  readonly onFullscreenChange: ((next: boolean) => void) | undefined;
  readonly close: () => unknown;
  readonly sheet: boolean;
  readonly floatChat: (() => void) | undefined;
  /** Every known version of the open artifact in this conversation, newest first. */
  readonly versions: readonly ArtifactDescriptor[];
  /** True while the panel follows the newest version; false when one older version is pinned. */
  readonly follow: boolean;
  /** `'latest'` follows the newest version; a descriptor from `versions` pins that one. */
  readonly select: (version: ArtifactDescriptor | 'latest') => void;
  /** Forward the viewer's actual loaded revision mount/unmount report. Opening or rendering the panel is not evidence. */
  readonly onShown: (shown: ArtifactShown) => void;
  /** Forward a viewer load/render failure; the waiting present is refused. */
  readonly onFailed: (failed: ArtifactFailed) => void;
}

/** The chat's own words an app may override through `agent.words`, next to the shell's (`AppShellText`): all of them are what the one composer shows. */
const CHAT_WORD_KEYS = ['placeholder', 'placeholderWorking', 'messageInput', 'send', 'sendHint', 'stop', 'queue', 'add', 'attachFiles', 'takePhoto', 'commands', 'retry', 'voiceStop', 'voiceCancel', 'emptyDescription'] as const;
export type AgentWords = Partial<AppShellText> & Partial<Pick<ChatLabels, (typeof CHAT_WORD_KEYS)[number]>> & {
  /** The empty conversation's title (« Conversation » by default). */
  readonly emptyTitle?: string;
};
/** The chat words an app gave in `agent.words`, as chat labels (`emptyTitle` is the chat's `title`). */
export const chatWordLabels = (words: AgentWords | undefined): Partial<ChatLabels> => {
  const labels: Record<string, string> = {};
  for (const key of CHAT_WORD_KEYS) { const word = words?.[key]; if (typeof word === 'string') labels[key] = word; }
  if (words?.emptyTitle) labels['title'] = words.emptyTitle;
  return labels as Partial<ChatLabels>;
};
/** The chat's words as this composer shows them: the locale's, then the app's `agent.words`. */
export const composerLabels = (locale: AppShellLocale | undefined, agent: AgentSpec | undefined): ChatLabels => ({ ...chatTextFor(locale ?? agent?.chatProps?.locale).labels, ...chatWordLabels(agent?.words) });

/** Compact: closed, peek, half or full. Expanded: closed or open. */
export type AgentLayerState = 'closed' | 'peek' | 'half' | 'full' | 'open';
export type Which = 'agent' | 'improve';
export type Snap = 'closed' | 'peek' | 'half' | 'full';
/** Where the one composer sits (`floatingComposer`): at the bottom of the page, floating over it (wide screens), or folded to a round icon. */
export type ComposerPlace = 'bottom' | 'float' | 'icon';
export type FloatCorner = 'tl' | 'tr' | 'bl' | 'br';
/** The floating bar's place: a corner (it stays there when the window resizes) or free, in px from the window's top left. */
export type FloatPos = { readonly corner: FloatCorner } | { readonly left: number; readonly top: number };
/** What the icon shows of the conversation: what is unread, and whether a decision waits for the person. */
/** What the app's feedback slot is given. */
export interface FeedbackSlotContext {
  /** Where the conversation is now (`folded`, `open`, `grown`, `full`, `docked`). */
  readonly level: Level;
  /** Takes the conversation to a level the launcher has (an app's own preview dock can fold the panel). */
  readonly setLevel: (level: Level) => void;
  /** The session's phase: `idle`, `active` (annotating), `processing`, or `review` (a finished draft). */
  readonly phase: string;
  /** The notes taken so far (the one being typed counts). */
  readonly count: number;
  /** Starts annotating, or ends it (Done): the same toggle as the built-in one, with point mode on a phone and Escape as a way out. */
  readonly annotate: () => void;
  readonly where: 'field' | 'title';
}
export type FeedbackSlot = ReactNode | ((context: FeedbackSlotContext) => ReactNode);
export interface ComposerSignals { readonly unread: { readonly label: string; readonly count?: number | undefined } | undefined; readonly needsYou: boolean; /** A run is under way: the folded icon pulses a ring round itself. */ readonly working?: boolean; /** Notes taken while annotating (the pointing tool): the circle and the tab show the count. */ readonly notes?: number }
export interface AgentLayerApi {
  readonly agent: NativeChatController | undefined;
  /** `floatingComposer`: where the one composer sits now. A phone never floats: `float` reads as `bottom` there. Always `bottom` without the prop. */
  readonly place: ComposerPlace;
  /** Moves the composer: to the bottom, floating (wide screens) or folded to its icon (the grown conversation is remembered and comes back with the icon's tap). No-op without `floatingComposer`. */
  readonly setPlace: (place: ComposerPlace) => void;
  readonly state: AgentLayerState;
  readonly showing: Which | null;
  /** Opens the assistant or the PM. Below `TOGETHER_FROM` (and on a phone) it closes the other; from it, the PM opens beside the assistant.
   * `at: 'dock'` opens the agent's conversation docked in the side column on a wide screen (what the tray's Dock does); on a phone it is `half`, and for the PM it is `half`. */
  open(which?: Which, at?: 'peek' | 'half' | 'full' | 'dock'): void;
  /** Closes what `showing` names: with both open, the assistant (a second call closes the PM). */
  close(): void;
  /** Open the real chat with one card mention. Call directly from a click or swipe release to grant microphone permission. False without an agent. */
  readonly talkAbout: (mention: string, options?: { readonly voice?: boolean; readonly at?: 'half' | 'full'; readonly add?: boolean }) => boolean;
  /** A short status in the field in place of the placeholder (« Draft saved », « 3 rows referenced »): it goes after 3 s or when the person types. Composer `bar`. */
  readonly status: (text: string) => void;
  /** The status on show, if any. */
  readonly fieldStatus: string | undefined;
  /** What the folded launcher carries: what is unread, a decision that waits, a run under way and the notes taken. A host can badge its own nav with it. */
  readonly signals: ComposerSignals;
  readonly expanded: boolean;
  /**
   * `composer: 'bar'` (D-2198): shows the app's preview of a file (dropped, attached or cited) in the right column, or full screen on a phone. The column holds one
   * thing at a time: a docked assistant goes back above the field (Ouvert) while the preview is open, and comes back when it closes. `null` closes it.
   * False (nothing shown) without `composer: 'bar'` or an agent.
   */
  readonly preview: (preview: AgentPreview | null) => boolean;
  /** `composer: 'bar'`: the right pane's back stack (`preview` is `pane.push`, `preview(null)` is `pane.close()`). */
  readonly pane: AgentPane;
}

/** What `useAgentLayer().pane.push` shows: the app's own view under its title, or a file the kit opens in its viewer (`AgentSpec.files`). */
export type PaneItem = AgentPreview | {
  readonly file: string;
  /** The back control's word for it (default: the file's name). */
  readonly title?: string | undefined;
  /** The set it was opened from (the files of one reply, a folder, a detail's attachments): previous and next step through it, « 2 / 5 ». */
  readonly files?: readonly string[] | undefined;
};

/** The right pane: one place with a back stack, whatever put content there (the app's detail views, a file, the library, the agent's `present`). */
export interface AgentPane {
  /** Shows `item` on top (opening the pane); its back control returns to what was under it, as it was. False when it cannot be shown. */
  push(item: PaneItem): boolean;
  /** One step back: the entry under the top, or the pane closes. */
  back(): void;
  /** Closes the pane, whatever it holds. */
  close(): void;
  /** How many entries the pane holds (0: closed). */
  readonly depth: number;
}

/** One entry of the pane's stack: what it shows, its title (the back control of the entry above says it) and the control that opened it (focus returns there). */
export type PaneEntry = { readonly id: number; readonly title: string; readonly opener: HTMLElement | null } & (
  | { readonly kind: 'view'; readonly content: ReactNode; readonly bare?: boolean }
  | { readonly kind: 'library'; readonly content: ReactNode }
  | { readonly kind: 'artifact'; readonly descriptor: ArtifactDescriptor; readonly follow: boolean }
  | { readonly kind: 'file'; readonly path: string; readonly files: readonly string[]; readonly revision?: string | undefined });

/** What `useAgentLayer().preview` shows: the app's own view of the file, under its title. */
export interface AgentPreview {
  readonly title: string;
  readonly content: ReactNode;
  /**
   * `false`: the pane draws no header of its own and `content` draws the one (a pi-app `FileViewer`, an editor with its own mode toggle and save state). The pane's
   * close and back reach it through `usePaneFrame()`: `<FileViewer onClose={close} onBack={back} backLabel={backLabel} … />`. Default: the pane's frame.
   */
  readonly frame?: false | undefined;
}

/** What a frameless pane entry (`frame: false`) wires into its own header: the pane's Fermer, and « ← <what is under> » when there is something to go back to. */
export interface PaneFrame {
  readonly close: () => void;
  /** Undefined when the entry is alone in a pane over no conversation (nothing to go back to). */
  readonly back: (() => void) | undefined;
  /** « Retour à <title> » (the back control's name). */
  readonly backLabel: string | undefined;
}
export const PaneFrameContext = createContext<PaneFrame | null>(null);
/** The standalone composer's pane window can take the whole screen: an `artifactPanel`'s full screen control reads and sets it. Absent: the pane has no full screen of its own. */
export const PaneFullscreenContext = createContext<{ readonly fullscreen: boolean; readonly set: (next: boolean) => void } | null>(null);
/** Inside `preview({ frame: false, content })`: the pane's close and back for the content's own header; a no-op frame elsewhere. */
export function usePaneFrame(): PaneFrame {
  return useContext(PaneFrameContext) ?? { close: () => {}, back: undefined, backLabel: undefined };
}
// The three fixed snap points: a peek (the file chip, one composer row and a line of the last reply, `PEEK_REM` above the tab bar), 55% and the full height.
export const PEEK_REM = 8;
/** `composer: 'bar'` (AC-20, mockup l-6): the peek is the one field and the handle, no line of the thread. */
export const PEEK_BAR_REM = 6;
/** The shell's z-scale (tabs 20, peek 30, drawer and panel 40, other sheets 50, point bar 60). */
export const Z = { tabs: 20, peek: 30, layer: 40, sheet: 50, point: 60 } as const;
export const HALF = 0.55;
export const FULL = 1;
/** Hold the trigger this long before it records; shorter is a tap. */
export const HOLD_MS = 350;
/**
 * From this width the assistant dock and the PM column are open together: the expanded sidebar (the default `--sidebar-width`, 16rem) + the screen's least width
 * (`DockLayout`'s 360px) + the dock's least width (320px) + the PM column (26rem) = 1352px. Below it they are one at a time, as on a phone.
 * A media query cannot read `--sidebar-width`, so this stays a constant for the default 16rem. A narrower themed sidebar only adds room; a sidebar wider than 16.5rem (8px of slack) needs this raised.
 */
export const TOGETHER_FROM = 1360;
export const TOGETHER_QUERY = `(width >= ${TOGETHER_FROM}px)`;
/** The PM column's width in px (26rem): while it is open beside the dock, the dock leaves the screen its least width beside both. */
export const PM_COLUMN = 416;
export const MIN_MAIN = 360;
export type ComposerLauncher = 'bar' | 'circle' | 'tab' | 'header';
/** The normalised flags every consumer reads. */
export interface ResolvedComposer {
  readonly launcher: ComposerLauncher;
