          <div data-base-ui-swipe-ignore="" className="flex min-h-0 flex-1 flex-col"><ChatSlot /></div>
        </div>
      </BaseDrawerParts.Drawer.VirtualKeyboardProvider>
    </DrawerContent>
  </Drawer>;
