  const grown = size !== 'open';
  // The page keeps one wrapper whether the tray is open or not, so opening it never remounts the screen; Agrandir only hides it.
  return <div ref={setDropZone} data-testid="agent-content" data-bar-tray={bar && trayOpen && !anchored ? (grown ? 'expanded' : 'open') : undefined} className={cn('relative flex min-h-0 min-w-0 flex-1 flex-col', bar && '@container')}>
    <div data-testid="agent-page" className={cn('flex min-h-0 min-w-0 flex-1 flex-col', trayOpen && grown && !anchored && !bar && 'hidden')}>{children}</div>
    {bar ? <BarBox /> : <>
      {trayOpen && !anchored && <ContentTray />}
      <div ref={setComposerSlot} data-testid="agent-content-composer" className="shrink-0" />
    </>}
  </div>;
}

/**
 * The one composer's box where its place puts it (`floatingComposer`): at the bottom in the column's flow, floating over the page in its own frame, or folded to the icon (the box stays
 * mounted and hidden, so the field, its draft and the folded card keep their place and the unread count goes on). `standalone`: no column to sit in, so the bottom is the window's.
 */
export function BarBox({ standalone = false }: { readonly standalone?: boolean }) {
  const hostClass = useContext(ComposerClassContext);
  const { setComposerSlot, setCardSlot, trayOpen, anchored, folded, place, placeFocus: focusRef, composerSlot } = useInternal();
  const slots = <>
    {trayOpen && !anchored && <ContentTray />}
    <div ref={setCardSlot} data-testid="agent-card-slot" className={cn('shrink-0 empty:hidden', !anchored && 'relative z-raised bg-card')} />
    <div ref={setComposerSlot} data-testid="agent-content-composer" className={cn('shrink-0', !anchored && 'relative z-raised rounded-b-(--radius-3xl) bg-card', folded && FOLDED_FIELD)} />
  </>;
  // Moved by a person (Minimise, the icon's tap, Dock to the bottom): the field takes focus once it is drawn in its new place.
  useEffect(() => {
    if (place === 'icon' || !focusRef.current || !composerSlot) return;
    // The field is drawn into its new slot a frame or two after the slot exists (the slot itself may be replaced meanwhile: the flag stays up until the field has focus).
    let frames = 0, frame = 0;
    const land = () => {
      const field = composerSlot.querySelector<HTMLElement>('[data-testid=composer-input]');
      if (field) { focusRef.current = false; field.focus({ preventScroll: true }); }
      else if (++frames < 12) frame = requestAnimationFrame(land);
      else focusRef.current = false;
    };
    frame = requestAnimationFrame(land);
    return () => cancelAnimationFrame(frame);
  }, [place, focusRef, composerSlot]);
  if (place === 'float') return <FloatFrame><OneBox floating>{slots}</OneBox></FloatFrame>;
  if (place === 'icon') return <><div hidden><OneBox>{slots}</OneBox></div><ComposerFab /></>;
  return standalone ? <div className={cn('@container fixed inset-x-0 bottom-0 z-(--z-app-shell-layer)', hostClass)}><NoticeSlot /><OneBox>{slots}</OneBox></div> : <OneBox>{slots}</OneBox>;
}

/**
 * Where the app wants the assistant's field: place it in the column the field belongs under (for a page with an aside, the main column).
 * While mounted, `composer: 'content'` draws the field and the reply tray here instead of across the whole content column; a file drop stays on the whole column.
 * Absent, nothing changes. Still one controller and one composer; the page is not remounted. Renders nothing visible without a content composer.
 */
export function AgentComposerAnchor({ className }: { readonly className?: string }) {
  const layer = useContext(LayerContext);
  const [tray, setTray] = useState<HTMLElement | null>(null);
  const [field, setField] = useState<HTMLElement | null>(null);
  const [card, setCard] = useState<HTMLElement | null>(null);
  const setAnchor = layer?.setAnchor;
  useLayoutEffect(() => {
    if (!setAnchor || !tray || !field || !card) return;
    setAnchor({ tray, field, card });
    return () => setAnchor(null);
  }, [setAnchor, tray, field, card]);
  if (!layer) return null;
  const slots = <>
    <div ref={setTray} data-testid="agent-anchor-tray" className="flex min-w-0 flex-col">{layer.trayOpen && layer.anchored && <ContentTray />}</div>
    <div ref={setCard} data-testid="agent-anchor-card" className="shrink-0 empty:hidden" />
    <div ref={setField} data-testid="agent-anchor-composer" className={cn('shrink-0', layer.folded && FOLDED_FIELD)} />
  </>;
  return <div data-testid="agent-composer-anchor" className={cn('flex min-w-0 shrink-0 flex-col', className)}>{layer.bar && layer.contentComposer ? <OneBox>{slots}</OneBox> : slots}</div>;
}

/**
 * The reply as a tray just above the field (`composer: 'content'`, wide, the person's default): the desktop twin of the phone's peek to half.
 * The same thread and controller as the dock and the drawer, moved here; its width is the field's, its height min(35%, 360px) of the column,
 * and the page above it shrinks instead of being covered. The unanchored bar reserves that page space with padding and slides a fixed-height surface.
 * No second composer: the field below stays the only input.
 */
function ContentTray() {
  const layer = useInternal();
  const { text, title } = useTitle();
  const { size, setSize, side, moveToDock } = layer;
  const grown = size !== 'open';
  const DockIcon = side === 'left' ? PanelLeftIcon : PanelRightIcon;
  const dockLabel = side === 'left' ? text.dockLeft : text.dockRight;
  const reduce = useCallback(() => {
    layer.close();
    layer.composerSlot?.querySelector<HTMLElement>('[data-testid=composer-input]')?.focus({ preventScroll: true });
  }, [layer]);
  const reduceRef = useRef(reduce);
  useLayoutEffect(() => { reduceRef.current = reduce; });
  // Esc goes back to the bare field, unless something else owns it: an open menu, dialog or popup, an IME composition, a handled key.
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.defaultPrevented || event.isComposing || event.keyCode === 229 || escapeInFeedback(event)) return;
      // Only a key pressed in the tray, in the one field or on the controller strip is the tray's; a host dock beside the content, a menu or a dialog keep their own Esc.
      if (!(event.target instanceof Element) || !event.target.closest('[data-testid=agent-tray], [data-testid=agent-content-composer], [data-testid=agent-composer-anchor], [data-testid=composer-controller]')) return;
      if (document.querySelector('[role=menu],[role=listbox],[role=dialog],[role=alertdialog],[data-boring-overlay]')) return;
      if (event.target instanceof Element && event.target.closest('[aria-haspopup][aria-expanded=true]')) return;
      event.preventDefault();
      reduceRef.current();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  // In an anchor the tray sits in the app's column, whose height is not the content column's: a share of the viewport, and Agrandir takes more of it instead of hiding the page.
  const boxed = layer.bar && layer.contentComposer;
  const overlay = boxed && !layer.anchored;
  const height = boxed ? (grown ? '70dvh' : '30dvh') : layer.anchored ? (grown ? 'min(70dvh, 720px)' : `min(35dvh, ${TRAY_MAX}px)`) : grown ? undefined : `min(35%, ${TRAY_MAX}px)`;
  const tray = <section data-testid="agent-tray" data-overlay={overlay || undefined} data-expanded={boxed && grown || undefined} aria-label={title} style={height ? { height: overlay ? 'var(--app-shell-bar-tray-size)' : height } : undefined}
    className={cn('flex min-h-0 min-w-0 flex-col', overlay ? 'pointer-events-auto absolute inset-x-0 top-0 transition-transform duration-(--duration-fast) ease-(--ease-standard) motion-reduce:transition-none' : 'relative bg-card', boxed ? 'shrink-0 px-3 text-card-foreground' : 'px-4 text-card-foreground', !boxed && (grown && !layer.anchored ? 'flex-1' : 'shrink-0'))}>
    {overlay && <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 h-(--app-shell-bar-tray-expanded) rounded-t-(--radius-3xl) bg-card" />}
    {boxed ? null : <Separator className="absolute inset-x-0 top-0" />}
    <div data-testid="agent-tray-body" className={cn('mx-auto flex min-h-0 w-full max-w-[720px] flex-col', overlay ? 'relative h-(--app-shell-bar-tray-expanded) shrink-0' : 'flex-1')}>
      <div data-testid="agent-tray-header" className="flex h-13 shrink-0 items-center gap-1.5">
        {layer.place === 'float' && <Grip />}
        <h2 data-testid="agent-tray-title" className="m-0 min-w-0 flex-1 truncate text-sm leading-5 font-semibold tracking-tight">{title}</h2>
        <HistoryButton />
        {layer.bar && <LibraryButton open={layer.openLibrary} text={text} testId="agent-layer-library" />}
        {layer.bar && <HeaderExtras text={text} compact={false} />}
        {boxed ? null : <>
          <OpenFullButton />
          <HeaderHint label={dockLabel}><Button variant="ghost" size="icon" data-testid={STRIP_ACTIONS.split.testId} aria-label={dockLabel} title={dockLabel}
            onClick={moveToDock}><DockIcon data-icon="inline-start" aria-hidden="true" /></Button></HeaderHint>
          <Button variant="ghost" size="icon" data-testid={STRIP_ACTIONS.more.testId} aria-label={text.expand} title={text.expand} aria-pressed={grown}
            onClick={() => setSize(grown ? 'open' : 'grown')}>{grown ? <ChevronDownIcon className="size-4" aria-hidden="true" /> : <ChevronUpIcon className="size-4" aria-hidden="true" />}</Button>
          <Button variant="ghost" size="icon" data-testid={STRIP_ACTIONS.reduce.testId} aria-label={text.collapse} title={text.collapse} onClick={reduce}><XIcon className="size-4" aria-hidden="true" /></Button>
        </>}
      </div>
      <VoiceProblem />
      <ChatSlot live={size !== 'full'} />
    </div>
    {boxed && !overlay && <Separator />}
  </section>;
  return overlay ? <div className="pointer-events-none absolute inset-x-0 bottom-full h-(--app-shell-bar-tray-expanded) overflow-hidden">{tray}</div> : tray;
}

/**
 * Wraps the app's content (placed once by the shell): on a wide screen the agent dock sits on its left or right and the content reflows,
 * or it floats over the content; on a phone this is only the content (the layer is the bottom drawer). Host concern: Pi has no layout.
 */
export function AgentDockLayout({ children }: { readonly children: ReactNode }): ReactElement {
  const layer = useInternal();
  const { title } = useTitle();
  const place = useExplorePlace();
  // `composer="explore"`: the panel takes the dock's place (`ExplorePanel`, closed by default); the dock stays only for an app that has no assistant of its own.
  const dock = layer.expanded && (layer.agent || layer.improve) && !place.active && !layer.circle ? <AgentDock side={layer.side} /> : null;
  // The PM column sits inside the main content: while it is open beside the dock, the dock leaves the screen its least width beside it.
  return <DockLayout storageKey={DOCK_KEY} persist="local" minMain={MIN_MAIN + (layer.besidePanel ? PM_COLUMN : 0)} {...(layer.bar ? { className: '@container/agent-layout' } : {})}>
    {layer.side === 'left' && dock}
    <DockMain>{layer.contentColumn ? <ContentColumn>{children}</ContentColumn> : children}</DockMain>
    {layer.bar && layer.expanded && layer.stack.length > 0 && !layer.paneStacked && <PaneDock assistant={title} />}
    {layer.side === 'right' && dock}
    {place.open && place.mode === 'push' && <ExplorePanel mode="push" />}
  </DockLayout>;
}

/**
 * The conversation over the whole viewport, wide screen (`composer: 'bar'`): the chat's persistent host moves here, to a fixed `inset-0` surface on the body,
 * so it covers the nav and the right pane. One header (back arrow, title, Close). The page behind is inert and does not scroll; Esc and the back arrow
 * go to `grown`, focus goes back to the control that opened it. The phone is not here: its drawer's full snap is this same `size`.
 */
function FullScreen() {
  const layer = useInternal();
  const { text, title } = useTitle();
  const root = useRef<HTMLDivElement>(null);
  const opener = useRef<HTMLElement | null>(typeof document === 'undefined' ? null : document.activeElement as HTMLElement | null);
  const { setFullField, close } = layer;
  const closing = useRef(false);
  const closeAll = useCallback(() => { closing.current = true; close(); }, [close]);
  // The conversation fills the main area, the rect the bar is centred on: the left navigation and the right pane stay beside it, visible and live.
  const [frame, setFrame] = useState<{ readonly left: number; readonly right: number; readonly top: number; readonly bottom: number }>({ left: 0, right: 0, top: 0, bottom: 0 });
  useLayoutEffect(() => {
    const main = document.querySelector<HTMLElement>('[data-boring=dock-main]');
    const measure = () => { if (!main) return; const r = main.getBoundingClientRect(); setFrame({ left: r.left, right: window.innerWidth - r.right, top: r.top, bottom: window.innerHeight - r.bottom }); };
    measure();
    const observer = main && typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : undefined;
    if (main) observer?.observe(main);
    window.addEventListener('resize', measure);
    return () => { observer?.disconnect(); window.removeEventListener('resize', measure); };
  }, []);
  const { leaveFull: back } = layer;
  const backRef = useRef(back);
  useLayoutEffect(() => { backRef.current = back; });
  useLayoutEffect(() => {
    const node = root.current;
    if (!node) return;
    const touched: Array<{ el: Element; inert: boolean; hidden: string | null }> = [];
    // Only what the conversation covers goes inert: the main area's page. The left navigation and the right pane stay beside it and live.
    for (const el of document.querySelectorAll('[data-boring=dock-main]')) {
      touched.push({ el, inert: (el as HTMLElement).inert, hidden: el.getAttribute('aria-hidden') });
      (el as HTMLElement).inert = true;
      el.setAttribute('aria-hidden', 'true');
    }
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    node.querySelector<HTMLElement>('[data-testid=composer-input]')?.focus({ preventScroll: true });
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.defaultPrevented || event.isComposing || event.keyCode === 229) return;
      if (document.querySelector('[role=menu],[role=listbox],[role=dialog]:not([data-testid=agent-full]),[role=alertdialog],[data-boring-overlay]')) return;
      if (event.target instanceof Element && event.target.closest('[aria-haspopup][aria-expanded=true]')) return;
      event.preventDefault();
      backRef.current();
    };
    document.addEventListener('keydown', onKey);
    const returnTo = opener.current;
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = overflow;
      for (const { el, inert, hidden } of touched) {
        (el as HTMLElement).inert = inert;
        if (hidden === null) el.removeAttribute('aria-hidden'); else el.setAttribute('aria-hidden', hidden);
      }
      // Back and Esc land on the opener (the strip's or the docked header's Full control when that is gone, which may mount a frame or two later).
      let frames = 0;
      const land = () => {
        const target = closing.current ? document.querySelector<HTMLElement>('[data-testid=composer-input]') : returnTo && returnTo !== document.body && returnTo.isConnected && returnTo.getClientRects().length > 0 ? returnTo : document.querySelector<HTMLElement>('[data-testid=agent-tray-full], [data-testid=agent-layer-full]');
        target?.focus({ preventScroll: true });
        if (document.activeElement !== target && ++frames < 12) requestAnimationFrame(land);
      };
      requestAnimationFrame(land);
    };
  }, []);
  return createPortal(
    <div ref={root} data-testid="agent-full" role="dialog" aria-modal="true" aria-label={title} style={frame} className="app-shell fixed z-fullscreen flex flex-col bg-card text-card-foreground">
      <div className="mx-auto flex min-h-0 w-full max-w-[720px] flex-1 flex-col">
        <Header text={text} title={title} controls={<HeaderHint label={text.close}><Button variant="ghost" size="icon" data-testid="agent-full-close" aria-label={text.close} onClick={closeAll}><XIcon data-icon="inline-start" aria-hidden="true" /></Button></HeaderHint>} />
        <VoiceProblem />
        <ChatSlot />
        <div data-one-dock="" className="shrink-0"><div ref={setFullField} data-testid="agent-full-composer" /></div>
      </div>
    </div>, document.body);
}

/** The layer itself: the drawer on a phone (the wide dock is `AgentDockLayout`). Placed once by the shell, for point mode on both. */
export function AgentLayer(): ReactElement | null {
  const layer = useInternal();
  const { title } = useTitle();
  const pointingAgent = usePointing(layer.agent?.feedback);
  // A circle's panel steps aside while annotating (`feedback.while`): like a phone's point mode, the layer then draws the note bubble and answers Back.
  const circleCollapsed = useCircleCollapsed();
  const session = pointingAgent || circleCollapsed ? layer.agent?.feedback : undefined;
  const commentingAgent = useCommenting(layer.agent?.feedback);
  const commenting = commentingAgent ? layer.agent?.feedback : undefined;
  // Back ends pointing first (the `point` priority), like Done: the notes wait for the next message. The layer keeps its own history entry underneath.
  useBackLayer(session !== undefined, () => { void session?.done(); }, 'point');
  const explore = useExplorePlace();
  useEscapeGuard();
  if (!layer.agent && !layer.improve) return null;
  const pointed = layer.agent;
  const transcribe = (pointed?.voice ?? layer.agent?.voice)?.transcribe;
  const locale = layer.locale ?? pointed?.chatProps?.locale;
  // Comment mode shows its banner either way: on a phone (point mode) above the tab bar, outside the layer, while the compact sheet steps
  // aside; on a wide screen at the top, the dock beside the app. The note bubble is here only while pointing (else inside the layer).
  return <>
    {explore.active && <><ExploreToggle /><ExploreController /></>}
    {explore.open && explore.mode === 'overlay' && <ExplorePanel mode="overlay" />}
    {layer.circle && <CircleHost />}
    {layer.expanded && layer.trayOpen && layer.size === 'full' && <FullScreen />}
    {!layer.expanded && layer.place !== 'icon' && !layer.suspended && <CompactSheet pointing={session !== undefined} />}
    {!layer.expanded && layer.place === 'icon' && !layer.suspended && <ComposerFab />}
    {layer.bar && !layer.expanded && layer.stack.length > 0 && <PaneStack placement="screen" assistant={title} />}
    {commenting && <CommentBanner session={commenting} bottomOffset={`${layer.tabbar}px`} className="z-toast" {...(locale === 'fr' ? { labels: feedbackLabelsFr } : {})} />}
    {session && <NoteBubble session={session} {...(transcribe ? { transcribe } : {})} {...(locale === 'fr' ? { labels: feedbackLabelsFr } : {})} />}
  </>;
}

'use client';

// The right pane (`composer: 'bar'`): one place with a back stack, whatever put content there: the app's own views (`pane.push({ title, content })`,
// `preview`), a file opened from a chip, the library or a page (`pane.push({ file })`, shown in the kit's `LocalFileViewer` through `agent.files`),
// and the agent's `present`. Data first: a stack of typed entries (`PaneEntry`), the top one last. The top one shows; the ones under it stay mounted,
// hidden, so back returns to them as they were (scroll, selection). Wide: the `preview` Dock on the right, or over the docked conversation in its
// column (« ← Assistant »). Phone: full screen, and the system Back steps back too. Every entry is drawn in the kit's `ViewerFrame`.
import { Suspense, lazy, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { PointerEvent as ReactPointerEvent, ReactNode } from 'react';
import { ArrowLeftIcon, LibraryIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { useArtifactFollow } from '@hachej/boring-ui-kit/chat-react';
import { mentionToken, pieces } from '@hachej/boring-ui-kit/chat-text';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { Dock } from '../dock/dock';
import { ViewerFrame, ViewerWindowProvider } from '../viewer-frame/viewer-frame';
import { frenchViewerLabels } from '../viewer-frame/viewer-labels-fr';
import type { LocalTextKind } from '../viewer-pdf/local-file-viewer';
import { codeKind, csvKind, svgKind } from '../viewer-code/code-kinds';
import { GROUP_AFTER, RowReferenceContext, referencedRows, rowKey, rowMentionPath } from '../viewer-code/row-reference';
import type { RowReferenceTarget } from '../viewer-code/row-reference';
import { StepButtons, stepIndex, stepOffset } from '../pi-chat/image-viewer';
import { useBackLayer } from '../utils/back';
import { cn } from '../utils/utils';
import type { ArtifactDescriptor, PresentedArtifact } from '../pi-artifacts/artifact';
import type { AppShellLocale, AppShellText } from './text';
import { shellWords, useInternal } from './layer-context';
import { PaneFrameContext, PaneFullscreenContext } from './layer-context';
import type { AgentPane, AgentSpec, FileKind, PaneEntry, PaneFrame, PaneItem, PanePresent } from './layer-context';

const MAX_DEPTH = 12;
const noSubscription = () => () => {};
type FileReader = NonNullable<AgentSpec['files']>['read'];
/** A new entry, before the stack gives it an id and its opener. */
type Draft = PaneEntry extends infer E ? E extends PaneEntry ? Omit<E, 'id' | 'opener'> : never : never;
const nameOf = (path: string) => path.split('/').at(-1) || path;

/** A Markdown file read as a note, with the chat's own renderer (no editor: the bytes are the app's, read only). */
const markdownKind: LocalTextKind = {
  match: (_target, artifact) => artifact.type === 'markdown',
  load: () => import('../pi-chat-markdown/markdown').then(module => ({ default: ({ text }: { readonly text: string }) => <div data-testid="pane-markdown" className="pi-chat text-sm"><module.Markdown text={text} /></div> })),
};
const TEXT_KINDS: readonly LocalTextKind[] = [csvKind, svgKind, codeKind, markdownKind];
/** The host's artifact kinds as text kinds of the file viewer, ahead of the pane's own (a `.diagram.json` is JSON text, a `.mockup.html` HTML text). */
const withKinds = (kinds: readonly FileKind[] | undefined): readonly LocalTextKind[] => [
  ...(kinds ?? []).map(kind => ({ match: (target: { readonly resource: { readonly path: string } }) => kind.match(target), load: async () => ({ default: ({ text, artifact }: { readonly text: string; readonly artifact: { readonly title: string } }) => <>{kind.renderer({ text, title: artifact.title })}</> }) })), ...TEXT_KINDS];
let readyFileViewer: typeof import('../viewer-pdf/local-file-viewer').LocalFileViewer | undefined;
const loadFileViewer = () => import('../viewer-pdf/local-file-viewer').then(module => {
  readyFileViewer = module.LocalFileViewer;
  return { default: module.LocalFileViewer };
});
const LocalFileViewer = lazy(loadFileViewer);

/** The files cited or attached in the message that names `path` (the latest one): the set previous and next step through. */
export function citedWith(controller: NativeChatController | undefined, path: string): readonly string[] {
  const entries = controller?.getSnapshot().view?.entries ?? [];
  for (let at = entries.length - 1; at >= 0; at -= 1) {
    for (const message of entries[at]!.model ?? []) {
      const content = (message as { readonly content?: unknown }).content;
      const text = typeof content === 'string' ? content : Array.isArray(content) ? content.map(part => (part as { readonly type?: string; readonly text?: string }).type === 'text' ? (part as { readonly text: string }).text : '').join('\n') : '';
      const files = [...new Set(pieces(text, { mentions: true, skills: [] }).flatMap(piece => piece.kind === 'mention' && piece.value && !/^[a-z][\w-]*:/i.test(piece.value) ? [piece.value] : []))];
      if (files.includes(path)) return files;
    }
  }
  return [path];
}

interface Persisted { readonly kind: 'file' | 'library'; readonly title: string; readonly path?: string; readonly files?: readonly string[] }

/**
 * The pane's state and its verbs, held by the provider: `push`, `back` and `close`, the library, a file from the chat, previous and next, the
 * agent's `present` (useArtifactFollow: a presented file opens on top, the viewer's mount acknowledges it), focus, Échap, ← →, the phone's Back,
 * and the file and library entries kept across a reload (sessionStorage).
 */
export function usePane({ agent, bar, compact, locale, field, storageKey, uncover }: {
  readonly agent: AgentSpec | undefined; readonly bar: boolean; readonly compact: boolean; readonly locale: AppShellLocale | undefined;
  /** A phone: the conversation steps down to its peek (the field over the pane's foot), so the pane opened from it shows. */
  readonly uncover: () => void;
  /** The one field, where focus lands when the pane closes and its opener is gone. */
  readonly field: () => HTMLElement | null | undefined;
  readonly storageKey: string;
}) {
  const [stack, setStack] = useState<readonly PaneEntry[]>([]);
  // What was last asked, set at once (not after the render): a pick in the library that opens a file and then calls `onPicked` sees the file.
  const latest = useRef(stack);
  const ids = useRef(0);
  const focusPlan = useRef<{ readonly to: 'top' } | { readonly to: 'same'; readonly testId: string } | { readonly to: 'element'; readonly element: HTMLElement | null; readonly fallback: 'top' | 'field' } | null>(null);
  const commit = useCallback((next: readonly PaneEntry[], plan: typeof focusPlan.current) => { latest.current = next; focusPlan.current = plan; setStack(next); }, []);
  const files = agent?.files;
  useEffect(() => {
    if (!bar || !files) return;
    // Warm module code together, without reading host files, so opening a CSV does not wait on two successive lazy imports.
    void loadFileViewer().catch(() => {});
    void csvKind.load().catch(() => {});
  }, [bar, files]);
  const opener = () => document.activeElement instanceof HTMLElement && document.activeElement !== document.body ? document.activeElement : null;

  // Opening the pane leaves the conversation as it is (folded stays folded): the page keeps its place, the one field stays where it was.
  const pushEntry = useCallback((entry: Draft, focus = true): number => {
    const current = latest.current;
    const top = current.at(-1);
    // The same thing again replaces the top (an app updating its view, the agent presenting the file on show), so back never shows it twice.
    const same = top && top.kind === entry.kind && (entry.kind === 'file' ? top.kind === 'file' && top.path === entry.path : entry.kind === 'artifact' ? top.kind === 'artifact' && top.descriptor.target.resource.path === entry.descriptor.target.resource.path : top.title === entry.title);
    const next = { ...entry, id: same ? top.id : ++ids.current, opener: same ? top.opener : opener() } as PaneEntry;
    // Focus follows a person's open of something new; an update of what is on top, or the agent's auto-open, leaves it where it is.
    commit([...(same ? current.slice(0, -1) : current), next].slice(-MAX_DEPTH), same || !focus ? null : { to: 'top' });
    if (compact) uncover();
    return next.id;
  }, [commit, compact, uncover]);
  const pushNow = useCallback((item: PaneItem): boolean => {
    if (!agent || !bar) return false;
    if ('content' in item) return pushEntry({ kind: 'view', title: item.title, content: item.content, ...(item.frame === false ? { bare: true } : {}) }) > 0;
    if (!files) return false;
    const set = item.files?.includes(item.file) ? item.files : [item.file];
    return pushEntry({ kind: 'file', title: item.title ?? nameOf(item.file), path: item.file, files: set }) > 0;
  }, [agent, bar, files, pushEntry]);
  // `push` keeps one identity for the life of the provider (an app's `useEffect(() => { preview(x); return () => preview(null) }, [preview])` must not loop): it calls the latest `pushNow`.
  const pushRef = useRef(pushNow);
  useLayoutEffect(() => { pushRef.current = pushNow; });
  const push = useCallback((item: PaneItem) => pushRef.current(item), []);
  const back = useCallback((): number => {
    const current = latest.current;
    const popped = current.at(-1);
    if (!popped) return 0;
    const next = current.slice(0, -1);
    commit(next, { to: 'element', element: popped.opener, fallback: next.length ? 'top' : 'field' });
    return next.length;
  }, [commit]);
  const close = useCallback(() => {
    const first = latest.current[0];
    if (first) commit([], { to: 'element', element: first.opener, fallback: 'field' });
  }, [commit]);
  const step = useCallback((offset: -1 | 1) => {
    const current = latest.current, top = current.at(-1);
    if (top?.kind !== 'file' || top.files.length < 2) return;
    const path = top.files[stepIndex(Math.max(0, top.files.indexOf(top.path)), offset, top.files.length)]!;
    // The viewer is drawn again for the new file: focus stays on the control that stepped (previous, next), else on nothing new (keys keep working).
    const held = document.activeElement instanceof HTMLElement && document.activeElement.closest('[data-pane-top]') ? document.activeElement.dataset['testid'] : undefined;
    commit([...current.slice(0, -1), { ...top, id: ++ids.current, path, title: nameOf(path), revision: undefined }], held ? { to: 'same', testId: held } : null);
  }, [commit]);

  // « Bibliothèque »: the app's navigator on top; a file the app (or the kit, from `onPicked({ path })`) opens goes above it, `onPicked()` alone closes it.
  const library = agent?.library;
  const words = shellWords(locale, agent);
  const libraryTitle = words.library;
  const libraryContent = useCallback(() => {
    if (!library) return null;
    let mine = -1;
    const content = library(file => {
      if (file && push({ file: file.path, files: file.files })) return;
      if (latest.current.at(-1)?.id === mine) back();
    });
    return { content, claim: (id: number) => { mine = id; } };
  }, [library, push, back]);
  const openLibrary = useMemo(() => {
    if (!library || !bar) return undefined;
    return () => {
      const made = libraryContent();
      if (!made) return;
      made.claim(pushEntry({ kind: 'library', title: libraryTitle, content: made.content }));
    };
  }, [library, bar, libraryContent, pushEntry, libraryTitle]);
  const chat = agent?.controller;
  const showFile = useCallback((path: string, set?: readonly string[]) => { push({ file: path, files: set ?? citedWith(chat, path) }); }, [push, chat]);
  const openFile = files && bar ? showFile : undefined;

  // The agent's `present`, and a card the person clicks: the file goes on top; the viewer's mount acknowledges it.
  const artifactPanel = agent?.artifactPanel;
  const hostArtifacts = agent?.chatProps?.artifacts;
  // The pane draws artifacts when it can (a file reader, the host's panel); a host that routes artifacts itself (`chatProps.artifacts`) still gets the present acknowledgements from here.
  const inPane = Boolean(files || artifactPanel);
  const hostOnly = Boolean(hostArtifacts) && !inPane;
  const controller = bar && (inPane || hostArtifacts) ? agent?.controller : undefined;
  const conversations = agent?.chatProps?.conversations;
  const top = stack.at(-1);
  const onTop = useCallback((path: string) => { const shown = latest.current.at(-1); return (shown?.kind === 'file' && shown.path === path) || (shown?.kind === 'artifact' && shown.descriptor.target.resource.path === path); }, []);
  // `artifactPanel`: the host's viewer draws the artifact (with its versions), the kit's file viewer is for files.
  const active = top?.kind === 'artifact' ? { descriptor: top.descriptor, follow: top.follow } : null;
  const presentFile = useCallback((artifact: PresentedArtifact, focus = true, follow = true) => {
    if (artifact.type === 'task') return false;
    const path = artifact.target.resource.path;
    if (artifactPanel) pushEntry({ kind: 'artifact', title: artifact.title || nameOf(path), descriptor: artifact, follow }, focus);
    else pushEntry({ kind: 'file', title: artifact.title || nameOf(path), path, files: [path], revision: artifact.revision }, focus);
    return true;
  }, [pushEntry, artifactPanel]);
  const follow = useArtifactFollow({ controller, conversationId: controller ? String(conversations?.activeId ?? controller.getSnapshot().conversationId) : undefined, active,
    onOpen: selection => { if (inPane) presentFile(selection.descriptor, !selection.follow, selection.follow); }, autoOpen: inPane, narrow: () => compact, showing: hostOnly ? () => true : onTop,
    ...(hostOnly ? { showingTask: () => true } : {}),
    openPresent: path => files ? pushEntry({ kind: 'file', title: nameOf(path), path, files: [path] }) > 0 : false,
    answer: agent?.chatProps?.actions?.answer as Parameters<typeof useArtifactFollow>[0]['answer'] });
  const { onShown, onFailed, open: followOpen, select, known } = follow;
  const presented = useMemo<PanePresent | undefined>(() => controller ? {
    open: artifact => { if (artifactPanel && artifact.type !== 'task') followOpen(artifact); else presentFile(artifact); },
    isOpen: artifact => artifact.type !== 'task' && onTop(artifact.target.resource.path),
    shown: onShown,
    failed: onFailed,
    select,
    versions: known.filter((version): version is ArtifactDescriptor => version.type !== 'task'),
  } : undefined, [controller, artifactPanel, presentFile, followOpen, onTop, onShown, onFailed, select, known]);

  // Focus: an entry's heading when it opens; back to the control that opened what closed (else the heading under it, or the field).
  useEffect(() => {
    const plan = focusPlan.current;
    focusPlan.current = null;
    if (!plan) return;
    const frame = requestAnimationFrame(() => {
      const heading = () => {
        const title = document.querySelector<HTMLElement>('[data-testid=agent-preview] [data-pane-top] [data-testid=agent-preview-title]');
        if (title && !title.hasAttribute('tabindex')) title.tabIndex = -1;
        return title;
      };
      const visible = (element: HTMLElement | null) => element?.isConnected && element.getClientRects().length > 0 && !element.closest('[inert]') ? element : null;
      const target = plan.to === 'top' ? heading() : plan.to === 'same' ? document.querySelector<HTMLElement>(`[data-pane-top] [data-testid="${plan.testId}"]`) ?? heading() : visible(plan.element) ?? (plan.fallback === 'top' ? heading() : field());
      target?.focus({ preventScroll: true });
    });
    return () => cancelAnimationFrame(frame);
  }, [stack, field]);
  // Échap steps back (the field's own Échap, an open menu, list or dialog keep theirs); ← and → step through the set, never while typing or on a divider.
  const depth = stack.length;
  const stepping = top?.kind === 'file' && top.files.length > 1;
  useEffect(() => {
    if (!depth) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing || event.altKey || event.ctrlKey || event.metaKey) return;
      const target = event.target instanceof Element ? event.target : null;
      // The pane's own keys: from inside it, or with nothing focused. A field or a control elsewhere on the page keeps its keys.
      const active = document.activeElement;
      if (!(target?.closest('[data-testid=agent-preview]') || (!active || active === document.body))) return;
      if (event.key === 'Escape') {
        if (target?.closest('[data-testid=composer-input]') || document.querySelector('[data-testid=conversations], [role=alertdialog], [role=dialog]:not([data-testid=agent-layer])') || target?.closest('[role=menu], [role=listbox]')) return;
        event.preventDefault(); back(); return;
      }
      const offset = stepping ? stepOffset(event.key) : undefined;
      if (!offset || target?.closest('input, textarea, select, video, audio, [contenteditable]:not([contenteditable=false]), [role=separator], [role=slider], [role=tree], [role=treegrid], [role=listbox], [role=menu], [role=tablist], [role=radiogroup]')) return;
      event.preventDefault(); step(offset);
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [depth, stepping, back, step]);
  // A phone's Back steps back one entry; the entry stays while more are under it.
  useBackLayer(compact && depth > 0, () => back() > 0 ? false : undefined, 'artifact');

  // The file and library entries survive a reload (an app's own view cannot be kept: it is the app's to rebuild).
  const restored = useRef(false);
  useLayoutEffect(() => {
    if (restored.current || !agent || !bar) return;
    restored.current = true;
    let saved: readonly Persisted[] = [];
    try { saved = JSON.parse(globalThis.sessionStorage?.getItem(storageKey) ?? '[]') as Persisted[]; } catch { /* a convenience */ }
    const entries = saved.flatMap((item): PaneEntry[] => {
      if (item.kind === 'file' && files && typeof item.path === 'string') return [{ id: ++ids.current, opener: null, kind: 'file', title: item.title, path: item.path, files: item.files ?? [item.path] }];
      const made = item.kind === 'library' ? libraryContent() : null;
      if (!made) return [];
      made.claim(ids.current + 1);
      return [{ id: ++ids.current, opener: null, kind: 'library', title: item.title, content: made.content }];
    });
    if (entries.length) commit(entries, null);
  }, [agent, bar, files, libraryContent, storageKey, commit]);
  useEffect(() => {
    if (!restored.current) return;
    const kept: Persisted[] = stack.flatMap((entry): Persisted[] => entry.kind === 'file' ? [{ kind: 'file', title: entry.title, path: entry.path, files: entry.files }] : entry.kind === 'library' ? [{ kind: 'library', title: entry.title }] : []);
    try { if (kept.length) globalThis.sessionStorage?.setItem(storageKey, JSON.stringify(kept)); else globalThis.sessionStorage?.removeItem(storageKey); } catch { /* a convenience */ }
  }, [stack, storageKey]);
  // The pane goes with the agent it was opened beside.
  useEffect(() => { if (!agent && latest.current.length) commit([], null); }, [agent, commit]);

  const verbs = useMemo(() => ({ push, back: () => { back(); }, close }), [push, back, close]);
  const pane = useMemo<AgentPane>(() => ({ ...verbs, depth }), [verbs, depth]);
  return { stack, pane, verbs, openLibrary, openFile, step, presented };
}

/** The back control: « ← <what is under> », or « ← Assistant » over the docked conversation. */
function BackButton({ title, text, onBack, testId }: { readonly title: string; readonly text: AppShellText; readonly onBack: () => void; readonly testId: string }) {
  return <Button variant="ghost" size="icon-sm" data-testid={testId} aria-label={`${text.backTo} ${title}`} title={`${text.backTo} ${title}`} onClick={onBack}>
    <ArrowLeftIcon data-icon="inline-start" aria-hidden="true" /></Button>;
}

/** Previous and next through the top file's set, with its position (« 2 / 5 »): the same buttons as the chat's image viewer. */
function FileSteps({ entry, text, onStep }: { readonly entry: Extract<PaneEntry, { kind: 'file' }>; readonly text: AppShellText; readonly onStep: (offset: -1 | 1) => void }) {
  if (entry.files.length < 2) return null;
  return <div data-testid="file-steps" className="flex items-center gap-1">
    <span data-testid="file-position" aria-live="polite" className="px-1 text-xs tabular-nums text-muted-foreground">{entry.files.indexOf(entry.path) + 1} / {entry.files.length}</span>
    <StepButtons count={entry.files.length} onStep={onStep} labels={{ previous: text.previousFile, next: text.nextFile }} testId="file" />
  </div>;
}

/**
 * The viewer replaces the « Ouverture… » frame once it has loaded: focus that sat on that frame's heading (and fell to the body with it) moves to
 * the viewer's. Inside the viewer's Suspense, so it runs only once the viewer is committed.
 */
function RefocusTitle() {
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      if (document.activeElement && document.activeElement !== document.body) return;
      const title = document.querySelector<HTMLElement>('[data-testid=agent-preview] [data-pane-top] [data-testid=agent-preview-title]');
      if (title && !title.hasAttribute('tabindex')) title.tabIndex = -1;
      title?.focus({ preventScroll: true });
    });
    return () => cancelAnimationFrame(frame);
  }, []);
  return null;
}

/** A file entry: its bytes read through `agent.files`, shown by `LocalFileViewer`; once shown, a presented revision is acknowledged. */
function FileEntry({ entry, frame, read, onShown, fileKinds, rows }: { readonly entry: Extract<PaneEntry, { kind: 'file' }>; readonly frame: { readonly id: string; readonly headerStart: ReactNode; readonly controls: ReactNode; readonly onClose: () => void; readonly text: AppShellText };
  readonly read: FileReader; readonly onShown: PanePresent['shown'] | undefined; readonly fileKinds: readonly FileKind[] | undefined; readonly rows: RowReferenceTarget | null }) {
  const kinds = useMemo(() => withKinds(fileKinds), [fileKinds]);
  const [loaded, setLoaded] = useState<{ readonly path: string; readonly blob: Blob | null; readonly revision?: string | undefined }>();
  useEffect(() => {
    let live = true;
    read(entry.path).then(found => { if (live) setLoaded(found instanceof Blob ? { path: entry.path, blob: found } : { path: entry.path, blob: found.blob, revision: found.revision }); },
      () => { if (live) setLoaded({ path: entry.path, blob: null }); });
    return () => { live = false; };
  }, [read, entry.path]);
  const file = loaded?.path === entry.path ? loaded : undefined;
  const blob = file?.blob;
  const path = entry.path, revision = entry.revision ?? file?.revision;
  useEffect(() => {
    if (!blob || !revision || !onShown) return;
    onShown({ path, revision });
    return () => onShown({ path, revision, hidden: true });
  }, [blob, path, revision, onShown]);
  const { id, headerStart, controls, onClose, text } = frame;
  const waiting = <ViewerFrame title={entry.title} testId={id} titleTestId={`${id}-title`} headerStart={headerStart} controls={controls} onClose={onClose}>
    <p role="status" data-testid={`${id}-status`} className="m-0 p-4 text-sm text-muted-foreground">{blob === null ? text.fileUnavailable : text.fileLoading}</p>
  </ViewerFrame>;
  if (!blob) return waiting;
  const Viewer = readyFileViewer ?? LocalFileViewer;
  return <Suspense fallback={waiting}><RowReferenceContext.Provider value={rows}><Viewer key={path} name={path} blob={blob} kinds={kinds} testId={id} titleTestId={`${id}-title`} headerStart={headerStart} controls={controls} onClose={onClose} /></RowReferenceContext.Provider>{id === 'agent-preview' && <RefocusTitle key={path} />}</Suspense>;
}

/**
 * One entry in the kit's viewer frame: the back control, the title, previous and next, « Bibliothèque », Fermer. Only the top entry carries the
 * pane's test ids (`agent-preview-title`, `-close`, `-back`); an entry under it keeps its place as `agent-preview-under-*`.
 */
function EntryView({ entry, below, top, placement, assistant }: { readonly entry: PaneEntry; readonly below: PaneEntry | undefined; readonly top: boolean; readonly placement: 'column' | 'stacked' | 'screen'; readonly assistant: string }) {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const id = top ? 'agent-preview' : 'agent-preview-under';
  const backTitle = below?.title ?? (placement === 'stacked' ? assistant : undefined);
  const headerStart = backTitle ? <BackButton title={backTitle} text={text} onBack={layer.pane.back} testId={`${id}-back`} /> : undefined;
  // A table file offers « @ » on each row when the app's chat has mentions: each row goes to the field as a `row` mention after the ones already there (the same
  // `talkAbout` path as a quoted page entry, with `add`); more than GROUP_AFTER new rows at once are one grouped chip.
  const { talkAbout, status } = layer, controller = layer.agent?.controller, hasMentions = layer.agent?.chatProps?.mentions !== undefined, filePath = entry.kind === 'file' ? entry.path : undefined;
  const draft = useSyncExternalStore(controller?.subscribe ?? noSubscription, () => controller?.getSnapshot().draft.text ?? '');
  const referenced = useMemo(() => referencedRows(draft), [draft]);
  const rows = useMemo<RowReferenceTarget | null>(() => hasMentions && filePath ? {
    path: filePath, referenced,
    words: { reference: text.referenceInAgent, referenced: text.referencedInAgent, referenceRows: text.referenceRows, selectRow: text.selectRow, clearSelection: text.clearSelection },
    reference: chosen => {
      const fresh = chosen.filter(item => !referenced.has(rowKey(filePath, item.row)));
      const groups = fresh.length > GROUP_AFTER ? [fresh] : fresh.map(item => [item]);
      for (const group of groups) talkAbout(mentionToken(rowMentionPath({ path: filePath, rows: group })), { add: true });
      if (fresh.length) status(text.rowsReferenced.replace('{n}', String(fresh.length)));
    },
  } : null, [hasMentions, filePath, referenced, talkAbout, status, text]);
  const library = entry.kind === 'view' && layer.openLibrary ? [{ id: 'library', label: text.library, icon: LibraryIcon, onSelect: layer.openLibrary, placement: 'header' as const }] : undefined;
  if (entry.kind === 'file' && layer.agent?.files) {
    // A phone folds a frame's controls into its « … » menu: there previous and next sit under the file instead.
    const steps = <FileSteps entry={entry} text={text} onStep={layer.step} />;
    return <>
      <div className="flex min-h-0 flex-1 flex-col"><FileEntry entry={entry} read={layer.agent.files.read} onShown={layer.presented?.shown} fileKinds={layer.agent.fileKinds} rows={rows} frame={{ id, headerStart, controls: placement === 'screen' ? undefined : steps, onClose: layer.pane.close, text }} /></div>
      {placement === 'screen' && entry.files.length > 1 && <div className="flex shrink-0 justify-center px-2 py-1">{steps}</div>}
    </>;
  }
  if (entry.kind === 'artifact' && layer.agent?.artifactPanel && layer.presented) {
    return <ArtifactEntry entry={entry} panel={layer.agent.artifactPanel} presented={layer.presented} id={id} placement={placement} close={layer.pane.close} />;
  }
  if (entry.kind === 'view' && entry.bare) {
    // The content draws its own header (`preview({ frame: false })`): the pane gives it its close and back, and a heading-less region name.
    const frame: PaneFrame = { close: layer.pane.close, back: backTitle ? layer.pane.back : undefined, backLabel: backTitle ? `${text.backTo} ${backTitle}` : undefined };
    return <PaneFrameContext.Provider value={frame}><div data-testid={`${id}-content`} data-bare="" className="flex min-h-0 flex-1 flex-col overflow-hidden text-sm [:where(&_*)]:border-border">{entry.content}</div></PaneFrameContext.Provider>;
  }
  return <ViewerFrame title={entry.title} testId={id} titleTestId={`${id}-title`} headerStart={headerStart} {...(library ? { actions: library } : {})} onClose={layer.pane.close}>
    {entry.kind === 'file' || entry.kind === 'artifact' ? null : <div data-testid={entry.kind === 'library' ? `${id}-library-list` : `${id}-content`} className="flex min-h-0 flex-1 flex-col overflow-auto text-sm [:where(&_*)]:border-border">{entry.content}</div>}
  </ViewerFrame>;
}

/** An artifact the host's `artifactPanel` draws: its own bar (close, full screen, versions), given the pane's controls and the versions of what is on show. */
function ArtifactEntry({ entry, panel, presented, id, placement, close }: { readonly entry: Extract<PaneEntry, { kind: 'artifact' }>; readonly panel: NonNullable<AgentSpec['artifactPanel']>; readonly presented: PanePresent;
  readonly id: string; readonly placement: 'column' | 'stacked' | 'screen'; readonly close: () => void }) {
  const wide = useContext(PaneFullscreenContext);
  const sheet = placement === 'screen';
  const shown = entry.follow ? presented.versions[0] ?? entry.descriptor : entry.descriptor;
  return <div data-testid={`${id}-content`} data-bare="" className="flex min-h-0 flex-1 flex-col overflow-hidden text-sm [:where(&_*)]:border-border">
    {panel(shown, { fullscreen: wide?.fullscreen ?? false, onFullscreenChange: sheet || !wide ? undefined : wide.set, close, sheet, floatChat: undefined,
      versions: presented.versions, follow: entry.follow, select: presented.select, onShown: presented.shown, onFailed: presented.failed })}
  </div>;
}

/** A touch swipe across the pane steps to the previous or next file (a pinch or a zoomed image keeps its own gestures). */
function useSwipe(onStep: (offset: -1 | 1) => void, enabled: boolean) {
  const start = useRef<{ readonly x: number; readonly y: number; readonly id: number } | null>(null);
  return enabled ? {
    onPointerDown: (event: ReactPointerEvent) => { start.current = event.pointerType === 'touch' && event.isPrimary ? { x: event.clientX, y: event.clientY, id: event.pointerId } : null; },
    onPointerUp: (event: ReactPointerEvent) => {
      const from = start.current;
      start.current = null;
      if (!from || from.id !== event.pointerId || (event.target instanceof Element && event.target.closest('[data-scale]:not([data-scale="1"])'))) return;
      const dx = event.clientX - from.x, dy = event.clientY - from.y;
      if (Math.abs(dx) > 64 && Math.abs(dx) > Math.abs(dy) * 1.5) onStep(dx < 0 ? 1 : -1);
    },
    onPointerCancel: () => { start.current = null; },
  } : {};
}

/**
 * The pane: every entry mounted, the top one shown. `column` is the wide Dock, `stacked` over the docked conversation, `screen` the phone: the whole
 * screen above the page, leaving the tabs visible under the conversation's drawer, whose peek (the one field) stays over the pane's foot.
 */
export function PaneStack({ placement, assistant }: { readonly placement: 'column' | 'stacked' | 'screen'; readonly assistant: string }) {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const { stack } = layer;
  const top = stack.at(-1);
  const fr = (layer.locale ?? layer.agent?.chatProps?.locale) === 'fr';
  const swipe = useSwipe(layer.step, placement === 'screen' && top?.kind === 'file' && top.files.length > 1);
  const viewer = useMemo(() => fr ? { labels: frenchViewerLabels } : {}, [fr]);
  if (!top) return null;
  return <ViewerWindowProvider value={viewer}>
    <aside data-testid="agent-preview" data-placement={placement} data-depth={stack.length} aria-label={`${text.preview} · ${top.title}`} {...swipe}
      {...(placement === 'screen' ? { style: { bottom: layer.tabbar, paddingBottom: `calc(${layer.peekPoint} - ${layer.tabbar}px)` } } : {})}
      className={cn('flex min-h-0 min-w-0 flex-col bg-background text-foreground [&_.file-tree-row-button]:pointer-coarse:min-h-(--control-min,2.75rem) [&_.file-tree-row-button]:max-md:min-h-(--control-min,2.75rem)', placement === 'screen' ? 'fixed inset-0 z-(--z-app-shell-peek) [&_[data-testid=artifact-csv]]:table-auto' : 'relative h-full flex-1')}>
      <div data-testid="agent-preview-body" className="relative min-h-0 flex-1">
        {stack.map((entry, index) => {
          const shown = index === stack.length - 1;
          return <div key={entry.id} data-pane-entry={entry.kind} {...(shown ? { 'data-pane-top': '' } : { inert: true, 'aria-hidden': true })} className={cn('absolute inset-0 flex-col', shown ? 'flex' : 'hidden')}>
            <EntryView entry={entry} below={stack[index - 1]} top={shown} placement={placement} assistant={assistant} />
          </div>;
        })}
      </div>
    </aside>
  </ViewerWindowProvider>;
}

/** The wide pane: the kit's `Dock`, as the docked conversation, so it resizes by drag or arrow keys and keeps its width whatever it shows. */
export function PaneDock({ assistant }: { readonly assistant: string }) {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const top = layer.stack.at(-1);
  return <Dock id="preview" side="right" defaultWidth={512} minWidth={320} open onOpenChange={next => { if (!next) layer.pane.close(); }} labels={{ region: `${text.preview} · ${top?.title ?? ''}`, resize: text.resizePreview }}>
    <PaneStack placement="column" assistant={assistant} />
  </Dock>;
}

// What the person is looking at, for the agent. A screen calls `useAgentContext({ name, params })`; the transport sends the latest
// value with each submit (`createRemoteChat({ requestContext: readAgentContext })`) and the host renders it in `createPromptContext`.
// Advisory text for the model, never policy. The most recently mounted caller wins; unmounting restores the previous one.
import { createContext, createElement, useContext, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';

/** A type alias, so the value is assignable to the transport's `Record<string, unknown>`. */
export type AgentScreenContext = { readonly name: string; readonly params: Readonly<Record<string, unknown>> };

/** `composer="explore"`: what the person is looking at, as the app wrote it. */
export type AgentLooking = { readonly title: string; readonly detail?: string | undefined };
interface Entry { value: AgentScreenContext }
interface Store { readonly entries: Entry[]; readonly looking: AgentLooking[] }

const StoreContext = createContext<Store | null>(null);
/**
 * Whether the calling screen is the one on show. The shell keeps every screen mounted and hides the others, so a hidden screen must not
 * register its context (here) or its header (`useScreenHeader`). True outside a shell.
 */
export const ScreenActiveContext = createContext(true);
/** Whether the calling screen is the one on show: `false` on a screen the shell has hidden, `true` on the one on show and outside a shell. */
export function useScreenActive(): boolean { return useContext(ScreenActiveContext); }
/** The mounted provider's store, for `readAgentContext` (the transport option has no React context to read). */
let current: Store | null = null;

/** Holds the screens' contexts. `AgentLayerProvider` mounts one. */
export function AgentContextProvider({ children }: { readonly children: ReactNode }) {
  const [store] = useState<Store>(() => ({ entries: [], looking: [] }));
  useLayoutEffect(() => {
    const mine = store;
    current = mine;
    return () => { if (current === mine) current = null; };
  }, [store]);
  return createElement(StoreContext.Provider, { value: store }, children);
}

/** Registers the current screen while the calling component is mounted; a new `name` or `params` (compared as JSON) replaces it. */
export function useAgentContext(value: AgentScreenContext): void {
  const store = useContext(StoreContext);
  const active = useContext(ScreenActiveContext);
  const key = JSON.stringify([value.name, value.params]);
  const latest = useRef(value);
  useLayoutEffect(() => { latest.current = value; });
  const entry = useRef<Entry>({ value });
  // Mounting takes the top place; a later change of `name` or `params` updates the entry where it stands.
  useEffect(() => {
    if (!store || !active) return;
    const mine = entry.current;
    store.entries.push(mine);
    return () => { const at = store.entries.indexOf(mine); if (at >= 0) store.entries.splice(at, 1); };
  }, [store, active]);
  useEffect(() => { entry.current.value = latest.current; }, [key]);
}

/** What the explore panel shows as « You are looking at », while the calling component is mounted: it joins the screen context as `params.lookingAt`, whichever screen registered last. */
export function useLookingAt(value: AgentLooking | undefined): void {
  const store = useContext(StoreContext);
  const title = value?.title, detail = value?.detail;
  useEffect(() => {
    if (!store || title === undefined) return;
    const mine: AgentLooking = detail === undefined ? { title } : { title, detail };
    store.looking.push(mine);
    return () => { const at = store.looking.indexOf(mine); if (at >= 0) store.looking.splice(at, 1); };
  }, [store, title, detail]);
}

/** The latest screen context, or undefined when no screen registered one. Pass it as `requestContext`. */
export function readAgentContext(): AgentScreenContext | undefined {
  const entries = current?.entries;
  const screen = entries?.length ? entries[entries.length - 1]!.value : undefined;
  const looking = current?.looking.at(-1);
  if (!looking) return screen;
  return { name: screen?.name ?? looking.title, params: { ...screen?.params, lookingAt: looking } };
}

// Host concern: launch URLs select the shell's existing agent layer, never an agent runtime or permission.
export interface AgentLink {
  readonly agent: 'coach' | 'agent' | 'improve';
  readonly open?: 'half' | 'full';
  readonly input?: 'text' | 'voice';
}

/** Known shell targets only. Missing or invalid presentation options default to full and text; voice always opens full. */
export function parseAgentLink(search: string): Required<AgentLink> | null {
  const params = new URLSearchParams(search);
  const agent = params.get('agent');
  if (agent !== 'coach' && agent !== 'agent' && agent !== 'improve') return null;
  const input = params.get('input') === 'voice' ? 'voice' : 'text';
  return { agent, open: input === 'voice' || params.get('open') !== 'half' ? 'full' : 'half', input };
}

/** The query for an app-owned manifest shortcut or start_url. Recording still needs the person's press. */
export function agentLink({ agent, open = 'full', input = 'text' }: AgentLink): string {
  return `?${new URLSearchParams({ agent, open: input === 'voice' ? 'full' : open, input })}`;
}

// Compatibility export for installed apps; the shared presentation helper owns the subscription.
export { useVisualViewport } from '../utils/use-media';
export type { VisualViewportBox } from '../utils/use-media';

'use client';

// A full-screen app view (a document sheet, a pushed view of the app) that takes part in the shell's one-layer-at-a-time rule: opening it
// closes the agent and product manager layers (both, when a wide screen shows them side by side), and opening either of those closes it.
// Between the agent and the product manager the rule is the agent layer's own: one at a time on a phone and below `TOGETHER_FROM`. Its Back is the shared Back manager's `sheet` layer
// (`useBackLayer`), so the browser's Back closes it first. Host concern: Pi has no layers; this is the shell's own presentation rule.
import { useCallback, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from 'react';
import { useBackLayer } from '../utils/back';

/** The shell's agent and product manager layers share one close; the agent layer registers it while mounted. */
const agentClosers = new Set<() => void>();
/** The one view on show, by id. Opening a view replaces the view on show. */
let shown: string | undefined;
const listeners = new Set<() => void>();
const emit = (): void => { for (const listener of [...listeners]) listener(); };
const subscribe = (listener: () => void): (() => void) => { listeners.add(listener); return () => { listeners.delete(listener); }; };

/** Registers how the agent layer closes (called by `AgentLayerProvider`). Returns the unregister function. */
export function registerAgentLayerCloser(close: () => void): () => void {
  agentClosers.add(close);
  return () => { agentClosers.delete(close); };
}

/** Closes the agent and product manager layers. The agent layer calls it before it opens; a view calls it before it opens. */
export function closeAgentLayers(): void {
  for (const close of [...agentClosers]) close();
}

/** Closes the view on show, if any (the agent layer calls it before it opens, so one layer is open at a time). */
export function closeShellLayer(): void {
  if (shown === undefined) return;
  shown = undefined;
  emit();
}

export interface ShellLayer {
  readonly open: () => void;
  readonly close: () => void;
  readonly isOpen: boolean;
}

export interface ShellLayerOptions {
  /** Asked when the browser's Back would close the view: `false` keeps it open (the history entry is pushed again). */
  readonly confirmBack?: () => boolean;
}

/** The one owner of each view id: its component registers Back and the history entry. Other callers only observe. */
const owners = new Map<string, symbol>();

/**
 * The handle of one full-screen view, `id` being its name in the shell. `open` closes the agent and product manager layers and any other
 * view; `close` closes this one (a no-op when it is not on show). The first component that calls `useShellLayer(id)` owns the view: only
 * it registers the Back layer and the history entry, and only it closes the view when it unmounts. Any other caller (a host's trigger)
 * observes `isOpen` and can open or close, and its own unmount releases nothing but its subscription.
 */
export function useShellLayer(id: string, options?: ShellLayerOptions): ShellLayer {
  // The owner is the first component of this id to render (parents render before their children). Claimed while rendering, so a parent
  // that mounts with an observer child is the owner; the claim is released by the owner's own cleanup.
  const [me] = useState(() => {
    const token = Symbol(id);
    const claimed = !owners.has(id);
    if (claimed) owners.set(id, token);
    return { token, owner: claimed };
  });
  const owner = me.owner;
  const isOpen = useSyncExternalStore(subscribe, () => shown === id, () => false);
  const open = useCallback(() => {
    closeAgentLayers();
    if (shown === id) return;
    shown = id;
    emit();
  }, [id]);
  const close = useCallback(() => {
    if (shown !== id) return;
    shown = undefined;
    emit();
  }, [id]);
  useEffect(() => {
    if (!owner) return undefined;
    if (!owners.has(id)) owners.set(id, me.token);
    return () => {
      if (owners.get(id) !== me.token) return;
      // The owner's component is gone: its view goes with it (its history entry is released by the Back layer's cleanup).
      owners.delete(id);
      close();
    };
  }, [id, owner, me, close]);
  const confirmBack = useRef(options?.confirmBack);
  const wanted = options?.confirmBack;
  useLayoutEffect(() => { confirmBack.current = wanted; });
  const back = useCallback(() => {
    // A refused Back keeps the view and its entry: the entry the browser just popped is pushed again.
    if (confirmBack.current && !confirmBack.current()) { history.pushState({ appShell: 'sheet' }, ''); return; }
    close();
  }, [close]);
  // The view is one history entry while it is open, owned by one component only (the Back manager's rules).
  useBackLayer(owner && isOpen, back, 'sheet');
  return { open, close, isOpen };
}

