  readonly sidebar?: false;
  readonly agent?: AgentSpec;
  /** Where the assistant's field sits on a wide screen: `dock` (default) in the dock under the thread; `content` pinned under the page content, at the content's width, with the dock holding only the thread (a send, or `talkAbout`, opens it); `bar`, the one composer (D-2198): as `content`, one row (chevron, attach, field, Dicter/Envoyer/Arrêter), the work or reply as a card on the folded field, the field going with the thread when docked, and `useAgentLayer().preview`. A phone keeps the peek drawer either way. `explore`: closed on every visit, with only a small « Ask » toggle at the bottom right (the unread dot and the needs-you ring as the icon has them; Ctrl or Cmd + J toggles); open, a right panel that pushes the page from 1100 px, overlays it below that and is a bottom sheet on a phone, its width resizable and remembered, Esc closing it. It replaces the icon of `floatingComposer` (they are not combined).
   * Or the config object (`ComposerConfig`, e.g. `{ launcher: 'circle', handoff: { openFull } }`: a round launcher that opens one panel, stacks with others, steps around `avoid` rectangles and hands the conversation to the app's full page), or a function of `{ phone, width, route }` that gives one. The strings are presets of it and stay. */
  readonly composer?: ComposerInput;
  /**
   * `composer="explore"`: what the person is looking at (`{ title, detail? }`), shown at the top of the panel as « You are looking at » and sent to the agent with each turn (`readAgentContext().params.lookingAt`).
   * Absent: nothing is shown and nothing is sent.
   */
  readonly context?: ExploreContext;
  /**
   * `composer="bar"`: the one composer may leave the bottom of the page (default `false`). The strip gains Float and Minimise: floating, the same bar sits over the page (moved by its grip, a corner or anywhere,
   * remembered per app and person; a wide screen only); minimised, it is a round icon with the unread mark and a ring when a decision waits, and a tap puts it back. A phone keeps the bar at the bottom
   * and gains Minimise. `useAgentLayer().place` and `setPlace` read and drive it.
   */
  readonly floatingComposer?: boolean;
  /** Consume agent/open/input launch parameters on mount (default). `false` leaves the URL and layer untouched. */
  readonly agentLink?: false;
  /** A panel beside the app, opened from the account menu. The product manager is `pmPanel` from the Factory's `platform-ui/pm-panel`. */
  readonly panel?: ShellPanel;
  readonly account?: AccountSpec;
  /** The language of the shell's own words and the layer's (« Se déconnecter », « Plus », « Ouvrir l’assistant »…). When set it wins over the agent's `chatProps.locale` and the panel's; without it `chatProps.locale`, then the panel's, then English. */
  readonly locale?: AppShellLocale;
  /**
   * The app's MCP door (`{ address: location.origin + '/mcp', appName, signIn }`): a plug icon button in the header, at the far right just
   * before the agent's button, on every screen and width, that opens how to connect a person's own assistant (`mcp-setup`). Words follow `locale`.
   */
  readonly mcp?: McpSetupProps;
  /** `false`: no assistant icon at the right of the screen header (default `true`). The assistant stays reachable from the left bar entry, the bar composer or the page. */
  readonly headerAgent?: boolean;
  /** Where the assistant's entry sits in the left bar: `end` (default) after the nav items, as before; `above-bottom` above the items placed after the screen's own sidebar content (the host's bottom items, such as « Admin »), with the before-items and the screen's content staying above it. */
  readonly agentNav?: 'end' | 'above-bottom';
  /** The app's router owns the URL; the shell only reports the choice. */
  readonly route: { readonly id: string; readonly onChange: (id: string) => void };
  /**
   * `true`: a backdrop blur behind dialogs, alert dialogs, sheets and drawers (default `false`: only their dim; blurring the page costs
   * frames on slow phones). Overlays live in a portal, so the shell marks `<html data-overlay-blur="on">` while it is mounted; the
   * shadcn overlays carry the rule (`in-data-[overlay-blur=on]:backdrop-blur-[var(--overlay-blur,4px)]`: an item's CSS stays inside `.app-shell`).
   */
  readonly overlayBlur?: boolean;
  /**
   * The wide-screen left pane can be resized (default `false`): its rail becomes a drag handle (`role="separator"`, arrow keys, double-click to reset),
   * between `min` and `max` rem (14 and 28). Fine pointer only; the phone sheet keeps `--sidebar-width-mobile`. The width is remembered per app and
   * per person; the theme's `--sidebar-width` stays the default. `true` or `{ min, max }`.
   */
  readonly resizable?: boolean | { readonly min?: number; readonly max?: number };
  /**
   * A stable id of the app (its slug), which names the app in the stored sidebar width instead of `title`: two apps with the same title on one origin,
   * or an app whose title is renamed or translated, keep (or do not share) their widths. Pass it with `resizable`; without it (or with an empty one) the key uses `title`.
   */
  readonly appId?: string;
  /**
   * A newer version of the app is online while the page is open. `{ available: true }` shows the kit's own notice (a status row above the phone's tab bar, at the foot of the
   * screen column on a wide screen: it takes room, so it never covers the screen's last control) with the shell's words, Reload and a dismiss. `onReload` replaces `location.reload()`.
   * A dismiss holds for `version` only. Default: no notice.
   */
  readonly update?: AppShellUpdate;
  /**
   * Things to tell the person at the composer, newest first. ONE shows at a time, above the bar (in the screen column, as the update notice does): `{ id, kind: 'info' | 'success' | 'warning' | 'error', text, action?, onDismiss?, reference? }`.
   * The others wait behind it as « N more waiting », and the next shows when it is dismissed. At most 5 wait: past that the oldest info or success notices go, a warning or an error never. Info and success fade after 8 s unless hovered or
   * focused; warnings and errors stay until dismissed. A notice never opens the conversation and never takes focus; a swipe left dismisses it on a phone. `update` is the last of the queue. Default: none.
   */
  readonly notices?: readonly AppShellNotice[];
}

/** The shells that ask for the blur now, and what `<html data-overlay-blur>` held before the first of them (the app's own HTML may set it). */
const blurOwners = new Set<symbol>();
let blurBefore: string | undefined;

/** `<html data-overlay-blur="on">` while any shell asks for it: set by the first owner, restored when the last one leaves. */
function useOverlayBlur(blur: boolean) {
  useEffect(() => {
    if (!blur || typeof document === 'undefined') return;
    const root = document.documentElement;
    const owner = Symbol('overlay-blur');
    if (blurOwners.size === 0) blurBefore = root.dataset.overlayBlur;
    blurOwners.add(owner);
    root.dataset.overlayBlur = 'on';
    return () => {
      blurOwners.delete(owner);
      if (blurOwners.size > 0) return;
      if (blurBefore === undefined) delete root.dataset.overlayBlur;
      else root.dataset.overlayBlur = blurBefore;
    };
  }, [blur]);
}

/** Registers what is on show for the agent. A screen's own `useAgentContext` is mounted later and wins. */
function ShellContext({ name }: { readonly name: string }): null {
  useAgentContext({ name, params: {} });
  return null;
}

function ScreenContent({ item }: { readonly item: NavItem }): ReactNode { return item.render(); }

/** Every screen stays mounted; the ones not on show are `hidden` and do not register a header or a context. */
function Screens({ items, activeId, scrolls, slot, centred, bar }: { readonly items: readonly NavItem[]; readonly activeId: string; readonly scrolls: boolean; readonly slot: HTMLElement | null; readonly centred: boolean; readonly bar: boolean }) {
  return <div data-bar-page={bar || undefined} className={cn('relative min-h-0 flex-1', bar && 'max-md:pb-(--app-shell-bar-height,0px)')}>
    {items.map(item => <ScreenActiveContext.Provider key={item.id} value={item.id === activeId}><ScreenHeaderSlotContext.Provider value={item.id === activeId ? slot : null}>
      <div hidden={item.id !== activeId} data-testid={`screen-${item.id}`} className={cn('h-full pb-[var(--agent-bar-reserve,0px)] scroll-pb-[var(--agent-bar-reserve,0px)]', scrolls ? 'overflow-y-auto overscroll-contain' : 'overflow-hidden')}>{centred ? <div data-testid="screen-centred" style={bar ? { marginInlineStart: 'clamp(0px, calc((100cqw - var(--container-3xl)) / 2), max(0px, calc(100% - var(--container-xs, 20rem) - var(--spacing) * 12)))', width: 'auto' } : undefined} className="mx-auto flex h-full w-full max-w-3xl flex-col"><ScreenContent item={item} /></div> : <ScreenContent item={item} />}</div>
    </ScreenHeaderSlotContext.Provider></ScreenActiveContext.Provider>)}
  </div>;
}

function Shell({ resizable, appId, compactNav, single, bar, layout, rail, title, nav, agent, panel, account, route, text, update, notices, mcp, headerAgent, agentNav }: { readonly headerAgent: boolean; readonly agentNav: NonNullable<AppShellProps['agentNav']>; readonly mcp: McpSetupProps | undefined; readonly update: AppShellUpdate | undefined; readonly notices: readonly AppShellNotice[]; readonly single: boolean; readonly bar: boolean; readonly resizable: AppShellProps['resizable']; readonly appId: string | undefined; readonly compactNav: NonNullable<AppShellProps['compactNav']>; readonly rail: NonNullable<AppShellProps['rail']>; readonly layout: AppShellProps['layout']; readonly title: string; readonly nav: readonly NavItem[]; readonly agent: AgentSpec | undefined; readonly panel: ShellPanel | undefined; readonly account: AccountSpec | undefined; readonly route: AppShellProps['route']; readonly text: AppShellText }) {
  const improve = panel && panel.menu !== false ? panel.label ?? text.improve : undefined;
  const Layout = panel?.Layout ?? NoPanelLayout;
  const compact = useIsCompact();
  const own = updateNotice(update, text);
  const sheet = compact && compactNav === 'sheet' && !single;
  const [accountOpen, setAccountOpen] = useState(false);
  // The header's slot for the screen on show (an embedded AgentWorkspace puts its bar's controls there).
  const [slot, setSlot] = useState<HTMLElement | null>(null);
  const active = nav.find(item => item.id === route.id) ?? nav[0];
  // The left pane: the person's kept choice, else the first visit's default (D-1909). `rail="hover"` keeps its own reveal and today's default.
  const today = rail !== 'hover' && layout === 'screen';
  const paneOpen = useSidebarOpen(rail !== 'hover', { app: appId || title, person: account?.email }, layout === 'screen', today, Boolean(active?.sidebar));
  if (!active) return null;
  // A nav choice waits for an open detail's stack entry to go back, so the app's router can replace the URL without that Back restoring
  // the detail's. Choosing the screen already on show changes nothing and keeps the detail.
  const choose = (id: string) => { if (id === active.id) route.onChange(id); else afterStacksBack(() => route.onChange(id)); };
  const hasAccount = Boolean(account) || improve;
  const avatar = hasAccount ? <>
    <Button variant="ghost" size="icon" data-testid="account-button" aria-label={account?.name ?? text.account} title={account?.name ?? text.account} onClick={() => setAccountOpen(true)}><AccountAvatar account={account} /></Button>
    <AppSheet open={accountOpen} onOpenChange={setAccountOpen} title={text.account}>
      <AccountChoices account={account} improve={improve} text={text} done={() => setAccountOpen(false)} />
    </AppSheet>
  </> : null;
  // The structure is the same compact or expanded, so a resize never remounts a screen.
  return <ResizableSidebarProvider data-testid="app-shell" resizable={resizable} app={appId || title} person={account?.email} defaultOpen={today} {...paneOpen} className="app-shell h-dvh min-h-0 overflow-hidden">
    {!single && (!compact || sheet) && <AppSidebar rail={sheet ? 'icon' : rail} identity={{ app: appId || title, person: account?.email }} title={title} items={nav} activeId={active.id} onChange={choose} agent={agent} agentNav={agentNav} account={account} improve={improve} text={text} />}
    <AgentDockLayout>
      <div data-slot="sidebar-inset" className="relative flex min-h-0 min-w-0 w-full flex-1 flex-col overflow-hidden bg-card">
      <Layout screen={active.label} navigation={compact && !sheet && !single ? <TabBar items={nav} activeId={active.id} onChange={choose} text={text} /> : undefined}>
        <ShellContext name={active.label} />
        <ScreenHeader fallbackTitle={single ? title : active.label} compact={compact} leadingAvatar={single} trigger={headerAgent && !(single && bar)}avatar={avatar} menu={sheet} screenSidebar={compact && !sheet && active.sidebar ? <ScreenSidebarSheet key={active.id} item={active} text={text} /> : undefined} text={text} slotRef={setSlot} mcp={mcp} />
        <Screens items={nav} activeId={active.id} scrolls={layout === 'screen'} slot={slot} centred={single} bar={bar} />
        <NoticeHost notices={own ? [...notices, own] : notices} text={text} compact={compact} reserve />
      </Layout>
      </div>
    </AgentDockLayout>
    <AgentLayer />
  </ResizableSidebarProvider>;
}

const never = () => () => {};
const NONE: readonly AppShellNotice[] = [];

export function AppShell(props: AppShellProps) {
  const { layout, rail = 'icon', compactNav = 'tabs', agent, panel, title, nav, account, route } = props;
  if (layout === 'chat' && agent) throw new Error('AppShell layout "chat" takes no `agent`: the page is the chat (use `panel` for the product manager)');
  const locale = props.locale ?? agent?.chatProps?.locale ?? (panel?.locale as AppShellLocale | undefined);
  const text = { ...appShellText(locale), ...agent?.words };
  const mcp = props.mcp && { ...props.mcp, locale: props.mcp.locale ?? (locale === 'fr' ? 'fr' : 'en') };
  useOverlayBlur(props.overlayBlur ?? false);
  // `composer` is a preset string, a config object (`launcher: 'circle'`...) or a function of `{ phone, width, route }` that gives one; the layer and the shell read it resolved.
  const given = useComposerInput(props.composer, route.id);
  // A screen may hide the composer or give its own (`NavItem.composer`).
  const { composer, floating } = composerForScreen(given, props.floatingComposer === true, nav.find(item => item.id === route.id)?.composer);
  const alone = useSyncExternalStore(never, () => panel?.page?.matches() ?? false, () => false);
  if (alone && panel?.page) return <panel.page.Page config={panel.config} appName={title} locale={props.locale} />;
  return <AgentLayerProvider agent={agent} composer={composer} context={props.context} floating={floating} panel={panel} locale={props.locale} agentLink={props.agentLink} appName={props.title} modeIdentity={{ app: props.appId || title, person: account?.email, screen: layout === 'screen' }}>
    <HeaderProvider><Shell single={props.sidebar === false} bar={resolveComposer({ composer, floatingComposer: floating }).flags.bar} resizable={props.resizable} appId={props.appId} compactNav={compactNav} layout={layout} rail={rail} title={title} nav={nav} agent={agent} account={account} route={route} panel={panel} text={text} update={props.update} notices={props.notices ?? NONE} mcp={mcp} headerAgent={props.headerAgent !== false} agentNav={props.agentNav ?? 'end'} /></HeaderProvider>
  </AgentLayerProvider>;
}

// The update notice (`AppShell update`): a newer version of the app is online while the page is open. It is one `AppShellNotice` (an info notice that stays until dismissed) drawn
// by the shell's notice host, with a Reload action and a dismiss that holds for the version named. Host concern: Pi has no layout; the host decides when `available` is true
// (a version poll, a service worker).
import type { AppShellNotice } from './shell-notice';
import type { AppShellText } from './text';

export interface AppShellUpdate {
  /** `true` once the host knows a newer version is online; the notice shows until the person reloads or dismisses it. */
  readonly available: boolean;
  /** The newer version's name. A dismiss holds for this version only: a later one shows the notice again. Without it a dismiss holds until `available` turns false. */
  readonly version?: string;
  /** What Reload does. Default: `location.reload()`. */
  readonly onReload?: () => void;
}

/** The update as a notice, or none while no update is available. */
export function updateNotice(update: AppShellUpdate | undefined, text: AppShellText): AppShellNotice | undefined {
  if (!update?.available) return undefined;
  return { id: `update:${update.version ?? ''}`, kind: 'info', text: text.updateAvailable, action: { label: text.updateReload, onSelect: update.onReload ?? (() => globalThis.location?.reload()) },
    own: { version: update.version, dismissLabel: text.updateDismiss, ids: { root: 'update-notice', text: 'update-notice-text', action: 'update-reload', dismiss: 'update-dismiss' } } };
}

'use client';

// A reference an app cites to the agent: one pill in the composer (icon, title, number or subtitle, remove). `CiteButton` (or `useAgentLayer().talkAbout(citeToken(ref), { add: true })`)
// adds it; the shell registers the `cite` mention kind itself, so no app code draws the chip. What the agent receives is `@"cite:{"kind","id","title"}"`, read back with `citedReferences`.
import { useSyncExternalStore } from 'react';
import { hasMention, mentionedPaths, mentionToken } from '@hachej/boring-ui-kit/chat-text';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { AtIcon, CheckIcon } from '../_shared/icons';
import type { MentionKind } from '../pi-chat/config';
import { cn } from '../utils/utils';
import { shellWords, useInternal } from './layer-context';

/** What an app cites: its own kind of thing (`card`, `invoice`), its id, a title, and an optional number or one muted line. */
export interface CiteReference {
  readonly kind: string;
  readonly id: string | number;
  readonly title: string;
  readonly subtitle?: string | undefined;
}

export const CITE_MENTION = 'cite';

export const citeMentionPath = ({ kind, id, title, subtitle }: CiteReference): string =>
  `${CITE_MENTION}:${JSON.stringify({ kind, id, title, ...(subtitle ? { subtitle } : {}) })}`;

/** The one `@` token for `talkAbout`, quoted when the value has spaces. */
export const citeToken = (reference: CiteReference): string => mentionToken(citeMentionPath(reference));

/** The reference a mention value (with its `cite:` prefix) stands for; undefined when it is not a well-formed citation. */
export function parseCiteReference(value: string): CiteReference | undefined {
  if (!value.startsWith(`${CITE_MENTION}:`)) return undefined;
  try {
    const parsed = JSON.parse(value.slice(CITE_MENTION.length + 1)) as Partial<CiteReference>;
    if (typeof parsed.kind !== 'string' || typeof parsed.title !== 'string' || (typeof parsed.id !== 'string' && typeof parsed.id !== 'number')) return undefined;
    return { kind: parsed.kind, id: parsed.id, title: parsed.title, ...(typeof parsed.subtitle === 'string' && parsed.subtitle ? { subtitle: parsed.subtitle } : {}) };
  } catch { return undefined; }
}

/** The citations a message carries, in order, once each: what the agent's side reads. */
export function citedReferences(text: string): CiteReference[] {
  const seen = new Set<string>();
  return mentionedPaths(text).flatMap(value => {
    const reference = parseCiteReference(value);
    const key = reference && `${reference.kind}:${reference.id}`;
    if (!reference || seen.has(key!)) return [];
    seen.add(key!);
    return [reference];
  });
}

/** The composer's chip and the sent message's mention for a citation; `word` is the kit's label (« Reference », « Référence »). */
export const citeMentionKind = (word: string): MentionKind => ({
  label: value => { const reference = parseCiteReference(`${CITE_MENTION}:${value}`); return reference ? `${word}: ${reference.title}` : value; },
  present: value => { const reference = parseCiteReference(`${CITE_MENTION}:${value}`); return reference ? { title: reference.title, ...(reference.subtitle ? { badge: reference.subtitle } : {}) } : { title: value }; },
  icon: <AtIcon className="size-4" aria-hidden="true" />,
});

const noSubscription = () => () => {};

/** A small button that cites `reference` to the agent: adds one chip (a second citation adds a second, the same one again changes nothing). Shown only when the agent's chat has `mentions`. */
export function CiteButton({ reference, className }: { readonly reference: CiteReference; readonly className?: string }) {
  const layer = useInternal();
  const controller = layer.agent?.controller, enabled = layer.agent?.chatProps?.mentions !== undefined;
  const draft = useSyncExternalStore(controller?.subscribe ?? noSubscription, () => controller?.getSnapshot().draft.text ?? '');
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  if (!enabled) return null;
  const done = hasMention(draft, citeMentionPath(reference)), label = `${done ? text.referencedInAgent : text.referenceInAgent}: ${reference.title}`;
  return <Tooltip>
    <TooltipTrigger render={<Button type="button" variant="ghost" size="icon-sm" data-testid="cite-reference" data-cited={done ? '' : undefined} aria-label={label} className={cn('max-md:min-w-11 pointer-coarse:min-w-11', className)}
      onClick={() => layer.talkAbout(citeToken(reference), { add: true })} />}>{done ? <CheckIcon aria-hidden="true" /> : <AtIcon aria-hidden="true" />}</TooltipTrigger>
    <TooltipContent side="top">{text.referenceInAgent}</TooltipContent>
  </Tooltip>;
}

'use client';

// Notices at the composer (`AppShell notices`, and the `update` notice drawn through the same component). ONE notice shows at a time, above the bar in the screen
// column, in the flow above the phone's tab bar (it takes room, so it never covers the screen's last control); the others wait behind it with a count and the next
// shows when this one goes. A notice takes no focus, never opens the conversation and is announced politely. Info and success fade after 8 s unless hovered or focused;
// warnings and errors stay until dismissed. Host concern: Pi has no layout; the platform decides what is worth a notice, the kit only draws it.
import { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { Alert } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { AtIcon, CircleAlertIcon, CircleCheckIcon, InfoIcon, TriangleAlertIcon, XIcon } from '../_shared/icons';
import { cn } from '../utils/utils';
import { useInternal } from './layer-context';
import type { AppShellText } from './text';

export interface AppShellNotice {
  /** Stable per notice: a dismiss holds for this id, and a list that no longer has it forgets the dismiss. */
  readonly id: string;
  readonly kind: 'info' | 'success' | 'warning' | 'error';
  readonly text: string;
  /** One action in place. The host removes the notice when it is done (a notice that stays shows the next one only when it is dismissed). */
  readonly action?: { readonly label: string; readonly onSelect: () => void };
  /** The person dismissed it, or it faded. The shell hides it at once either way; a host that owns the list drops it here. */
  readonly onDismiss?: () => void;
  /** Warning and error only: a mention token (`talkAbout`) that puts this notice in the assistant's field, as a table row does. Shown when the agent's chat has `mentions`. */
  readonly reference?: string;
  /** Set by the shell for its own update notice: it stays until dismissed, has its own names, and says which version it is for. */
  readonly own?: { readonly version: string | undefined; readonly dismissLabel: string; readonly ids: { readonly root: string; readonly text: string; readonly action: string; readonly dismiss: string } };
}

const FADE_MS = 8000;
const MAX_QUEUED = 5;
const SWIPE = 48;
const droppable = (notice: AppShellNotice) => notice.kind === 'info' || notice.kind === 'success';
const fades = (notice: AppShellNotice) => droppable(notice) && !notice.own;
/** How long a notice stays before it fades: `fadeMs` (0 = stays) for every kind but a warning, else 8 s for info and success and no fade for the others. Undefined: it stays. */
const fadeAfter = (notice: AppShellNotice, fadeMs: number | undefined): number | undefined =>
  notice.own ? undefined : fadeMs === undefined ? fades(notice) ? FADE_MS : undefined : notice.kind === 'warning' || fadeMs <= 0 ? undefined : fadeMs;

/** At most `MAX_QUEUED`: past that the oldest (last) info or success notices go, one at a time; a warning or an error is never dropped. */
export function capNotices(list: readonly AppShellNotice[], max = MAX_QUEUED): readonly AppShellNotice[] {
  const kept = [...list];
  for (let at = kept.findLastIndex(droppable); kept.length > max && at >= 0; at = kept.findLastIndex(droppable)) kept.splice(at, 1);
  return kept;
}

const TONES = {
  info: { icon: InfoIcon, box: '', mark: '' },
  success: { icon: CircleCheckIcon, box: 'border-success bg-success-soft', mark: 'text-success-soft-foreground' },
  warning: { icon: TriangleAlertIcon, box: 'border-warning bg-warning-soft', mark: 'text-warning-soft-foreground' },
  error: { icon: CircleAlertIcon, box: 'border-destructive bg-destructive-soft', mark: 'text-destructive-soft-foreground' },
} as const;

/** Notices as the shell shows them: the host's, then the update's. `notices` is newest first. Renders at most one. */
export function NoticeHost({ notices, text, compact, fadeMs, max, reserve = false }: { readonly notices: readonly AppShellNotice[]; readonly text: AppShellText; readonly compact: boolean; readonly fadeMs?: number | undefined; readonly max?: number | undefined; /** The shell's row at the foot of the screen: a circle launcher's footprint (`--composer-reserve-inline`) is kept free at its end, so the row never runs under the circle. */ readonly reserve?: boolean }): ReactNode {
  // Read here, not in the shell: only a shell with notices follows the layer's snaps (a shell that reads the layer re-renders its screens with it).
  const layer = useInternal();
  const [gone, setGone] = useState<readonly string[]>([]);
  const [held, setHeld] = useState(false);
  const [press, setPress] = useState<{ readonly x: number; readonly y: number } | undefined>();
  const queue = capNotices(notices, max).filter(notice => !gone.includes(notice.id));
  const shown = queue[0];
  // A dismiss ends with the notice leaving the list: the same id may come back and show again. Reset while rendering, not in an effect.
  if (gone.some(id => !notices.some(notice => notice.id === id))) setGone(gone.filter(id => notices.some(notice => notice.id === id)));
  const dismiss = () => { if (!shown) return; setGone(ids => [...ids, shown.id]); setHeld(false); shown.onDismiss?.(); };
  const fadeIn = shown === undefined ? undefined : fadeAfter(shown, fadeMs);
  const fading = fadeIn !== undefined;
  const latest = useRef(shown);
  useEffect(() => { latest.current = shown; });
  const shownId = shown?.id;
  useEffect(() => {
    if (shownId === undefined || !fading || held) return;
    const timer = setTimeout(() => { setGone(ids => [...ids, shownId]); latest.current?.onDismiss?.(); }, fadeIn);
    return () => clearTimeout(timer);
  }, [shownId, fading, fadeIn, held]);
  if (!shown) return null;
  const { icon: Icon, box, mark } = TONES[shown.kind];
  const ids = shown.own?.ids ?? { root: 'notice', text: 'notice-text', action: 'notice-action', dismiss: 'notice-dismiss' };
  // A phone's peek (the one composer's field, or a parked drawer) sits over the foot of the screen, above the tabs: the notice rises above it.
  const lift = compact && layer.snap === 'peek' ? `calc(${layer.peekPoint} - ${layer.tabbar}px)` : undefined;
  const mentions = layer.agent?.chatProps?.mentions !== undefined;
  const touch = 'max-md:min-h-11 pointer-coarse:min-h-11';
  return <div data-testid={ids.root} data-notice-kind={shown.kind} data-version={shown.own?.version} data-feedback-ignore="" style={lift || (reserve && layer.circle) ? { ...(lift ? { marginBottom: lift } : {}), ...(reserve && layer.circle ? { paddingInlineEnd: 'max(var(--screen-gutter, 1rem), calc(var(--composer-reserve-inline, 0px) + 0.5rem))' } : {}) } : undefined} className="shrink-0 touch-pan-y px-[var(--screen-gutter,1rem)] py-2"
    onPointerEnter={() => setHeld(true)} onPointerLeave={() => setHeld(false)} onFocus={() => setHeld(true)} onBlur={() => setHeld(false)}
    onPointerDown={event => { if (event.pointerType !== 'mouse') setPress({ x: event.clientX, y: event.clientY }); }}
    onPointerUp={event => { const start = press; setPress(undefined); if (start && event.clientX - start.x <= -SWIPE && Math.abs(event.clientY - start.y) < SWIPE / 2) dismiss(); }} onPointerCancel={() => setPress(undefined)}>
    {/* The default Alert tinted by the kind: the kit's variants are not in every shadcn Alert, and `info` keeps the plain card the update notice always had. */}
    <Alert role="status" aria-live="polite" className={cn('flex items-center gap-2', box)}>
      <Icon className={mark} />
      <div className="flex min-w-0 flex-1 flex-col md:flex-row md:items-center md:gap-2">
        <span data-testid={ids.text} className="min-w-0 flex-1">{shown.text}</span>
        {queue.length > 1 && <span data-testid="notice-more" className="shrink-0 text-xs text-muted-foreground">{text.noticeMore.replace('{n}', String(queue.length - 1))}</span>}
      </div>
      {shown.reference && mentions && (shown.kind === 'warning' || shown.kind === 'error') && <Tooltip>
        <TooltipTrigger render={<Button type="button" variant="ghost" size="icon-sm" data-testid="notice-reference" aria-label={text.referenceInAgent} className={cn(touch, 'max-md:min-w-11 pointer-coarse:min-w-11')} onClick={() => layer.talkAbout(shown.reference!, { add: true })} />}><AtIcon aria-hidden="true" /></TooltipTrigger>
        <TooltipContent side="top">{text.referenceInAgent}</TooltipContent>
      </Tooltip>}
      {shown.action && <Button variant="outline" size="sm" data-testid={ids.action} className={touch} onClick={shown.action.onSelect}>{shown.action.label}</Button>}
      <Button variant="ghost" size="icon-sm" data-testid={ids.dismiss} aria-label={shown.own?.dismissLabel ?? text.noticeDismiss} className={cn(touch, 'max-md:min-w-11 pointer-coarse:min-w-11')} onClick={dismiss}><XIcon /></Button>
    </Alert>
  </div>;
}

'use client';

// The grip of the floating composer: six dots on the left of the bar and in the window's header. It is the drag handle (pointer events, a grab cursor, a 44 px target on touch)
// and the keyboard's way to move the bar (arrow keys, 16 px a step, 64 with Shift). The frame (`FloatFrame`) owns the position and hands the handlers down through this context.
import { createContext, useContext } from 'react';
import type { KeyboardEvent, PointerEvent } from 'react';
import { GripVerticalIcon } from '../_shared/icons';
import { cn } from '../utils/utils';
import { shellWords, useInternal } from './layer-context';

export interface GripHandlers {
  readonly onPointerDown: (event: PointerEvent<HTMLElement>) => void;
  readonly onPointerMove: (event: PointerEvent<HTMLElement>) => void;
  readonly onPointerUp: (event: PointerEvent<HTMLElement>) => void;
  readonly onPointerCancel: (event: PointerEvent<HTMLElement>) => void;
  readonly onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
}
export const GripContext = createContext<GripHandlers | null>(null);

/** `rail`: the full-height strip on the bar's left edge. Otherwise a small grip for a header. Nothing outside a `FloatFrame`. */
export function Grip({ rail = false }: { readonly rail?: boolean }) {
  const handlers = useContext(GripContext);
  const layer = useInternal();
  if (!handlers) return null;
  const label = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent).dragHandle;
  return <span role="button" tabIndex={0} data-testid={rail ? 'composer-grip' : 'composer-grip-tray'} aria-label={label} title={label} {...handlers}
    className={cn('flex touch-none cursor-grab items-center justify-center rounded-(--radius-3xl) text-muted-foreground outline-ring select-none hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:text-foreground focus-visible:outline-2 active:cursor-grabbing [&_svg]:size-4',
      rail ? 'absolute inset-y-0 left-0 z-raised w-7 pointer-coarse:w-11' : 'size-8 shrink-0 pointer-coarse:size-11')}><GripVerticalIcon aria-hidden="true" /></span>;
}

'use client';

// The open conversation's top edge as a handle (`shell-composer-resize`): drag it to make the window taller or shorter, or use the keys. It is a horizontal separator on the edge the
// controller strip sits on (the strip stays on top and keeps its buttons). While dragging the height goes straight into the two CSS variables the tray and its frame already read, so
// nothing re-renders per move; the release commits it to the layer, which remembers it per app and person. Host concern: Pi has no layout.
import { useCallback, useLayoutEffect, useRef, useState } from 'react';
import type { KeyboardEvent, PointerEvent } from 'react';
import { cn } from '../utils/utils';
import { shellWords, useInternal } from './layer-context';

/** The window's least height (px): its header and about three messages; the bar is not part of it. */
export const TRAY_MIN = 240;
const STEP = 24;
const BIG_STEP = 96;
/** The gap kept between the window's top edge and the header (or the viewport's top), in px. */
const MARGIN = 16;
const SIZE_VAR = '--app-shell-bar-tray-size';
const EXPANDED_VAR = '--app-shell-bar-tray-expanded';

/** The element that carries the two variables while the handle changes them: the floating frame, or the composer's box. */
const hostOf = (handle: HTMLElement): HTMLElement | null => handle.closest<HTMLElement>('[data-testid=composer-floating]') ?? handle.closest<HTMLElement>('[data-one-composer]');

/** The least and greatest height the window can take now, and the height it has. The greatest keeps the window under the header (in the page) or inside the viewport (floating). */
function measure(handle: HTMLElement): { readonly min: number; readonly max: number; readonly now: number } | null {
  const box = handle.closest<HTMLElement>('[data-one-composer]');
  const tray = box?.querySelector<HTMLElement>('[data-testid=agent-tray]');
  if (!box || !tray) return null;
  const bar = box.getBoundingClientRect();
  const floating = handle.closest('[data-testid=composer-floating]') !== null;
  const room = floating ? window.innerHeight - bar.height - 2 * MARGIN : bar.top - (handle.closest('[data-testid=agent-content]')?.getBoundingClientRect().top ?? 0) - MARGIN;
  return { min: TRAY_MIN, max: Math.max(TRAY_MIN, Math.floor(room)), now: Math.round(tray.getBoundingClientRect().height) };
}

export function ResizeHandle() {
  const layer = useInternal();
  const { trayHeight, setTrayHeight, size, setSize } = layer;
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const ref = useRef<HTMLDivElement>(null);
  const [range, setRange] = useState({ min: TRAY_MIN, max: TRAY_MIN, now: TRAY_MIN });
  const drag = useRef<{ readonly y: number; readonly height: number; moved: boolean; last: number } | null>(null);
  const clamp = (value: number, from: { readonly min: number; readonly max: number }) => Math.min(Math.max(value, from.min), from.max);

  // The range follows the window: what the person set, a resize of the viewport, another level. A remembered height that no longer fits is brought back inside it.
  useLayoutEffect(() => {
    const read = () => {
      const handle = ref.current;
      const next = handle && measure(handle);
      if (!next) return;
      setRange(before => before.min === next.min && before.max === next.max && before.now === next.now ? before : next);
      if (size === 'open' && trayHeight !== undefined && !drag.current && (trayHeight > next.max || trayHeight < next.min)) setTrayHeight(clamp(trayHeight, next));
    };
    read();
    window.addEventListener('resize', read);
    return () => window.removeEventListener('resize', read);
  }, [trayHeight, size, setTrayHeight]);

  const apply = useCallback((height: number | null) => {
    const host = ref.current && hostOf(ref.current);
    if (!host) return;
    for (const name of [SIZE_VAR, EXPANDED_VAR]) { if (height === null) host.style.removeProperty(name); else host.style.setProperty(name, `${height}px`); }
  }, []);
  const commit = useCallback((height: number | undefined) => { setTrayHeight(height); setSize('open'); }, [setTrayHeight, setSize]);
  const current = () => (ref.current && measure(ref.current)) ?? range;

  const stop = () => { document.body.style.removeProperty('user-select'); drag.current = null; };
  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.style.setProperty('user-select', 'none');
    drag.current = { y: event.clientY, height: current().now, moved: false, last: current().now };
  };
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const held = drag.current;
    if (!held) return;
    const bounds = current();
    const next = Math.round(clamp(held.height + held.y - event.clientY, bounds));
    if (next === held.last && held.moved) return;
    held.moved = true;
    held.last = next;
    apply(next);
    event.currentTarget.setAttribute('aria-valuenow', String(next));
  };
  const onPointerUp = () => {
    const held = drag.current;
    stop();
    if (held?.moved) commit(held.last);
  };
  const onPointerCancel = () => {
    const held = drag.current;
    stop();
    if (held?.moved) { apply(trayHeight ?? null); setRange(before => ({ ...before })); }
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const bounds = current();
    const by = event.shiftKey ? BIG_STEP : STEP;
    const target = event.key === 'ArrowUp' ? bounds.now + by : event.key === 'ArrowDown' ? bounds.now - by : event.key === 'Home' ? bounds.min : event.key === 'End' ? bounds.max : null;
    if (target === null && event.key !== 'Enter') return;
    event.preventDefault();
    commit(target === null ? undefined : clamp(target, bounds));
  };

  return <div ref={ref} role="separator" aria-orientation="horizontal" tabIndex={0} data-testid="composer-resize" aria-label={text.resizeHandle} title={text.resizeHandle}
    aria-valuenow={range.now} aria-valuemin={range.min} aria-valuemax={range.max}
    onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerCancel} onLostPointerCapture={onPointerCancel} onKeyDown={onKeyDown} onDoubleClick={() => commit(undefined)}
    style={{ top: `calc(0px - var(${SIZE_VAR}))` }}
    className={cn('group/resize pointer-events-auto absolute inset-x-0 z-lifted h-1.5 -translate-y-1/2 cursor-ns-resize touch-none select-none outline-none',
      'pointer-coarse:h-11 pointer-coarse:-translate-y-[calc(100%-0.25rem)]')}>
    {/* On hover and keyboard focus the border thickens to a 2 px line with a short grip bar; the strip sits over the middle, so the grip is drawn a quarter in. */}
    <span aria-hidden="true" className="pointer-events-none absolute inset-x-4 top-1/2 h-0.5 -translate-y-1/2 bg-ring opacity-0 transition-opacity duration-(--duration-fast) group-[:hover]/resize:opacity-100 group-[:focus-visible]/resize:opacity-100 group-[:active]/resize:opacity-100 motion-reduce:transition-none pointer-coarse:top-[calc(100%-0.125rem)]" />
    <span aria-hidden="true" className="pointer-events-none absolute top-1/2 left-1/4 h-1.5 w-10 -translate-x-1/2 -translate-y-1/2 rounded-(--radius-3xl) bg-ring opacity-0 transition-opacity duration-(--duration-fast) group-[:hover]/resize:opacity-100 group-[:focus-visible]/resize:opacity-100 group-[:active]/resize:opacity-100 motion-reduce:transition-none pointer-coarse:top-[calc(100%-0.125rem)]" />
  </div>;
}

'use client';

// `composer="explore"`: the same composer in a mode for screens people read (tables, charts). Closed on every visit: the page keeps its whole width and nothing sits at the bottom;
// a small « Ask » toggle at the bottom right opens the panel. Open, the panel pushes the page from 1100 px, overlays it below that, and is the bottom sheet on a phone (`CompactSheet`,
// the same drawer as every other mode). It reuses the layer's chat, title row, History and notices: no second chat component. The closed toggle carries what the icon carries
// (the unread mark, the needs-you ring), so a result that arrives while closed is never silent. Host concern: Pi has no layout.
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, PointerEvent } from 'react';
import { UnreadMark } from '../_shared/controller-strip';
import { Separator } from '@/components/ui/separator';
import { useMedia } from '../utils/use-media';
import { cn } from '../utils/utils';
import { useLookingAt } from './agent-context';
import { ChatSlot, Header, useTitle } from './agent-chats';
import { VoiceProblem } from './agent-bar-parts';
import { shellWords, useInternal } from './layer-context';
import { LauncherNote, OpenFullButton, escapeInFeedback, useNote } from './composer-actions';
import { layerStyle, useCornerPlace } from './composer-place';

/** The panel pushes the page from this viewport width (px); below it the panel overlays the page. A phone (below 768) has the bottom sheet. */
export const EXPLORE_PUSH_FROM = 1100;
export const EXPLORE_PUSH_QUERY = `(width >= ${EXPLORE_PUSH_FROM}px)`;
const EXPLORE_DEFAULT = 384;
const EXPLORE_MIN = 320;
const EXPLORE_MAX = 720;
/** The page keeps at least this much beside a pushing panel (px), and an overlay leaves this much of the page's edge visible. */
const MIN_PAGE = 360;
const EDGE = 48;
const STEP = 24;
const BIG_STEP = 96;
const FIELD = '[data-spec=agent] [data-testid=composer-input]';

/** Where explore stands: whether the mode is on (with an agent), whether the panel is open, and how it shows at this width. */
export function useExplorePlace(): { readonly active: boolean; readonly open: boolean; readonly mode: 'push' | 'overlay' | 'sheet' } {
  const layer = useInternal();
  const wide = useMedia(EXPLORE_PUSH_QUERY);
  const active = layer.explore && layer.agent !== undefined;
  return { active, open: active && layer.showing === 'agent', mode: !layer.expanded ? 'sheet' : wide ? 'push' : 'overlay' };
}

/** « You are looking at »: the app's `context`, at the top of the panel (and of the sheet). Absent when the app gives none. */
export function ExploreContextLine() {
  const layer = useInternal();
  const looking = layer.lookingAt;
  if (!layer.explore || !looking) return null;
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  return <div data-testid="explore-context" className="mx-3 mb-2 flex shrink-0 flex-col gap-0.5 rounded-(--radius-3xl) bg-muted px-3 py-2 text-xs text-muted-foreground">
    <span data-testid="explore-context-label" className="font-medium text-primary">{text.lookingAt}</span>
    <span data-testid="explore-context-title" className="text-sm font-medium text-foreground wrap-anywhere">{looking.title}</span>
    {looking.detail && <span data-testid="explore-context-detail" className="wrap-anywhere">{looking.detail}</span>}
  </div>;
}

/** The toggle: a small tab at the bottom right, above the phone's tab bar and inside the safe areas. It shows the unread dot and the needs-you ring of the closed conversation. */
export function ExploreToggle() {
  const layer = useInternal();
  const { open } = useExplorePlace();
  const { signals, expanded, tabbar } = layer;
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const unread = signals.unread;
  const label = unread ? `${text.ask} (${unread.label}${unread.count && unread.count > 1 ? `, ${unread.count}` : ''})` : text.ask;
  const box = useRef<HTMLSpanElement>(null);
  const note = useNote();
  // A config object places the tab by its `at.offset` (flush with the edge by default), `at.stack`, `avoid` and `layer`; a string keeps the place it always had.
  const placed = useCornerPlace({ ref: box, corner: 'bottom-end', defaults: { inline: 0, block: expanded ? 'max(1rem, env(safe-area-inset-bottom))' : `calc(${tabbar}px + max(1rem, env(safe-area-inset-bottom)))` }, size: { w: 30, h: 76 }, active: !open && !layer.suspended });
  const style: CSSProperties = placed.style ?? { right: 'env(safe-area-inset-right, 0px)', bottom: expanded ? 'max(1rem, env(safe-area-inset-bottom))' : `calc(${tabbar}px + max(1rem, env(safe-area-inset-bottom)))` };
  if (layer.suspended) return null;
  // The approved tab: slim (30 px by 76 px), flush with the right edge, with its inner corners curved, the label set vertically; the unread mark sits on its top corner.
  return <span ref={box} hidden={open} style={style} data-composer={layer.composerFlags.id} data-testid="explore-place" className={cn('fixed z-(--z-app-shell-layer) h-19 w-7.5 rounded-l-(--radius-lg) shadow-pm-popover', signals.needsYou && 'ring-2 ring-warning outline-3 outline-warning/25')}>
    <button type="button" data-testid="explore-toggle" data-needs-you={signals.needsYou || undefined} aria-label={label} aria-expanded={open} aria-keyshortcuts="Control+J Meta+J" title={`${text.ask} (Ctrl+J)`} onClick={() => layer.open('agent')}
      style={{ writingMode: 'vertical-rl' }}
      className="relative flex size-full items-center justify-center rounded-l-(--radius-lg) bg-primary text-xs font-medium tracking-wider text-primary-foreground outline-ring select-none before:absolute before:-inset-2 before:content-[''] focus-visible:outline-2 focus-visible:outline-offset-2">{text.ask}</button>
    {unread && <UnreadMark unread={unread} dot="-top-1 -left-1" pill="-top-2 -left-3" className="ring-2 ring-background" />}
    {note && <LauncherNote note={note} />}
  </span>;
}

/** Ctrl or Cmd + J toggles; Esc closes the panel (the sheet's own Esc is the drawer's); focus goes into the field on open and back to the toggle on close; the context travels with the turn. */
export function ExploreController() {
  const layer = useInternal();
  const { open, mode } = useExplorePlace();
  useLookingAt(layer.lookingAt);
  const now = useRef({ open, mode, layer });
  useLayoutEffect(() => { now.current = { open, mode, layer }; });
  useEffect(() => {
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.isComposing || event.keyCode === 229) return;
      const { open: isOpen, mode: place, layer: api } = now.current;
      if ((event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === 'j') {
        event.preventDefault();
        if (isOpen) api.close(); else api.open('agent');
        return;
      }
      if (event.key !== 'Escape' || event.defaultPrevented || !isOpen || place === 'sheet' || escapeInFeedback(event)) return;
      // A list, menu or file opened over the panel takes its own Escape first.
      if (document.querySelector('[data-testid=conversations], [data-testid=agent-preview]') || (event.target instanceof Element && event.target.closest('[role=menu], [role=listbox], [aria-haspopup][aria-expanded=true]'))) return;
      event.preventDefault();
      api.close();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  const was = useRef(open);
  const { host } = layer;
  useEffect(() => {
    if (was.current === open) return;
    was.current = open;
    let frame = 0, tries = 0;
    const land = () => {
      const held = document.activeElement;
      if (open) {
        // A phone's sheet keeps the keyboard down until the person taps the field (which also grows the sheet): focus stays on the sheet.
        if (now.current.mode === 'sheet') return;
        const field = host?.querySelector<HTMLElement>(FIELD);
        field?.focus({ preventScroll: true });
        if (field && document.activeElement === field) return;
      } else {
        // Only when focus is nowhere (the closed panel took it with it): a view that opened meanwhile keeps its own.
        if (held && held !== document.body && !held.closest('[data-testid=explore-toggle]')) return;
        const toggle = document.querySelector<HTMLElement>('[data-testid=explore-toggle]');
        toggle?.focus({ preventScroll: true });
        if (toggle && document.activeElement === toggle) return;
      }
      if (++tries < 12) frame = requestAnimationFrame(land);
    };
    land();
    return () => cancelAnimationFrame(frame);
  }, [open, host]);
  return null;
}

/** The panel's side edge: a vertical separator (drag, arrow keys, Home and End, double-click to reset). The release commits the width, which the layer remembers per app and person. */
function ResizeEdge({ mode, width, live, commit }: { readonly mode: 'push' | 'overlay'; readonly width: number; readonly live: (width: number | undefined) => void; readonly commit: (width: number | undefined) => void }) {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const ref = useRef<HTMLDivElement>(null);
  const drag = useRef<{ readonly x: number; readonly width: number; last: number; moved: boolean } | null>(null);
  const bounds = useCallback(() => {
    const row = mode === 'push' ? ref.current?.parentElement?.parentElement?.clientWidth : undefined;
    const room = (row || window.innerWidth) - (mode === 'push' ? MIN_PAGE : EDGE);
    return { min: EXPLORE_MIN, max: Math.max(EXPLORE_MIN, Math.min(EXPLORE_MAX, room)) };
  }, [mode]);
  const clamp = (value: number) => { const { min, max } = bounds(); return Math.round(Math.min(Math.max(value, min), max)); };
  const down = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    drag.current = { x: event.clientX, width, last: width, moved: false };
  };
  const move = (event: PointerEvent<HTMLDivElement>) => {
    const held = drag.current;
    if (!held) return;
    const next = clamp(held.width + held.x - event.clientX);
    if (next === held.last && held.moved) return;
    held.moved = true; held.last = next;
    live(next);
  };
  const up = () => { const held = drag.current; drag.current = null; if (held?.moved) commit(held.last); };
  const cancel = () => { const held = drag.current; drag.current = null; if (held?.moved) live(undefined); };
  const keys = (event: KeyboardEvent<HTMLDivElement>) => {
    const by = event.shiftKey ? BIG_STEP : STEP;
    const { min, max } = bounds();
    const target = event.key === 'ArrowLeft' ? width + by : event.key === 'ArrowRight' ? width - by : event.key === 'Home' ? min : event.key === 'End' ? max : null;
    if (target === null && event.key !== 'Enter') return;
    event.preventDefault();
    commit(target === null ? undefined : clamp(target));
  };
  return <div ref={ref} role="separator" tabIndex={0} aria-orientation="vertical" data-testid="explore-resize" aria-label={text.resizeExplore} title={text.resizeExplore} aria-valuenow={width} aria-valuemin={EXPLORE_MIN} aria-valuemax={EXPLORE_MAX}
    onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={cancel} onLostPointerCapture={cancel} onKeyDown={keys} onDoubleClick={() => commit(undefined)}
    className="group/resize absolute inset-y-0 -left-1.5 z-lifted w-3 cursor-col-resize touch-none select-none outline-none">
    <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-transparent transition-[width,background-color] duration-(--duration-fast) group-hover/resize:w-0.5 group-hover/resize:bg-ring group-focus-visible/resize:w-0.5 group-focus-visible/resize:bg-ring group-active/resize:w-0.5 group-active/resize:bg-ring motion-reduce:transition-none" />
  </div>;
}

/** The open panel on a wide screen: beside the page (`push`, in the dock layout's row) or over it (`overlay`). The same title row, History, chat and field as the dock, with the context line on top. */
export function ExplorePanel({ mode }: { readonly mode: 'push' | 'overlay' }) {
  const layer = useInternal();
  const { text, title } = useTitle();
  const [dragged, setDragged] = useState<number | undefined>(undefined);
  const width = dragged ?? layer.exploreWidth ?? EXPLORE_DEFAULT;
  const commit = useCallback((next: number | undefined) => { setDragged(undefined); layer.setExploreWidth(next); }, [layer]);
  const push = mode === 'push';
  return <aside data-testid="explore-panel" data-mode={mode} data-composer={layer.composerFlags.id} role={push ? 'complementary' : 'dialog'} aria-label={title}
    style={{ ...layerStyle(layer, 1), width, maxWidth: push ? `calc(100% - ${MIN_PAGE / 16 + 0.5}rem)` : `calc(100vw - ${EDGE / 16}rem)` }}
    className={cn('app-shell flex min-h-0 flex-col bg-card text-card-foreground', push ? 'relative h-full shrink-0' : 'fixed inset-y-0 right-0 z-(--z-app-shell-layer) shadow-pm-popover')}>
    <Separator orientation="vertical" className="absolute inset-y-0 left-0" />
    <ResizeEdge mode={mode} width={width} live={setDragged} commit={commit} />
    <Header text={text} title={title} controls={<OpenFullButton />} />
    <ExploreContextLine />
    <VoiceProblem />
    <ChatSlot />
  </aside>;
}

'use client';

// The one composer floating over a page (`floatingComposer`) and folded to its icon. `FloatFrame` is the bar detached: fixed over the page, which stays usable under it, moved by its
// grip (pointer drag, arrow keys); dropped near a corner it snaps there. The place is the person's, remembered per app and person (`composer-pos`). `ComposerFab` is the round
// button the bar folds into: the unread mark and the needs-you ring of the conversation, and a tap puts everything back where it was. Host concern: Pi has no layout.
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, ReactNode } from 'react';
import { SparklesIcon } from '../_shared/icons';
import { UnreadMark } from '../_shared/controller-strip';
import { Button } from '@/components/ui/button';
import { useDraggable } from '../utils/use-draggable';
import type { DragPosition } from '../utils/use-draggable';
import { cn } from '../utils/utils';
import { GripContext } from './composer-grip';
import { LauncherNote, useNote } from './composer-actions';
import { useCornerPlace } from './composer-place';
import type { Corner } from './composer-config';
import type { GripHandlers } from './composer-grip';
import { shellWords, useInternal } from './layer-context';
import type { FloatCorner, FloatPos } from './layer-context';

/** The gap kept between the floating bar and the window's edge, in px. */
const MARGIN = 16;
/** A drop this close (px, on both axes) to a corner's place snaps to that corner. */
const SNAP = 120;
/** The bar's width at rest (22 rem, less the margins on a narrow window) and its height, for placing a remembered position of the old bar. */
const BAR_WIDTH = 352;
const BAR_HEIGHT = 56;
const STEP = 16;
const BIG_STEP = 64;
const ARROWS: Readonly<Record<string, readonly [number, number]>> = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };

const clamp = (value: number, low: number, high: number) => Math.min(Math.max(value, low), Math.max(low, high));
/** The logical corner of a float corner (`bl` is the bottom inline start). */
const LOGICAL: Readonly<Record<FloatCorner, Corner>> = { tl: 'top-start', tr: 'top-end', bl: 'bottom-start', br: 'bottom-end' };
const BOTTOM_EDGE = `max(${MARGIN}px, env(safe-area-inset-bottom))`;

export const cornerOf = (pos: FloatPos, width = 0, height = 0): FloatCorner => 'corner' in pos ? pos.corner
  : `${pos.top + height / 2 < window.innerHeight / 2 ? 't' : 'b'}${pos.left + width / 2 < window.innerWidth / 2 ? 'l' : 'r'}`;

/** The corner a dropped rect is close enough to, if any. */
export function snapCorner(rect: { readonly left: number; readonly top: number; readonly width: number; readonly height: number }): FloatCorner | undefined {
  for (const corner of ['tl', 'tr', 'bl', 'br'] as const) {
    const left = corner.endsWith('l') ? MARGIN : window.innerWidth - rect.width - MARGIN;
    const top = corner.startsWith('t') ? MARGIN : window.innerHeight - rect.height - MARGIN;
    if (Math.abs(rect.left - left) <= SNAP && Math.abs(rect.top - top) <= SNAP) return corner;
  }
  return undefined;
}

/**
 * The place the old floating bar (`AmbientChat`) remembered, `{ right, bottom }` in px from the window's bottom right, as this bar's place: a corner when it is near one (the old default is), else free.
 * Anything else (nothing saved, a malformed value) is no place.
 */
export function legacyFloatPos(value: unknown): FloatPos | undefined {
  const { right, bottom } = (value ?? {}) as { right?: unknown; bottom?: unknown };
  if (typeof right !== 'number' || typeof bottom !== 'number' || !Number.isFinite(right) || !Number.isFinite(bottom) || typeof window === 'undefined') return undefined;
  const width = Math.min(BAR_WIDTH, window.innerWidth - 2 * MARGIN);
  const at = { left: Math.max(0, Math.round(window.innerWidth - width - right)), top: Math.max(0, Math.round(window.innerHeight - BAR_HEIGHT - bottom)), width, height: BAR_HEIGHT };
  const corner = snapCorner(at);
  return corner ? { corner } : { left: at.left, top: at.top };
}

/** The CSS of a place. A top-anchored bar with the window open keeps room above it for the window. */
function placement(pos: FloatPos, trayOpen: boolean): CSSProperties {
  const room = `calc(var(--app-shell-bar-tray-size) + ${MARGIN}px)`;
  const top = (px: number) => trayOpen ? `max(${px}px, ${room})` : px;
  if ('corner' in pos) return { ...(pos.corner.endsWith('l') ? { left: MARGIN } : { right: MARGIN }), ...(pos.corner.startsWith('t') ? { top: top(MARGIN) } : { bottom: `max(${MARGIN}px, env(safe-area-inset-bottom))` }) };
  return { left: pos.left, top: top(pos.top) };
}

/**
 * The standalone entry's notices (`FloatingComposer notices`), drawn by whichever place the composer is in: above the floating bar (below it when the bar sits in a top corner),
 * above the folded icon, above the bottom bar. Null for a composer with no notices, so the shell's own places carry nothing.
 */
export const NoticeSlotContext = createContext<ReactNode>(null);

/** The host's `className` for the composer's own box (`FloatingComposer className`): the floating frame, the folded icon and the standalone bottom bar carry it, so a host can move or size the bar. */
export const ComposerClassContext = createContext<string | undefined>(undefined);

/** Where the notices sit around a box: above it, or below it for a bar in a top corner (above would leave the window). */
export function NoticeSlot({ below = false, className }: { readonly below?: boolean; readonly className?: string }) {
  const notices = useContext(NoticeSlotContext);
  if (!notices) return null;
  return <div data-testid="composer-notices" className={cn('absolute inset-x-0', below ? 'top-full' : 'bottom-full', className)}>{notices}</div>;
}

/** The bar detached from the page: `children` is the one composer's box. */
export function FloatFrame({ children }: { readonly children: ReactNode }) {
  const layer = useInternal();
  const className = useContext(ComposerClassContext);
  const { floatPos, setFloatPos, trayOpen } = layer;
  const box = useRef<HTMLDivElement>(null);
  // The place while the grip is held, and after a clamp; committed (and remembered) when the grip is released.
  const [live, setLive] = useState<DragPosition | null>(null);
  const moved = useRef(false);
  // The last place the drag asked for: a release reads it, not the DOM, which the last move has not been drawn into yet.
  const latest = useRef<DragPosition | null>(null);
  const pos: FloatPos = live ?? floatPos;
  const free = 'left' in pos ? pos : null;
  const place = useCallback((next: DragPosition) => { moved.current = true; latest.current = next; setLive(next); }, []);
  const drag = useDraggable({ box, position: free, onPositionChange: place, enabled: true });
  const commit = useCallback(() => {
    const size = box.current?.getBoundingClientRect();
    const at = latest.current;
    if (!size || !at) return;
    const corner = snapCorner({ ...at, width: size.width, height: size.height });
    setFloatPos(corner ? { corner } : { left: Math.round(at.left), top: Math.round(at.top) });
    setLive(null);
  }, [setFloatPos]);
  const handlers = useMemo<GripHandlers>(() => ({
    onPointerDown: event => { moved.current = false; latest.current = null; drag.onPointerDown(event); },
    onPointerMove: drag.onPointerMove,
    onPointerUp: () => { drag.onPointerUp(); if (moved.current) commit(); moved.current = false; },
    onPointerCancel: () => { drag.onPointerCancel(); if (moved.current) commit(); moved.current = false; },
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => {
      const way = ARROWS[event.key];
      const rect = box.current?.getBoundingClientRect();
      if (!way || !rect) return;
      event.preventDefault();
      const step = event.shiftKey ? BIG_STEP : STEP;
      setFloatPos({ left: Math.round(clamp(rect.left + way[0] * step, 0, window.innerWidth - rect.width)), top: Math.round(clamp(rect.top + way[1] * step, 0, window.innerHeight - rect.height)) });
      setLive(null);
    },
  }), [drag, commit, setFloatPos]);
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const tall = layer.size === 'open' && layer.trayHeight !== undefined ? `${layer.trayHeight}px` : 'min(26rem, 55dvh)';
  // A config object places a bar in a corner by its `at.offset`, `at.stack`, `avoid` and `layer`; a bar the person dragged free, and a composer given as a string, keep their own place.
  const corner = 'corner' in pos ? LOGICAL[pos.corner] : null;
  const around = useCornerPlace({ ref: box, corner, defaults: { inline: MARGIN, block: corner?.startsWith('top') ? MARGIN : BOTTOM_EDGE }, size: { w: BAR_WIDTH, h: BAR_HEIGHT }, active: true });
  const note = useNote();
  const room = `calc(var(--app-shell-bar-tray-size) + ${MARGIN}px)`;
  const where: CSSProperties = around.style ? { ...around.style, ...(trayOpen && corner?.startsWith('top') ? { insetBlockStart: `max(${String(around.style.insetBlockStart)}, ${room})` } : {}) } : placement(pos, trayOpen);
  const style = { ...where, ...(trayOpen ? { '--app-shell-bar-tray-size': tall, '--app-shell-bar-tray-expanded': tall } : {}) } as CSSProperties;
  return <GripContext.Provider value={handlers}>
    <div ref={box} data-testid="composer-floating" data-corner={'corner' in pos ? pos.corner : undefined} role="group" aria-label={text.assistant} style={style}
      className={cn('fixed z-(--z-app-shell-layer) w-[min(22rem,calc(100vw-2rem))]', className)} data-composer={around.style ? layer.composerFlags.id : undefined}>{children}<NoticeSlot below={cornerOf(pos, 0, 0).startsWith('t')} />{note && !trayOpen && <LauncherNote note={note} placement="above" className={corner?.startsWith('top') ? 'top-full bottom-auto mt-2 mb-0' : undefined} />}</div>
  </GripContext.Provider>;
}

/** The round button the composer folds into. A tap restores the bar where it was (floating, or the window if it was open). */
export function ComposerFab() {
  const layer = useInternal();
  const className = useContext(ComposerClassContext);
  const { signals, floatPos, expanded, tabbar, restore, placeFocus: focusRef } = layer;
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const button = useRef<HTMLButtonElement>(null);
  // A person who pressed Minimise keeps their place: focus lands on the icon.
  useEffect(() => { if (focusRef.current) { focusRef.current = false; button.current?.focus({ preventScroll: true }); } }, [focusRef]);
  const corner = expanded ? cornerOf(floatPos, 352, 56) : 'br';
  const Icon = layer.agent?.icon ?? SparklesIcon;
  const box = useRef<HTMLSpanElement>(null);
  const placed = useCornerPlace({ ref: box, corner: LOGICAL[corner], defaults: { inline: MARGIN, block: corner.startsWith('t') ? MARGIN : expanded ? BOTTOM_EDGE : `calc(${tabbar}px + ${BOTTOM_EDGE})` }, size: { w: 52, h: 52 }, active: true });
  const note = useNote();
  const style: CSSProperties = placed.style ? placed.style : expanded
    ? { ...(corner.endsWith('l') ? { left: MARGIN } : { right: MARGIN }), ...(corner.startsWith('t') ? { top: MARGIN } : { bottom: `max(${MARGIN}px, env(safe-area-inset-bottom))` }) }
    : { right: MARGIN, bottom: `calc(${tabbar}px + max(${MARGIN}px, env(safe-area-inset-bottom)))` };
  const label = signals.unread ? `${text.restore} (${signals.unread.label}${signals.unread.count && signals.unread.count > 1 ? `, ${signals.unread.count}` : ''})` : text.restore;
  // The agent at work: a thin ring pulses round the icon (still when the person prefers less motion). A decision that waits shows its own ring, which wins.
  const working = signals.working === true && !signals.needsYou;
  return <span ref={box} style={style} data-composer={placed.style ? layer.composerFlags.id : undefined} className={cn('fixed z-(--z-app-shell-layer) size-13 rounded-pm-round shadow-pm-popover', signals.needsYou && 'ring-2 ring-warning outline-3 outline-warning/25', className)}>
    <Button ref={button} type="button" size="icon" data-testid="composer-icon" data-needs-you={signals.needsYou || undefined} data-working={working || undefined} aria-busy={working || undefined} aria-label={label} title={text.restore} onClick={restore}>
      <Icon aria-hidden="true" />
      {signals.unread && <UnreadMark unread={signals.unread} dot="top-0 right-0" pill="-top-1 -right-2" />}
    </Button>
      {working && <span data-testid="composer-icon-working" aria-hidden="true" className="pointer-events-none absolute -inset-0.5 rounded-pm-round ring-2 ring-primary animate-pulse motion-reduce:animate-none" />}
    <NoticeSlot below={corner.startsWith('t')} className={cn('w-[min(22rem,calc(100vw-2rem))]', corner.endsWith('l') ? 'left-0 right-auto' : 'right-0 left-auto')} />
    {note && <LauncherNote note={note} />}
  </span>;
}

'use client';

// The standalone composer's right pane on a wide screen: what the page's own layout gives the shell (the right column), a floating window gives here. The pane's entries (an artifact the host's
// `artifactPanel` draws, a file in the kit's viewer, an app view) open in a window beside the floating bar, on the side the page has room for, or over the whole screen when the viewer asks for it.
// Same pane, same entries and back stack as the shell's column; a phone shows them full screen (`AgentLayer`). Host concern: Pi has no layout.
import { useEffect, useState } from 'react';
import type { CSSProperties, ReactElement } from 'react';
import { cn } from '../utils/utils';
import { PaneStack } from './agent-pane';
import { useTitle } from './agent-chats';
import { cornerOf } from './float-composer';
import { PaneFullscreenContext, useInternal } from './layer-context';

/** The bar's own width (`FloatFrame`) and the gap kept around the window, as CSS lengths. */
const BAR = 'min(22rem, calc(100vw - 2rem))';
const GAP = '1rem';

/** The window beside the bar: next to it on the side with room, at the bar's height; the folded icon and a bottom bar leave it at the right edge above them. */
function placeOf(layer: ReturnType<typeof useInternal>): CSSProperties {
  const { place, floatPos } = layer;
  const width = `min(40rem, calc(100vw - ${BAR} - 3 * ${GAP}))`;
  if (place !== 'float') return { right: GAP, bottom: '6rem', width: 'min(40rem, calc(100vw - 2rem))', height: 'min(46rem, calc(100dvh - 8rem))' };
  const corner = cornerOf(floatPos, 352, 56);
  return { ...(corner.endsWith('l') ? { left: `calc(${BAR} + 2 * ${GAP})` } : { right: `calc(${BAR} + 2 * ${GAP})` }), ...(corner.startsWith('t') ? { top: GAP } : { bottom: GAP }), width, height: `min(46rem, calc(100dvh - 2 * ${GAP}))` };
}

export function FloatPane(): ReactElement | null {
  const layer = useInternal();
  const { title } = useTitle();
  const [fullscreen, setFullscreen] = useState(false);
  const open = layer.stack.length > 0;
  // eslint-disable-next-line react-hooks/set-state-in-effect -- the full screen belongs to the open pane: closing it ends the full screen
  useEffect(() => { if (!open) setFullscreen(false); }, [open]);
  if (!open) return null;
  return <PaneFullscreenContext.Provider value={{ fullscreen, set: setFullscreen }}>
    <div data-testid="composer-pane" data-fullscreen={fullscreen || undefined} style={fullscreen ? undefined : placeOf(layer)}
      className={cn('fixed z-(--z-app-shell-layer) flex min-h-0 min-w-0 flex-col overflow-hidden bg-card text-card-foreground ring-1 ring-border', fullscreen ? 'inset-0' : 'rounded-(--radius-3xl) shadow-pm-popover')}>
      <PaneStack placement="column" assistant={title} />
    </div>
  </PaneFullscreenContext.Provider>;
}

'use client';

// What a host page adds to the standalone composer (`FloatingComposer`), the window-content props `AmbientChat` has: header tools and actions, Dock and Open in full chat as header actions, thumbs on replies,
// the artifact panel and the host's artifact routing, and embedding the conversation in a container. Each is opt-in: with none of them the composer is what it was. They are merged into the one `AgentSpec`
// the layer already reads, so the shell's own surfaces (`AppShell`'s `agent`) get no second path.
import { useMemo } from 'react';
import type { ReactElement, ReactNode } from 'react';
import { useArtifactFollow } from '@hachej/boring-ui-kit/chat-react';
import { ExternalLinkIcon, PanelLeftIcon } from '../_shared/icons';
import { PiChat } from '../pi-chat/pi-chat';
import { withChatPlugins } from '../pi-chat-plugins/chat-plugins';
import type { ReplyRef } from '../pi-chat/config';
import type { ArtifactsConfig } from '../pi-artifacts/artifact';
import { withReplyFeedback } from './reply-feedback';
import type { ReplyFeedbackHandler } from './reply-feedback';
import { useAutoOpenTasks } from './task-present';
import { chatWordLabels, shellWords } from './layer-context';
import type { AgentArtifactPanelApi, AgentSpec } from './layer-context';
import type { ScreenHeaderAction } from './header-actions';
import type { AppShellLocale } from './text';
import type { ArtifactDescriptor } from '../pi-artifacts/artifact';

/** The props `AmbientChat` has for what the window shows, with the same names and meaning. */
export interface FloatingHostProps {
  /** Draw the conversation in the container the host gives it (a workspace pane) instead of floating over the page: the thread and its field fill the container, no bar, no icon, no remembered place. The host supplies any header; the header props below are not shown. */
  readonly embedded?: boolean | undefined;
  /** Host-owned controls in the window's title row (for example an icon-anchored popover), before the actions. */
  readonly headerTools?: ReactNode;
  /** Host actions in the window's title row: two shown, the rest in « … ». */
  readonly headerActions?: readonly ScreenHeaderAction[] | undefined;
  /** Adds « Dock chat » to the window's title row, for a host that floats this conversation out of a docked chat (the controller is shared, nothing is lost). */
  readonly onDock?: (() => void) | undefined;
  /** Adds « Open in full chat » to the window's title row: hand the conversation to the host's full chat. */
  readonly onOpenFull?: ((conversationId: string) => void) | undefined;
  /** Adds thumbs up and down under each finished reply. `value` is `null` when the person takes the rating back. */
  readonly onFeedback?: ReplyFeedbackHandler | undefined;
  /** The viewer an artifact card opens in, inside the window's side pane (beside the bar, full screen on a phone). Build it from the viewer registry; it draws its own bar and calls `api.close`. */
  readonly artifactPanel?: ((artifact: ArtifactDescriptor, api: AgentArtifactPanelApi) => ReactNode) | undefined;
  /** The host's artifact routing (`ArtifactsConfig`): its cards' `open`, kinds and detection. With `artifactPanel` it still opens tasks; without, every artifact opens in the host. */
  readonly artifacts?: ArtifactsConfig | undefined;
  /** `window` (default when `artifactPanel` is given) opens artifacts in the window's pane; `host` calls `artifacts.open` instead, for a host that shows them in its own viewer. */
  readonly artifactTarget?: 'window' | 'host' | undefined;
}

type Host = FloatingHostProps & { readonly locale?: AppShellLocale | undefined };

/** The spec the layer reads: the agent, with the host's window props merged in. The same object while nothing changes, and the agent itself when the host gave none. */
export function useHostedSpec(agent: AgentSpec, host: Host): AgentSpec {
  const { headerTools, headerActions, onDock, onOpenFull, onFeedback, artifactPanel, artifacts, artifactTarget, locale } = host;
  const given = headerTools !== undefined || headerActions !== undefined || onDock !== undefined || onOpenFull !== undefined || onFeedback !== undefined || artifactPanel !== undefined || artifacts !== undefined;
  return useMemo(() => {
    if (!given) return agent;
    const text = shellWords(locale ?? agent.chatProps?.locale, agent);
    const conversationId = () => String(agent.chatProps?.conversations?.activeId ?? agent.controller.getSnapshot().conversationId);
    const actions: ScreenHeaderAction[] = [...(agent.headerActions ?? []), ...(headerActions ?? []),
      ...(onOpenFull ? [{ id: 'open-full', label: text.openFull, icon: ExternalLinkIcon, onSelect: () => onOpenFull(conversationId()) }] : []),
      ...(onDock ? [{ id: 'dock', label: text.dockChat, icon: PanelLeftIcon, onSelect: onDock }] : [])];
    const replyFooter = withReplyFeedback(onFeedback, text, agent.chatProps?.replyFooter as ((reply: ReplyRef) => ReactNode) | undefined);
    const routed = artifacts ?? agent.chatProps?.artifacts;
    const inWindow = artifactPanel !== undefined && artifactTarget !== 'host';
    return { ...agent,
      ...(actions.length ? { headerActions: actions } : {}),
      ...(headerTools !== undefined ? { headerTools } : {}),
      ...(inWindow ? { artifactPanel } : {}),
      chatProps: { ...agent.chatProps, ...(routed ? { artifacts: routed } : {}), ...(replyFooter ? { replyFooter } : {}) } };
  }, [agent, given, locale, headerTools, headerActions, onDock, onOpenFull, onFeedback, artifactPanel, artifacts, artifactTarget]);
}

/** `embedded`: the conversation in its container, the way the old window embedded it: the chat's own thread and field, the same words, the host's artifact routing and its acknowledgements. */
export function EmbeddedConversation({ agent, locale }: { readonly agent: AgentSpec; readonly locale?: AppShellLocale | undefined }): ReactElement {
  const { controller, chatProps } = agent;
  const lang = locale ?? chatProps?.locale;
  const host = chatProps?.artifacts as ArtifactsConfig | undefined;
  const conversationId = String(chatProps?.conversations?.activeId ?? controller.getSnapshot().conversationId);
  const follow = useArtifactFollow({ controller, conversationId, active: null, onOpen: () => {}, showing: () => true, showingTask: () => true, openPresent: () => false,
    answer: chatProps?.actions?.answer as Parameters<typeof useArtifactFollow>[0]['answer'] });
  const reports = useMemo(() => ({ onShown: follow.onShown, onFailed: follow.onFailed }), [follow.onShown, follow.onFailed]);
  useAutoOpenTasks(controller, host, reports);
  const artifacts = useMemo(() => host ? { ...host, open: (artifact: Parameters<ArtifactsConfig['open']>[0], given?: Parameters<ArtifactsConfig['open']>[1]) => host.open(artifact, given ?? reports) } : undefined, [host, reports]);
  const labels = { ...chatWordLabels(agent.words), ...chatProps?.labels };
  return <div data-testid="composer-embedded" className="flex min-h-0 min-w-0 flex-1 flex-col [&_[data-boring=pi-chat]>header]:hidden">
    <PiChat {...withChatPlugins({ ...chatProps, ...(artifacts ? { artifacts } : {}) })} {...(Object.keys(labels).length > 0 ? { labels } : {})} {...(lang ? { locale: lang } : {})} controller={controller} placement="docked" />
  </div>;
}

'use client';

// `FloatingComposer onFeedback`: thumbs up and down under each finished reply (`chatProps.replyFooter`). Pressing the chosen thumb again takes the rating back (`value` is `null`).
import { useState } from 'react';
import type { ReactNode } from 'react';
import { ThumbsDownIcon, ThumbsUpIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import type { ReplyRef } from '../pi-chat/config';
import type { AppShellText } from './text';

export type ReplyFeedbackHandler = (reply: { readonly key: string; readonly text: string }, value: 'up' | 'down' | null) => void;

function Thumbs({ reply, onFeedback, text }: { readonly reply: ReplyRef; readonly onFeedback: ReplyFeedbackHandler; readonly text: Pick<AppShellText, 'goodResponse' | 'badResponse'> }) {
  const [value, setValue] = useState<'up' | 'down' | null>(null);
  return <div data-testid="reply-feedback" className="-ml-2 flex items-center gap-0.5 pointer-coarse:gap-1">
    {(['up', 'down'] as const).map(which => {
      const label = which === 'up' ? text.goodResponse : text.badResponse;
      const Icon = which === 'up' ? ThumbsUpIcon : ThumbsDownIcon;
      return <Button key={which} variant={value === which ? 'secondary' : 'ghost'} size="icon-sm" data-testid={`feedback-${which}`} aria-label={label} title={label} aria-pressed={value === which}
        onClick={() => { const next = value === which ? null : which; setValue(next); onFeedback({ key: reply.key, text: reply.text }, next); }}><Icon data-icon="inline-start" aria-hidden="true" /></Button>;
    })}
  </div>;
}

/** The reply footer with the thumbs, followed by the host's own footer when it has one. */
export function withReplyFeedback(onFeedback: ReplyFeedbackHandler | undefined, text: Pick<AppShellText, 'goodResponse' | 'badResponse'>, host?: (reply: ReplyRef) => ReactNode): ((reply: ReplyRef) => ReactNode) | undefined {
  if (!onFeedback) return host;
  return reply => <>
    <Thumbs reply={reply} onFeedback={onFeedback} text={text} />
    {host?.(reply)}
  </>;
}

'use client';

// `chatProps.artifacts.autoOpenTasks` on the one composer: while the agent's `present` of a task waits, the host's `artifacts.open` is asked for the task's viewer once, with the layer's reports
// (the viewer must still report its mount or its failure). What the old floating window did for a host that shows tasks in its own viewer.
import { useEffect, useRef } from 'react';
import { useChatView } from '@hachej/boring-ui-kit/chat-react';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { createTaskArtifact, pendingPresents } from '../pi-artifacts/artifact';
import type { ArtifactHostViewApi, ArtifactsConfig } from '../pi-artifacts/artifact';

export function useAutoOpenTasks(controller: NativeChatController, host: ArtifactsConfig | undefined, reports: ArtifactHostViewApi | undefined): void {
  const pending = useChatView(controller, pendingPresents);
  const requested = useRef(new WeakMap<NativeChatController, Set<string>>());
  useEffect(() => {
    if (!host?.autoOpenTasks || !reports) return;
    let asked = requested.current.get(controller);
    if (!asked) { asked = new Set(); requested.current.set(controller, asked); }
    for (const call of pending) {
      if (!('subject' in call) || asked.has(call.id)) continue;
      asked.add(call.id);
      host.open(createTaskArtifact(call.subject), reports);
    }
  }, [controller, host, pending, reports]);
}

'use client';

// The standalone entry of the one composer: a page with no `AppShell` (an existing site) mounts the same bar, floating over the page or folded to its icon, with the same strip, the same
// conversation levels, the unread mark and the needs-you ring. What `AmbientChat` does today, on the shell's composer. No side dock, no right pane: the conversation opens as the window above
// the bar, or full screen; on a phone it is the bottom sheet. Props are the agent and its words; nothing else is configurable. Host concern: Pi has no layout.
import type { ReactElement, ReactNode } from 'react';
import { usePhone } from '../utils/use-media';
import { AgentLayer, AgentLayerProvider } from './agent-layer';
import type { AgentLayerApi, AgentSpec } from './layer-context';
import { ComposerClassContext, NoticeSlotContext } from './float-composer';
import { BarBox } from './agent-placements';
import { shellWords, useInternal } from './layer-context';
import type { ComposerConfig, ComposerEnv } from './composer-config';
import { useComposerInput } from './composer-input';
import { NoticeHost } from './shell-notice';
import { EmbeddedConversation, useHostedSpec } from './floating-host';
import type { FloatingHostProps } from './floating-host';
import { FloatPane } from './float-pane';
import type { AppShellNotice } from './shell-notice';
import type { AppShellLocale } from './text';
import type { Persistence } from '../utils/persisted';

export interface FloatingComposerProps extends FloatingHostProps {
  /** The one assistant: the same `AgentSpec` as `AppShell`'s `agent`. */
  readonly agent: AgentSpec;
  /**
   * The composer's config (`ComposerConfig`), or a function of `{ phone, width, route }` that gives it: `{ launcher: 'circle', handoff: { openFull } }` is a round launcher that opens one panel
   * and hands the conversation to the app's full page; `{ launcher: 'bar', fold: 'circle', float: { movable: true } }` is the bar this component draws by default. The object replaces `start`, `storage` and `onOpenFull`: given with it, they throw.
   */
  readonly composer?: ComposerConfig | ((env: ComposerEnv) => ComposerConfig) | undefined;
  /** The language of the composer's own words (default: the agent's `chatProps.locale`, then English). */
  readonly locale?: AppShellLocale;
  /** A stable id of the host site and, when known, the person: the place and the floating or folded choice are remembered per app and person. */
  readonly appId?: string;
  readonly person?: string;
  /** Where it starts when nothing is remembered: `float` (default) or `icon`. A phone keeps the bar at the bottom (or the icon). */
  readonly start?: 'float' | 'icon';
  /**
   * Things to tell the person, newest first: the shell's `notices` (one at a time, the others behind it as « N more waiting »), drawn above the floating bar (below it from a top corner),
   * above the folded icon and above the bottom bar, and above the field on a phone. Absent: none. A function gets the layer's api, so a notice's action can open the conversation or bring the icon back.
   */
  readonly notices?: readonly AppShellNotice[] | ((layer: Omit<AgentLayerApi, 'agent'>) => readonly AppShellNotice[]) | undefined;
  /** Where the place (floating, folded, the corner or free position) is remembered: `local` (default, kept across visits) or `session` (this browser tab only). */
  readonly storage?: Persistence;
  /** The key the old floating bar (`AmbientChat`) kept its dragged position under (`{ right, bottom }`). With no place of its own yet, the composer starts where that was, once: nothing is lost on an upgrade. Read from `legacyPositionStorage` (default `session`, as the old bar). */
  readonly legacyPositionKey?: string;
  readonly legacyPositionStorage?: Persistence;
  /** Classes for the composer's own box (the floating frame, the folded icon, the bottom bar of a wide window; a phone's bottom sheet is the shell's own), so a host can move or size it. */
  readonly className?: string;
  /** How long a notice stays before it fades, in ms; `0` keeps it until dismissed. Applies to every kind but a warning (a decision waits). Default: info and success fade after 8 s, errors stay. */
  readonly autoDismissMs?: number;
  /** The most notices kept (one shows at a time, the others wait behind it as « N more »): the oldest info and success go first, a warning or an error is never dropped. Default 5. */
  readonly maxToasts?: number;
  /** Rendered inside the composer's layer, so it can read `useAgentLayer()` (a host bridge that mirrors the place and the open conversation). Draws nothing of its own. */
  readonly children?: ReactNode;
}

const NONE: readonly AppShellNotice[] = [];
const NO_LEGACY: readonly string[] = [];

function Surface({ notices: given = NONE, autoDismissMs, maxToasts }: { readonly notices?: FloatingComposerProps['notices']; readonly autoDismissMs?: number | undefined; readonly maxToasts?: number | undefined }): ReactElement {
  const layer = useInternal();
  const phone = usePhone();
  const notices = typeof given === 'function' ? given(layer) : given;
  const host = notices.length ? <NoticeHost notices={notices} text={shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent)} compact={phone} fadeMs={autoDismissMs} max={maxToasts} /> : null;
  return <NoticeSlotContext.Provider value={phone ? null : host}>
    <div className="app-shell contents">
      {layer.contentComposer && <BarBox standalone />}
      {/* A phone has no floating frame: the notice stands on the foot of the screen (`NoticeHost` lifts itself over the peek). */}
      {phone && host && <div data-testid="composer-notices" className="fixed inset-x-0 bottom-0 z-(--z-app-shell-layer)">{host}</div>}
      <AgentLayer />
      {/* Wide: the pane's entries (an artifact, a file, an app view) open in a window beside the bar; a phone shows them full screen (`AgentLayer`). */}
      {!phone && <FloatPane />}
    </div>
  </NoticeSlotContext.Provider>;
}

/** The one composer on a page that has no AppShell. Mount it once, anywhere: it positions itself over the page. */
export function FloatingComposer({ agent, composer, locale, appId, person, start, notices, storage, legacyPositionKey, legacyPositionStorage = 'session', className, autoDismissMs, maxToasts, children, embedded, headerTools, headerActions, onDock, onOpenFull, onFeedback, artifactPanel, artifacts, artifactTarget }: FloatingComposerProps): ReactElement {
  const resolved = useComposerInput(composer);
  const config = typeof resolved === 'object' ? resolved : undefined;
  // The object replaces the props it makes second sources; the resolver throws when it is given next to them.
  const legacy = config ? [['start', start], ['storage', storage], ['onOpenFull', onOpenFull]].flatMap(([name, value]) => value === undefined ? [] : [name as string]) : NO_LEGACY;
  const spec = useHostedSpec(agent, { locale, headerTools, headerActions, onDock, onOpenFull, onFeedback, artifactPanel, artifacts, artifactTarget });
  if (embedded) return <EmbeddedConversation agent={spec} locale={locale} />;
  const remember = config?.at?.remember === undefined ? undefined : config.at.remember === 'local' ? 'local' : 'session';
  return <AgentLayerProvider agent={spec} composer={config ?? 'bar'} floating={config === undefined} standalone legacy={legacy} docks={false} agentLink={false} {...(locale ? { locale } : {})} startIn={start ?? 'float'} storage={storage ?? remember ?? 'local'} modeIdentity={{ ...(appId ? { app: appId } : {}), ...(person ? { person } : {}) }}
    {...(legacyPositionKey ? { legacyPosition: { key: legacyPositionKey, storage: legacyPositionStorage } } : {})}>
    {children}
    <ComposerClassContext.Provider value={className}><Surface notices={notices} autoDismissMs={autoDismissMs} maxToasts={maxToasts} /></ComposerClassContext.Provider>
  </AgentLayerProvider>;
}

'use client';

// The one list/detail primitive of layout B. Expanded: the list (20rem, or a `railWidth` rail when `collapsible` and folded; its own scroll) and the detail side by side. Compact: one pane at a
// time; opening a detail is a stack step (one history entry, Back returns to the list) and the list stays mounted, hidden, so its scroll is
// kept. Host concern: Pi has no layout. A deep link that mounts with a detail needs nothing more: the Back manager's entry sits above the
// one the page was opened on, and the app's `onBack` (called by Back, and by « ← » which is Back) clears the selection and replaces the URL.
import { useContext, useState } from 'react';
import type { ReactNode } from 'react';
import { ChevronsLeftIcon, ChevronsRightIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { cn } from '../utils/utils';
import { ScreenActiveContext } from './agent-context';
import { useBackLayer } from '../utils/back';
import { useIsCompact } from './compact';
import { useScreenHeader } from './header';

export interface ListDetailProps {
  /** The list pane (the app's own list; a card list when compact is the app's choice through `useIsCompact`). */
  readonly list: ReactNode | ((state: { readonly collapsed: boolean }) => ReactNode);
  /** `null` = nothing selected. */
  readonly detail: ReactNode | null;
  /** Clears the selection and replaces the URL: called by compact Back and by the header's « ← » (which goes through the browser's Back). */
  readonly onBack: () => void;
  /** Wide screens: what the detail pane shows while nothing is selected (centred, e.g. a muted line « Choisissez une consultation »). Default: nothing. */
  readonly empty?: ReactNode;
  /** The detail's header title when compact (default: the screen's own). */
  readonly title?: string;
  /** Wide screens only: the list pane can fold to a narrow rail (`railWidth`), with a toggle on its edge. Give `list` as a function to render the rail's content. Default: fixed 20rem, no toggle. */
  readonly collapsible?: boolean;
  /** Controlled fold state; without it the pane keeps its own (starting open). */
  readonly collapsed?: boolean;
  readonly onCollapsedChange?: (collapsed: boolean) => void;
  /** The rail's width when collapsed (any CSS length). Default `3rem`, the shell's icon rail. */
  readonly railWidth?: string;
  /** The toggle's accessible names. Default English. */
  readonly labels?: { readonly collapse: string; readonly expand: string };
}

/** Which panes show: both when expanded; when compact the detail if one is selected, else the list. */
export function listDetailView(compact: boolean, detail: ReactNode | null): 'list' | 'detail' | 'both' {
  return !compact ? 'both' : detail === null ? 'list' : 'detail';
}

export function ListDetail({ list, detail, empty, onBack, title, collapsible, collapsed: controlled, onCollapsedChange, railWidth = '3rem', labels = { collapse: 'Collapse the list', expand: 'Expand the list' } }: ListDetailProps) {
  const compact = useIsCompact();
  const [own, setOwn] = useState(false);
  const folds = Boolean(collapsible) && !compact;
  const collapsed = folds && (controlled ?? own);
  const toggle = () => { if (controlled === undefined) setOwn(!collapsed); onCollapsedChange?.(!collapsed); };
  const active = useContext(ScreenActiveContext);
  const view = listDetailView(compact, detail);
  const stacked = view === 'detail';
  useBackLayer(active && stacked, onBack, 'stack');
  // « ← » is the browser's Back, so there is one path: the popstate calls `onBack`, and the URL the entry below holds is the one the app then replaces.
  useScreenHeader(stacked ? { back: () => history.back(), ...(title ? { title } : {}) } : {}, { overlay: true });
  return <div data-testid="list-detail" data-view={view} className="flex h-full min-h-0">
    <div hidden={view === 'detail'} data-testid="list-pane" data-collapsed={folds ? collapsed : undefined} style={collapsed ? { width: railWidth } : undefined}
      className={cn('min-h-0 overflow-y-auto overscroll-contain', compact ? 'w-full' : collapsed ? 'shrink-0' : 'w-80 shrink-0')}>{folds && <div className={cn('flex p-1', collapsed ? 'justify-center' : 'justify-end')}>
        <Button variant="ghost" size="icon-sm" data-testid="list-toggle" aria-expanded={!collapsed} aria-label={collapsed ? labels.expand : labels.collapse} title={collapsed ? labels.expand : labels.collapse} onClick={toggle}>
          {collapsed ? <ChevronsRightIcon /> : <ChevronsLeftIcon />}
        </Button>
      </div>}
      {typeof list === 'function' ? list({ collapsed }) : list}</div>
    <div hidden={view === 'list'} data-testid="detail-pane" className={cn('min-h-0 min-w-0 flex-1 overflow-y-auto overscroll-contain', view !== 'list' && detail === null && empty != null && 'grid place-items-center p-6 text-sm text-muted-foreground')}>{detail ?? empty}</div>
  </div>;
}

// The screen's one left margin. A screen wraps its content in `ScreenBody`: it pads the inline sides with `--screen-gutter` (the theme token; 1rem, 0.75rem under
// `data-density="compact"`, fallback 1rem), the same value the shell's header title starts on, so title and body share one left edge. Block padding is the gutter too.
// A list, table or `ListDetail` that draws its own rows passes `bleed`: no inline padding (rows and dividers run edge to edge), and the first cell of each
// `li`, `tr` or `[role=row]` gets `padding-inline-start: var(--screen-gutter, 1rem)` from the app-shell item's css (zero specificity: a row's own padding wins), so its text still sits on the gutter.
// A screen needs no bottom padding for the assistant's bar: the shell pads each screen box with `--agent-bar-reserve` (`bar-reserve.ts`), so the last control scrolls above it.
// Host concern: Pi has no layout.
import type { ComponentProps } from 'react';

export interface ScreenBodyProps extends ComponentProps<'div'> {
  /** No inline padding, for a list, table or `ListDetail` that runs edge to edge; its rows' first cells keep the text on the gutter. */
  readonly bleed?: boolean;
}

export function ScreenBody({ bleed = false, className, ...props }: ScreenBodyProps) {
  return <div data-slot="screen-body" {...(bleed ? { 'data-bleed': '' } : {})} className={`${bleed ? 'py-[var(--screen-gutter,1rem)]' : 'p-[var(--screen-gutter,1rem)]'}${className ? ` ${className}` : ''}`} {...props} />;
}

'use client';

// One header per screen. A screen calls `useScreenHeader` and the shell renders it; the most recently mounted caller wins as a whole
// (a `ListDetail` inside a screen overlays « ← » and a title and keeps the screen's actions) and unmounting restores the previous one. A
// screen the shell has hidden does not count (ScreenActiveContext). Host concern: Pi has no layout.
import { createContext, createElement, useContext, useLayoutEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { ArrowLeftIcon } from '../_shared/icons';
import { SidebarTrigger } from '@/components/ui/sidebar';
import { Button } from '@/components/ui/button';
import { ScreenActiveContext } from './agent-context';
import { HeaderActions } from './header-actions';
import type { ScreenHeaderAction } from './header-actions';
import { AgentTrigger } from './agent-layer';
import { McpSetup } from '../mcp-setup/mcp-setup';
import type { McpSetupProps } from '../mcp-setup/mcp-setup';
import type { AppShellText } from './text';

interface Icon { className?: string }
export interface ScreenHeaderSpec {
  /** Default: the active nav label. */
  readonly title?: string;
  readonly subtitle?: string;
  /** Shows « ← ». */
  readonly back?: () => void;
  /** At most two are shown; the others go in « … ». */
  readonly actions?: readonly ScreenHeaderAction[];
  /** Controls rendered right after « ← » (on a phone with `compactNav="sheet"`, after the menu button), before the title: a screen that owns its row, left-aligned. */
  readonly leading?: ReactNode;
  /** The title's face: `display` (default, the theme's display font) or `sans`. */
  readonly titleFace?: 'display' | 'sans';
  /** A dense 48 px row instead of 56 px. */
  readonly dense?: boolean;
}

export type { ScreenHeaderAction } from './header-actions';

interface Entry { spec: ScreenHeaderSpec; readonly overlay: boolean }
interface Store {
  readonly entries: Entry[];
  version: number;
  readonly listeners: Set<() => void>;
}

const HeaderContext = createContext<Store | null>(null);

/** A number per icon component, so a change of icon is a change of header. */
const icons = new WeakMap<object, number>();
let iconCount = 0;
const iconId = (icon: ComponentType<Icon>): number => { let id = icons.get(icon); if (id === undefined) { iconCount += 1; id = iconCount; icons.set(icon, id); } return id; };

const touch = (store: Store) => { store.version += 1; for (const listener of [...store.listeners]) listener(); };

/** Holds the screens' headers. `AppShell` mounts one. */
export function HeaderProvider({ children }: { readonly children: ReactNode }) {
  const [store] = useState<Store>(() => ({ entries: [], version: 0, listeners: new Set() }));
  return createElement(HeaderContext.Provider, { value: store }, children);
}

/**
 * Registers the calling screen's header while it is mounted and on show. The latest spec is always read at click time. An `overlay`
 * (the shell's own `ListDetail`) is merged over the screen's header whatever the effect order: it adds « ← » and a title, and keeps the actions.
 */
export function useScreenHeader(spec: ScreenHeaderSpec, options?: { readonly overlay?: boolean }): void {
  const store = useContext(HeaderContext);
  const active = useContext(ScreenActiveContext);
  const entry = useRef<Entry>({ spec, overlay: options?.overlay === true });
  useLayoutEffect(() => { entry.current.spec = spec; });
  const key = JSON.stringify([spec.title, spec.subtitle, Boolean(spec.back), spec.titleFace, spec.dense, spec.actions?.map(action => [action.id, action.label, action.showLabel, action.href, action.target, action.rel, iconId(action.icon)])]);
  useLayoutEffect(() => {
    if (!store || !active) return;
    const mine = entry.current;
    store.entries.push(mine);
    touch(store);
    return () => { const at = store.entries.indexOf(mine); if (at >= 0) store.entries.splice(at, 1); touch(store); };
  }, [store, active]);
  // `leading` is a node with no stable key, so it is a new value on each render of the screen and touches the store each time; that only re-renders the header, which is cheap and intended.
  useLayoutEffect(() => { if (store && active) touch(store); }, [store, active, key, spec.leading]);
}

/** The header of the screen on show (the most recently mounted caller), or undefined. Re-renders when screens come and go or change their header. */
export function useTopHeader(): { readonly spec: ScreenHeaderSpec } | undefined {
  const store = useContext(HeaderContext);
  useSyncExternalStore(
    listener => { store?.listeners.add(listener); return () => { store?.listeners.delete(listener); }; },
    () => store?.version ?? 0,
    () => 0,
  );
  // A getter, so a click reads the live specs (a callback that changed without a visible change is still the current one).
  return store?.entries.length ? { get spec() { return mergedSpec(store.entries); } } : undefined;
}

/** The latest ordinary entry is the whole header; explicit overlays (the shell's `ListDetail`) are merged over it field by field. */
function mergedSpec(entries: readonly Entry[]): ScreenHeaderSpec {
  const base = entries.filter(entry => !entry.overlay).at(-1);
  const spec: Record<string, unknown> = { ...base?.spec };
  for (const entry of entries) if (entry.overlay) for (const [field, value] of Object.entries(entry.spec)) if (value !== undefined) spec[field] = value;
  return spec as ScreenHeaderSpec;
}


/**
 * The header of the screen on show: the avatar button (compact) or « ← », then the title and subtitle,
 * then the slot of the screen's own controls (`slotRef`), up to two actions, « … » and the agent trigger. `avatar` is the compact account button. `menu` (compact only) makes the leading button open the sidebar sheet and leaves the account to the sidebar's footer. The sidebar toggle of a wide screen lives in the sidebar's own header (`AppSidebar`), not here: on a phone the sheet does not exist while closed, so its opener stays in this header.
 */
export function ScreenHeader({ fallbackTitle, compact, leadingAvatar = false, trigger = true, avatar, text, slotRef, menu, screenSidebar, mcp }: { readonly mcp?: McpSetupProps | undefined; readonly leadingAvatar?: boolean; readonly trigger?: boolean; readonly menu?: boolean; readonly screenSidebar?: ReactNode; readonly fallbackTitle: string; readonly compact: boolean; readonly avatar: ReactNode; readonly text: AppShellText; readonly slotRef?: (element: HTMLElement | null) => void }) {
  const top = useTopHeader();
  const spec = top?.spec;
  const actions = spec?.actions ?? [];
  const run = (id: string) => top?.spec.actions?.find(action => action.id === id)?.onSelect();
  const back = spec?.back ? <Button variant="ghost" size="icon" data-testid="header-back" aria-label={text.goBack} title={text.goBack} onClick={() => top?.spec.back?.()}><ArrowLeftIcon data-icon="inline-start" aria-hidden="true" /></Button> : null;
  // The title starts on the screen gutter (the body's left edge) when it is the first thing in the header; a button or control before it keeps a small gap instead.
  // `leadingAvatar` (AppShell `sidebar={false}`): the account menu leads the bar at every width, as on a phone.
  const lead = compact || leadingAvatar;
  const precedes = Boolean(spec?.leading != null || back || (lead && (menu || avatar || screenSidebar)));
  return <header data-testid="screen-header" className={`sticky top-0 z-raised flex ${spec?.dense ? 'min-h-12' : 'min-h-14'} shrink-0 items-center gap-1 bg-card px-[var(--screen-gutter,1rem)] pt-(--app-shell-safe-top)`}>
    {lead ? (back ?? (menu ? <SidebarTrigger /> : avatar)) : back}
    {compact && screenSidebar}
    {spec?.leading != null && <div data-testid="header-leading" className="flex min-w-0 shrink items-center gap-1">{spec.leading}</div>}
    <div className={`min-w-0 flex-1 pe-1 ${precedes ? 'ps-1' : ''}`}>
      <h1 data-testid="header-title" className={`m-0 truncate text-sm leading-tight font-semibold ${spec?.titleFace === 'sans' ? 'font-sans' : '[font-family:var(--font-display,var(--font-sans))]'}`}>{spec?.title ?? fallbackTitle}</h1>
      {spec?.subtitle && <p data-testid="header-subtitle" className="m-0 truncate text-xs text-muted-foreground">{spec.subtitle}</p>}
    </div>
    {/* An embedded page's own controls (`ScreenHeaderSlotContext`, for example AgentWorkspace layout="embedded"), so it needs no second row. */}
    <div ref={slotRef} data-testid="header-slot" className="flex shrink-0 items-center gap-1 empty:hidden" />
    {/* The MCP door: after the screen's own controls, just before its actions (a panel toggle) and the agent's button. */}
    {mcp && <McpSetup {...mcp} />}
    <HeaderActions actions={actions} compact={compact} text={text} prefix="header" run={run} />
    {lead && back && !menu && avatar}
    {trigger && <AgentTrigger />}
  </header>;
}

'use client';

// The header actions (`ScreenHeaderAction`) and their renderer, shared by the screen header and the AgentLayer header: up to two icon or label
// buttons (or links), the rest in « … ». Imports nothing from header.tsx or agent-layer.tsx (the shell's import graph has no cycle).
import { useState } from 'react';
import type { ComponentType, MouseEvent } from 'react';
import { EllipsisIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { afterBack } from '../utils/back';
import { AppSheet, SHEET_ROW } from './app-sheet';
import type { AppShellText } from './text';

interface Icon { className?: string }
export interface ScreenHeaderAction {
  readonly id: string;
  /** The accessible name and the tooltip. */
  readonly label: string;
  readonly icon: ComponentType<Icon>;
  /** `'always'` also shows the label as text next to the icon (default: icon only, at every width). */
  readonly showLabel?: 'always';
  /** The action is a link (an anchor); `onSelect` still runs on click. `target` and `rel` are set only when the host passes them. */
  readonly href?: string;
  readonly target?: string;
  readonly rel?: string;
  /** `'menu'`: always in « … », never as a button, whatever the count. */
  readonly placement?: 'menu';
  readonly onSelect: () => void;
}

/** One action as a control: an anchor when it has `href`, else a button. `onSelect` is the caller's run (it reads the live action at click time). */
function ActionControl({ action, prefix, onSelect }: { readonly action: ScreenHeaderAction; readonly prefix: string; readonly onSelect: () => void }) {
  const content = <><action.icon data-icon="inline-start" aria-hidden="true" />{action.showLabel === 'always' && action.label}</>;
  return <Button variant="ghost" size={action.showLabel === 'always' ? 'default' : 'icon'}
    {...(action.href !== undefined ? { nativeButton: false, render: <a href={action.href} target={action.target} rel={action.rel} /> } : {})}
    data-testid={`${prefix}-action-${action.id}`} aria-label={action.label} title={action.label} onClick={onSelect}>{content}</Button>;
}

/** Up to two actions as controls; the rest go in « … » (a sheet when compact, a menu otherwise). `prefix` names the test ids. Shared with the AgentLayer header. */
export function HeaderActions({ actions, compact, text, prefix, run }: { readonly actions: readonly ScreenHeaderAction[]; readonly compact: boolean; readonly text: AppShellText; readonly prefix: string; readonly run: (id: string) => void }) {
  const inline = actions.filter(action => action.placement !== 'menu');
  const shown = inline.slice(0, 2), extra = [...inline.slice(2), ...actions.filter(action => action.placement === 'menu')];
  const [sheetOpen, setSheetOpen] = useState(false);
  // A link in the phone sheet: the sheet closes first and a same-tab navigation waits for its history entry (afterBack), so the Back
  // manager never undoes it. A new tab, or a modified click, keeps the browser's own default.
  const sheetLink = (event: MouseEvent<HTMLElement>, action: ScreenHeaderAction) => {
    setSheetOpen(false);
    if ((action.target !== undefined && action.target !== '_self') || event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) { afterBack(() => run(action.id)); return; }
    event.preventDefault();
    const href = action.href ?? '';
    afterBack(() => { run(action.id); window.location.assign(href); });
  };
  return <>
    {shown.map(action => <ActionControl key={action.id} action={action} prefix={prefix} onSelect={() => run(action.id)} />)}
    {extra.length > 0 && (compact
      ? <>
        <Button variant="ghost" size="icon" data-testid={`${prefix}-more`} aria-label={text.actions} title={text.actions} onClick={() => setSheetOpen(true)}><EllipsisIcon data-icon="inline-start" aria-hidden="true" /></Button>
        <AppSheet open={sheetOpen} onOpenChange={setSheetOpen} title={text.actions}>
          {extra.map(action => action.href === undefined
            ? <Button key={action.id} variant="ghost" size="lg" data-testid={`${prefix}-action-${action.id}`} className={SHEET_ROW} onClick={() => { setSheetOpen(false); afterBack(() => run(action.id)); }}><action.icon data-icon="inline-start" />{action.label}</Button>
            : <Button key={action.id} variant="ghost" size="lg" nativeButton={false} render={<a href={action.href} target={action.target} rel={action.rel} />} data-testid={`${prefix}-action-${action.id}`} className={SHEET_ROW} onClick={event => sheetLink(event, action)}><action.icon data-icon="inline-start" />{action.label}</Button>)}
        </AppSheet>
      </>
      : <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon" />} data-testid={`${prefix}-more`} aria-label={text.actions} title={text.actions}><EllipsisIcon data-icon="inline-start" aria-hidden="true" /></DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="app-shell w-48">
          {extra.map(action => <DropdownMenuItem key={action.id} data-testid={`${prefix}-action-${action.id}`} className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onClick={() => run(action.id)}
            render={action.href === undefined ? undefined : <a href={action.href} target={action.target} rel={action.rel} />}><action.icon className="size-4" />{action.label}</DropdownMenuItem>)}
        </DropdownMenuContent>
      </DropdownMenu>)}
  </>;
}

'use client';

// The navigation: a bottom tab bar when compact, the shadcn sidebar (icon rail plus NavUser, the sidebar-07 and sidebar-08 patterns) when
// expanded. Choosing an item only calls `route.onChange`: the app's router owns the URL, and the shell adds no history entry.
import { useEffect, useRef, useState } from 'react';
import type { ComponentType, KeyboardEvent, ReactNode } from 'react';
import { EllipsisIcon, PinIcon, SparklesIcon } from '../_shared/icons';
import { Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarSeparator, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { afterBack, BACK_SETTLE_MS, useBackLayer } from '../utils/back';
import { NavUser } from './account';
import { useAgentLayer } from './agent-layer';
import type { AgentSpec } from './agent-layer';
import type { ComposerConfig } from './composer-config';
import type { AccountSpec } from './account';
import { AppSheet, SHEET_ROW } from './app-sheet';
import { InsideNavSheet, useExclusiveSheet } from './use-exclusive-sheet';
import type { AppShellText } from './text';
import { ResizableRail } from './sidebar-resize';
import { useSidebarPin } from './sidebar-open';

export interface NavBadge {
  readonly tone: 'info' | 'success' | 'warning' | 'destructive';
  readonly label: string;
}

export interface NavItem {
  readonly id: string;
  readonly label: string;
  readonly icon: ComponentType<{ className?: string }>;
  /** A state dot on the item. Both are required, so the dot always means something: `tone` picks the colour (info, success, warning, destructive tokens), `label` is its accessible name (« Nuit à noter »). No dot, no state: leave it out. */
  readonly badge?: NavBadge;
  readonly render: () => ReactNode;
  /** The screen's own content inside the shell's sidebar (its list, say) while this item is on show: above the nav items, which move below it. `collapsed` is true on the icon rail, so the content can fold with it. */
  readonly sidebar?: (state: { readonly collapsed: boolean }) => ReactNode;
  /** The sidebar content's own name, for the phone button that opens it in tabs mode (« Library »): its label reads « <item label>: <sidebarLabel> ». Default: the shell's word for « panel ». */
  readonly sidebarLabel?: string;
  /** Where this item sits against a screen's own sidebar content: `'before-sidebar'` puts it above that content, `'after-sidebar'` (the default) below. Items marked before come first everywhere (the tab bar and the phone sheet too); each side keeps the registered order. */
  readonly placement?: 'before-sidebar' | 'after-sidebar';
  /** The composer on this screen: `false` hides it here (the launcher is suspended and the conversation read: the full-page support route), or a config object replaces the app's `composer` for this screen. Absent: the app's own. */
  readonly composer?: ComposerConfig | false;
}

/** The items marked `before-sidebar`, then the others, each in registered order. */
export function placeNav<T extends Pick<NavItem, 'placement'>>(items: readonly T[]): { readonly before: readonly T[]; readonly after: readonly T[] } {
  return { before: items.filter(item => item.placement === 'before-sidebar'), after: items.filter(item => item.placement !== 'before-sidebar') };
}

/** The most tabs the bar shows. */
const MAX_TABS = 4;

/** Up to four items are all tabs; more than four give three tabs and the rest behind « Plus ». */
export function splitNav<T>(items: readonly T[]): { readonly tabs: readonly T[]; readonly overflow: readonly T[] } {
  return items.length <= MAX_TABS ? { tabs: items, overflow: [] } : { tabs: items.slice(0, MAX_TABS - 1), overflow: items.slice(MAX_TABS - 1) };
}

const DOT_TONE = { info: 'bg-info', success: 'bg-success', warning: 'bg-warning', destructive: 'bg-destructive' } as const;

/** A state dot: a plain 8px span in the tone's token, named by its label. Its classes only place it. */
// A hidden comma before the dot gives screen readers a pause: the item reads « Plus, Nuit à noter », not « Plus Nuit à noter ». It is generated content, so the item's textContent stays « Plus », and it takes the dot's className so it hides with the dot (collapsed rail).
const Dot = ({ badge, className }: { readonly badge: NavBadge; readonly className?: string }) => <><span className={`sr-only before:content-[',_'] ${className ?? ''}`} /><span role="img" aria-label={badge.label} data-testid="nav-badge" className={`inline-block size-2 shrink-0 rounded-full ${DOT_TONE[badge.tone]} ${className ?? ''}`} /></>;

/** Publishes the bar's measured height as `--app-shell-tabbar` on the document root (the drawer is portaled, so the shell root is too high up to reach it). */
function useTabbarHeight(bar: { readonly current: HTMLElement | null }, shown: boolean): void {
  useEffect(() => {
    const root = document.documentElement;
    const node = bar.current;
    if (!shown || !node) { root.style.setProperty('--app-shell-tabbar', '0px'); return; }
    const measure = () => root.style.setProperty('--app-shell-tabbar', `${node.getBoundingClientRect().height}px`);
    measure();
    const observer = typeof ResizeObserver === 'function' ? new ResizeObserver(measure) : undefined;
    observer?.observe(node);
    return () => { observer?.disconnect(); root.style.removeProperty('--app-shell-tabbar'); };
  }, [bar, shown]);
}

/** Layout for a tab on the host's Button: icon over label, filling its share of the bar. */
const TAB = 'relative h-auto min-w-0 flex-1 flex-col gap-0.5';

/** The tab bar's arrow keys: Left and Right move the focus between the tabs (wrapping). */
const arrows = (event: KeyboardEvent<HTMLElement>) => {
  const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>('[role=tab]')];
  const at = buttons.indexOf(document.activeElement as HTMLElement);
  const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0;
  if (at < 0 || !step) return;
  event.preventDefault();
  buttons[(at + step + buttons.length) % buttons.length]!.focus();
};

/** The compact tab bar. With one item there is none. Exported for tests. */
export function TabBar({ items, activeId, onChange, text }: { readonly items: readonly NavItem[]; readonly activeId: string; readonly onChange: (id: string) => void; readonly text: AppShellText }) {
  const bar = useRef<HTMLElement>(null);
  const [plusOpen, setPlusOpen] = useState(false);
  const shown = items.length > 1;
  useTabbarHeight(bar, shown);
  if (!shown) return null;
  const { before, after } = placeNav(items);
  const { tabs, overflow } = splitNav([...before, ...after]);
  const inOverflow = overflow.find(item => item.id === activeId);
  /** « Plus » stands for the hidden items: it shows the dot of the first badged one other than the item on show (that one has its own tab face). */
  const hidden = overflow.find(item => item.id !== activeId && item.badge)?.badge;
  const tab = (item: NavItem) => <Button key={item.id} variant={item.id === activeId ? 'secondary' : 'ghost'} role="tab" data-testid={`tab-${item.id}`} aria-selected={item.id === activeId} tabIndex={item.id === activeId ? 0 : -1}
    onClick={() => onChange(item.id)} className={TAB}>
    <item.icon />{item.label}{item.badge && <Dot badge={item.badge} className="absolute top-1 left-1/2 ml-2" />}
  </Button>;
  // « Plus » always keeps its own icon and word (a dot belongs to the label it sits next to); the header names the screen on show.
  const Plus = overflow.length ? EllipsisIcon : undefined;
  return <nav ref={bar} role="tablist" aria-label={text.tabs} data-testid="tabbar" data-feedback-ignore="" onKeyDown={arrows}
    className="relative z-(--z-app-shell-tabs) box-border flex min-h-(--app-shell-tabbar-min) shrink-0 bg-sidebar px-2 pb-(--app-shell-safe-bottom)">
    {tabs.map(tab)}
    {Plus && <>
      <Button variant={inOverflow ? 'secondary' : 'ghost'} role="tab" data-testid="tab-plus" aria-selected={Boolean(inOverflow)} aria-haspopup="dialog" tabIndex={inOverflow ? 0 : -1} onClick={() => setPlusOpen(true)}
        className={TAB}>
        <Plus />{text.more}{hidden && <Dot badge={hidden} className="absolute top-1 left-1/2 ml-2" />}
      </Button>
      <AppSheet open={plusOpen} onOpenChange={setPlusOpen} title={text.more}>
        {overflow.map(item => <Button key={item.id} variant={item.id === activeId ? 'secondary' : 'ghost'} size="lg" data-testid={`plus-${item.id}`} aria-current={item.id === activeId} className={SHEET_ROW}
          onClick={() => { setPlusOpen(false); afterBack(() => onChange(item.id)); }}>
          <item.icon data-icon="inline-start" />{item.label}{item.badge && <Dot badge={item.badge} className="ml-auto" />}
        </Button>)}
      </AppSheet>
    </>}
  </nav>;
}

/** What keeps the sheet open, checked from the tapped element up: a field to type in, or anything under `data-keep-sheet`. */
const KEEPS = 'input, textarea, select, [contenteditable=""], [contenteditable=true], [data-keep-sheet]';
/** What a tap on a row of the sidebar content counts as « choosing a row »: it closes the sheet. A field to type in does not, and an element may opt out with `data-keep-sheet`. */
const CHOOSES = 'a, button, [role=button], [role=option], [role=menuitem], [role=treeitem], [role=row], [role=link]';

/**
 * Tabs mode on a phone: the current item's `sidebar` has no sidebar to live in, so the header carries a leading button that opens that same content in a left sheet
 * (the width of `compactNav="sheet"`). Choosing a row closes the sheet. An item without a `sidebar` renders nothing. Exported for the header.
 */
export function ScreenSidebarSheet({ item, text }: { readonly item: NavItem; readonly text: AppShellText }) {
  // `open` owns the Back entry; `shown` keeps the sheet mounted while a chosen row's click is replayed once that entry has gone.
  const [open, setOpen] = useState(false);
  const [shown, setShown] = useState(false);
  const replaying = useRef(false);
  const choosing = useRef(false);
  // The choice held behind the sheet's Back; unmounting or settling drops it.
  const pending = useRef<object | null>(null);
  useEffect(() => () => { pending.current = null; }, []);
  const close = () => { pending.current = null; choosing.current = false; setOpen(false); setShown(false); };
  useExclusiveSheet(open, close);
  useBackLayer(open, close, 'sheet');
  if (!item.sidebar) return null;
  const name = `${item.label}: ${item.sidebarLabel ?? text.panel}`;
  return <>
    <Button variant="ghost" size="icon" data-testid="screen-sidebar-button" aria-label={name} title={name} aria-haspopup="dialog" aria-expanded={open} onClick={() => { setOpen(true); setShown(true); }}><item.icon data-icon="inline-start" aria-hidden="true" /></Button>
    <Sheet open={shown} onOpenChange={next => { if (!next) close(); }}>
      <SheetContent side="left" showCloseButton={false} data-testid="screen-sidebar-sheet" className="app-shell data-[side=left]:w-[var(--sidebar-width-mobile,75%)]">
        <SheetHeader className="sr-only"><SheetTitle>{name}</SheetTitle><SheetDescription>{name}</SheetDescription></SheetHeader>
        <div data-testid="screen-sidebar-content" className="flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain bg-sidebar pb-(--app-shell-safe-bottom) text-sidebar-foreground"
          onClickCapture={event => {
            // The choice is held back: the sheet lets go of its Back entry first, and only then does the row's own click (a router push, a link) run, so that entry's `history.back()` cannot undo it.
            const target = event.target;
            // A modified or non-primary click (new tab, new window, middle button) is not a choice: it goes through untouched and the sheet stays open.
            const { button, metaKey, ctrlKey, shiftKey, altKey } = event;
            if (replaying.current || !(target instanceof Element) || target.closest(KEEPS) || !target.closest(CHOOSES) || button !== 0 || metaKey || ctrlKey || shiftKey || altKey) return;
            event.preventDefault();
            event.stopPropagation();
            // One choice at a time: a second tap while the sheet is closing is swallowed, so a navigating row navigates once.
            if (choosing.current) return;
            choosing.current = true;
            const mine = {};
            pending.current = mine;
            setOpen(false);
            // A Back that never lands settles after a bounded wait: the choice is dropped (never run ahead of the traversal) and the sheet closes.
            setTimeout(() => { if (pending.current !== mine) return; pending.current = null; choosing.current = false; setShown(false); }, BACK_SETTLE_MS);
            afterBack(() => {
              if (pending.current !== mine) return;
              pending.current = null;
              if (target.isConnected) {
                replaying.current = true;
                try { target.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true })); } finally { replaying.current = false; }
              }
              choosing.current = false;
              setShown(false);
            });
          }}>
          {item.sidebar({ collapsed: false })}
        </div>
      </SheetContent>
    </Sheet>
  </>;
}

/** Hover intent of the hover rail, in ms: the pointer must stay this long to reveal the pane, and be gone this long (focus too) to fold it. */
const HOVER_REVEAL_MS = 150;
const HOVER_FOLD_MS = 300;

/** The expanded sidebar: the app title, the nav items (none with one item) and the account in the footer. */
export function AppSidebar({ rail = 'icon', identity, title, items, activeId, onChange, agent, agentNav = 'end', account, improve, text }: {
  readonly agentNav?: 'end' | 'above-bottom';
  readonly rail?: 'icon' | 'hover'; readonly identity?: { readonly app?: string | undefined; readonly person?: string | undefined }; readonly title: string; readonly items: readonly NavItem[]; readonly activeId: string; readonly onChange: (id: string) => void;
  readonly agent: AgentSpec | undefined; readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText;
}) {
  const { setOpen, openMobile, setOpenMobile, state, isMobile } = useSidebar();
  // The hover rail's pin (D-2010): on a wide screen only. Pinned, the pane is open whatever the pointer and focus do and the page sits beside it.
  const hover = rail === 'hover' && !isMobile;
  const { pinned, set: setPinned } = useSidebarPin(hover, identity ?? {});
  const wrapper = useRef<HTMLDivElement>(null);
  // A dialog, menu or popover opened from the pane lives in a portal outside it: the pointer and focus leave the pane while it is open. Its trigger says so; the pane waits.
  const layerOpen = () => Boolean(wrapper.current?.querySelector('[aria-haspopup][aria-expanded="true"], [aria-haspopup][data-popup-open], [aria-haspopup][data-state="open"]'));
  const togglePin = () => {
    const next = !pinned;
    setPinned(next);
    // Unpinning folds unless the pointer or focus is still in the pane (then leaving does).
    const el = wrapper.current;
    setOpen(next || layerOpen() || Boolean(el && (el.matches(':hover') || el.contains(document.activeElement))));
  };
  const toggle = useRef(togglePin);
  useEffect(() => { toggle.current = togglePin; });
  useEffect(() => { if (pinned && state === 'collapsed') setOpen(true); }, [pinned, state, setOpen]);
  const settled = () => {
    const el = wrapper.current;
    try { return Boolean(el) && !el!.matches(':hover') && !(el!.contains(document.activeElement) && document.activeElement!.matches(':focus-visible')); } catch { return false; }
  };
  // Keyboard focus inside the pane (a mouse click leaves none to keep it open) and the pointer over it each keep it open: it folds when both have gone.
  const focusIn = () => { const el = wrapper.current; try { return Boolean(el && el.contains(document.activeElement) && document.activeElement!.matches(':focus-visible')); } catch { return false; } };
  const pointerIn = () => { try { return Boolean(wrapper.current?.matches(':hover')); } catch { return false; } };
  const fold = () => { if (!pinned && !layerOpen() && !pointerIn() && !focusIn()) setOpen(false); };
  // Hover intent: the pane opens once the pointer has stayed HOVER_REVEAL_MS on the rail and folds HOVER_FOLD_MS after pointer and focus left, so a pointer passing by flashes nothing. Keyboard focus opens it at once.
  const intent = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const latestFold = useRef(fold);
  useEffect(() => { latestFold.current = fold; });
  useEffect(() => () => clearTimeout(intent.current), []);
  const foldLater = () => { clearTimeout(intent.current); intent.current = setTimeout(() => latestFold.current(), HOVER_FOLD_MS); };
  // When that layer closes, the pane folds if the pointer and focus are outside (the trigger gets focus back after a pause).
  useEffect(() => {
    const el = wrapper.current;
    if (!hover || !el || pinned) return undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const observer = new MutationObserver(() => { clearTimeout(timer); timer = setTimeout(() => { if (!layerOpen() && settled()) setOpen(false); }, 60); });
    observer.observe(el, { subtree: true, attributes: true, attributeFilter: ['aria-expanded', 'data-popup-open'] });
    return () => { observer.disconnect(); clearTimeout(timer); };
  }, [hover, pinned, setOpen]);
  // Ctrl+B toggles the pin here, ahead of the provider's own listener (which would fold the pane under the pointer).
  useEffect(() => {
    if (!hover) return undefined;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== 'b' || !(event.metaKey || event.ctrlKey)) return;
      // A text field or editor keeps its own Ctrl+B (bold, say).
      if (event.target instanceof Element && event.target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
      event.preventDefault();
      event.stopPropagation();
      toggle.current();
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [hover]);
  // In the phone sheet, choosing a screen closes it.
  const choose = (id: string) => { setOpenMobile(false); onChange(id); };
  const own = items.find(item => item.id === activeId)?.sidebar?.({ collapsed: state === 'collapsed' && !isMobile && !pinned });
  const { before, after } = placeNav(items);
  const navGroup = (group: readonly NavItem[], className?: string, testId?: string) => group.length > 0 && <SidebarGroup className={className} data-testid={testId}><SidebarGroupContent><SidebarMenu>
    {group.map(item => <SidebarMenuItem key={item.id}>
      <SidebarMenuButton isActive={item.id === activeId} tooltip={item.label} data-testid={`nav-${item.id}`} className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]" onClick={() => choose(item.id)}>
        <item.icon />
        <span>{item.label}</span>
        {item.badge && <Dot badge={item.badge} className="ml-auto group-data-[collapsible=icon]:hidden" />}
      </SidebarMenuButton>
    </SidebarMenuItem>)}
  </SidebarMenu></SidebarGroupContent></SidebarGroup>;
  const layer = useAgentLayer();
  // One layer at a time on a phone (D-1903): the sheet closes when the assistant or the PM opens, or when another sheet (the account's) opens.
  const covering = layer.state !== 'closed' ? layer.showing : null;
  useEffect(() => { if (covering) setOpenMobile(false); }, [covering, setOpenMobile]);
  useExclusiveSheet(isMobile && openMobile, () => setOpenMobile(false), true);
  const pressed = layer.state !== 'closed' && layer.showing === 'agent';
  const AgentIcon = agent?.icon ?? SparklesIcon;
  const agentLabel = agent?.label ?? agent?.chatProps?.labels?.title ?? text.assistant;
  // The assistant is a layer, never a destination: no route, it toggles the right panel.
  const agentEntry = agent && <>
    {items.length > 1 && <SidebarSeparator />}
    <SidebarGroup><SidebarGroupContent><SidebarMenu><SidebarMenuItem>
      <SidebarMenuButton isActive={pressed} aria-pressed={pressed} tooltip={agentLabel} data-testid="nav-agent" className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]"
        onClick={() => { setOpenMobile(false); if (pressed) layer.close(); else layer.open('agent', 'half'); }}>
        <AgentIcon /><span>{agentLabel}</span>
      </SidebarMenuButton>
    </SidebarMenuItem></SidebarMenu></SidebarGroupContent></SidebarGroup>
  </>;
  // Hover-revealed and unpinned, the pane floats over the page: a shadow on its sidebar surface lifts it (pinned, it sits beside the page).
  const sidebar = <Sidebar collapsible="icon" variant="inset" data-testid="app-sidebar" data-float={hover && !pinned && state === 'expanded' ? 'true' : undefined}>
    {/* The phone sheet is portaled out of the shell root, so the `.app-shell` reset would not reach its buttons: this wrapper carries it (`contents`: no box of its own). */}
    <InsideNavSheet.Provider value={true}>
    <div className="app-shell contents">
    {/* The one toggle: title and button expanded, the button alone on the icon rail, and « close » inside the phone sheet. The hover rail has no toggle on a wide screen (it opens on hover and focus by itself) but a pin (D-2010) that keeps it open, and keeps « close » in the sheet. */}
    <SidebarHeader className="flex-row items-center justify-between gap-1 group-data-[collapsible=icon]:justify-center"><p data-testid="sidebar-title" className="m-0 min-w-0 truncate px-2 py-1 text-sm font-semibold group-data-[collapsible=icon]:hidden">{title}</p>{(rail !== 'hover' || isMobile) && <SidebarTrigger />}
      {hover && <Button type="button" variant="ghost" size="icon-sm" data-testid="sidebar-pin" aria-pressed={pinned} aria-label={text.pin} title={`${pinned ? text.unpin : text.pin} · Ctrl+B`} onClick={togglePin}
        className="group-data-[collapsible=icon]:pointer-events-none group-data-[collapsible=icon]:opacity-0 group-data-[collapsible=icon]:pointer-coarse:pointer-events-auto group-data-[collapsible=icon]:pointer-coarse:opacity-100"><PinIcon aria-hidden="true" data-pinned={pinned ? 'true' : 'false'} weight={pinned ? 'fill' : 'regular'} /></Button>}</SidebarHeader>
    <SidebarContent>
      {/* Without the screen's own content, one group in placed order; with it, the before items above it and the rest below. */}
      {items.length > 1 && (own != null || agentNav === 'above-bottom') && navGroup(before, 'shrink-0', 'nav-before')}
      {own != null && <div data-testid="sidebar-screen" className="min-h-0 flex-1 overflow-y-auto overscroll-contain">{own}</div>}
      {agentNav === 'above-bottom' && agentEntry}
      {items.length > 1 && (own != null || agentNav === 'above-bottom' ? navGroup(after, 'shrink-0') : navGroup([...before, ...after]))}
      {agentNav !== 'above-bottom' && agentEntry}
    </SidebarContent>
    <SidebarFooter><NavUser account={account} improve={improve} text={text} /></SidebarFooter>
    <ResizableRail />
    </div>
    </InsideNavSheet.Provider>
  </Sidebar>;
  if (rail !== 'hover') return sidebar;
  // Reserve the native inset icon gap even while the fixed sidebar reveals its labels over the page.
  return <div ref={wrapper} data-rail="hover" data-pinned={pinned} className={pinned ? 'relative z-lifted shrink-0' : 'relative z-lifted w-[calc(var(--sidebar-w-icon)+(--spacing(4)))] shrink-0'}
    onPointerEnter={event => { if (event.pointerType === 'mouse' || event.pointerType === 'pen') { clearTimeout(intent.current); intent.current = setTimeout(() => setOpen(true), HOVER_REVEAL_MS); } }}
    onPointerLeave={foldLater}
    onFocusCapture={event => { if (event.target.matches(':focus-visible')) { clearTimeout(intent.current); setOpen(true); } }}
    onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) foldLater(); }}
    onKeyDownCapture={event => { if (!pinned && event.key === 'Escape' && event.target instanceof Node && event.currentTarget.contains(event.target)) { event.preventDefault(); event.stopPropagation(); clearTimeout(intent.current); setOpen(false); } }}>
    {sidebar}
  </div>;
}

'use client';

// The account choices: the compact sheet's content (`AccountChoices`) and the expanded sidebar's footer (`NavUser`, the sidebar-07 pattern).
// Both list « Améliorer l'app » (when the app has an `improve` agent, opened in the AgentLayer), the app's own `menu`, then sign out.
import { useId } from 'react';
import type { CSSProperties } from 'react';
import { ChevronsUpDownIcon, LogOutIcon, MessageSquarePlusIcon, MoonIcon } from '../_shared/icons';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from '@/components/ui/sidebar';
import { useAgentLayer } from './agent-layer';
import { afterBack } from '../utils/back';
import { Switch } from '@/components/ui/switch';
import { DropdownMenuCheckboxItem } from '@/components/ui/dropdown-menu';
import { SHEET_ROW } from './app-sheet';
import type { AppShellText } from './text';

export interface AccountSpec {
  readonly name: string;
  readonly email?: string;
  readonly signOut?: () => void;
  readonly menu: readonly { readonly label: string; readonly onSelect: () => void }[];
  /** The app's resolved theme: one « Mode sombre » switch in the account menu. The host resolves `system` (its preference) to `light` or `dark` before it gets here. Absent: no row. */
  readonly theme?: { readonly value: 'light' | 'dark'; readonly onChange: (value: 'light' | 'dark') => void };
}

/** « Améliorer l'app »'s row: 52px as a height, not a minimum, so the shell's 44px touch-target `min-height` (more specific) cannot shrink it. Its radius: the theme's large radius plus one step (12px on a 8px theme). */
const IMPROVE_ROW = { '--radius': 'var(--app-shell-row-radius)' } as CSSProperties;

/** The switch's state: on is dark. */
const darkOn = (theme: NonNullable<AccountSpec['theme']>) => theme.value === 'dark';

function ThemeSwitch({ theme, text }: { readonly theme: NonNullable<AccountSpec['theme']>; readonly text: AppShellText }) {
  const id = useId();
  return <div className="flex items-center gap-3">
    <label htmlFor={id} className="flex min-h-11 items-center gap-3"><MoonIcon aria-hidden="true" />{text.darkMode}</label>
    <Switch id={id} data-testid="account-theme" aria-label={text.darkMode} checked={darkOn(theme)} className="ml-auto" onCheckedChange={on => theme.onChange(on ? 'dark' : 'light')} />
  </div>;
}

/** « Jean Dupont » gives « JD »; one word gives its first letter. */
export function initials(name: string): string {
  const letters = name.trim().split(/\s+/).filter(Boolean).slice(0, 2).map(word => [...word][0]!.toUpperCase());
  return letters.join('') || '?';
}

export function AccountAvatar({ account, size }: { readonly account: AccountSpec | undefined; readonly size?: 'default' | 'lg' }) {
  return <Avatar size={size === 'lg' ? 'lg' : 'default'}><AvatarFallback>{initials(account?.name ?? '')}</AvatarFallback></Avatar>;
}

/** The compact account sheet's content. Every choice closes the sheet first (`done`). */
export function AccountChoices({ account, improve, text, done }: { readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText; readonly done: () => void }) {
  const layer = useAgentLayer();
  const choose = (action: () => void) => () => { done(); afterBack(action); };
  return <div data-testid="account-menu" className="flex flex-col" style={{ '--app-shell-row-radius': 'calc(var(--radius) + 4px)' } as CSSProperties}>
    {account && <div className="flex items-center gap-3 px-4 py-3">
      <AccountAvatar account={account} size="lg" />
      <div className="min-w-0"><p className="m-0 truncate font-medium">{account.name}</p>{account.email && <p className="m-0 truncate text-xs text-muted-foreground">{account.email}</p>}</div>
    </div>}
    {/* C1: the first item, 52px on the muted fill, the speech bubble with a plus (icon 20), 15/650. */}
    {improve && <Button variant="secondary" size="lg" data-testid="account-improve" className={`${SHEET_ROW} h-13`} style={IMPROVE_ROW} onClick={choose(() => layer.open('improve'))}><MessageSquarePlusIcon data-icon="inline-start" className="size-5" aria-hidden="true" /><span className="text-base font-pm-title">{improve}</span></Button>}
    {account?.menu.map(entry => <Button key={entry.label} variant="ghost" size="lg" className={SHEET_ROW} onClick={choose(entry.onSelect)}>{entry.label}</Button>)}
    {account?.theme && <ThemeSwitch theme={account.theme} text={text} />}
    {account?.signOut && <Button variant="ghost" size="lg" data-testid="account-sign-out" className={SHEET_ROW} onClick={choose(account.signOut)}><LogOutIcon data-icon="inline-start" aria-hidden="true" />{text.signOut}</Button>}
  </div>;
}

/** The expanded sidebar footer: avatar, name and a dropdown with the same entries as the compact sheet. */
export function NavUser({ account, improve, text }: { readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText }) {
  const layer = useAgentLayer();
  if (!account && !improve) return null;
  return <SidebarMenu><SidebarMenuItem>
    <DropdownMenu>
      <DropdownMenuTrigger render={<SidebarMenuButton size="lg" data-testid="nav-user" className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]" />}>
        <AccountAvatar account={account} />
        <div className="grid min-w-0 flex-1 text-left text-xs leading-tight">
          <span className="truncate font-medium">{account?.name ?? text.account}</span>
          {account?.email && <span className="truncate text-xs text-muted-foreground">{account.email}</span>}
        </div>
        <ChevronsUpDownIcon className="ml-auto size-4" aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent side="right" align="end" sideOffset={4} className="app-shell w-56 min-w-56">
        {improve && <DropdownMenuItem className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" data-testid="account-improve" onClick={() => layer.open('improve')}><MessageSquarePlusIcon className="size-4" aria-hidden="true" />{improve}</DropdownMenuItem>}
        {account?.menu.map(entry => <DropdownMenuItem key={entry.label} className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onClick={entry.onSelect}>{entry.label}</DropdownMenuItem>)}
        {account?.theme && <DropdownMenuCheckboxItem checked={darkOn(account.theme)} closeOnClick data-testid="account-theme" className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onCheckedChange={on => account.theme?.onChange(on ? 'dark' : 'light')}><MoonIcon aria-hidden="true" />{text.darkMode}</DropdownMenuCheckboxItem>}
        {account?.signOut && <><DropdownMenuSeparator /><DropdownMenuItem className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" data-testid="account-sign-out" onClick={account.signOut}><LogOutIcon className="size-4" aria-hidden="true" />{text.signOut}</DropdownMenuItem></>}
      </DropdownMenuContent>
    </DropdownMenu>
  </SidebarMenuItem></SidebarMenu>;
}

'use client';

// The one sheet of the shell (account, « Plus », « … », app flows): the host's shadcn `drawer`, a modal bottom sheet. Only one is open at a time
// (opening one closes any other) and Back closes it (the Back manager's `sheet` layer). The agent layer is not an AppSheet.
import type { ReactNode } from 'react';
import { Drawer, DrawerContent, DrawerHeader, DrawerTitle } from '@/components/ui/drawer';
import { useBackLayer } from '../utils/back';
import { useExclusiveSheet } from './use-exclusive-sheet';

/** A modal bottom sheet with a title. The scrim, Escape, a swipe down and Back close it. */
export function AppSheet({ open, onOpenChange, title, children }: { readonly open: boolean; readonly onOpenChange: (open: boolean) => void; readonly title: string; readonly children: ReactNode }) {
  const close = () => onOpenChange(false);
  useExclusiveSheet(open, close);
  useBackLayer(open, close, 'sheet');
  return <Drawer open={open} onOpenChange={next => { if (!next) close(); }} showSwipeHandle swipeDirection="down">
    <DrawerContent data-testid="app-sheet" className="app-shell max-h-(--app-shell-sheet-max)">
      <DrawerHeader><DrawerTitle>{title}</DrawerTitle></DrawerHeader>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain px-2 pt-2 pb-(--app-shell-safe-bottom)">{children}</div>
    </DrawerContent>
  </Drawer>;
}

/** Layout for a full-width sheet row on the host's ghost `Button`: at least 48px tall (44px is the touch minimum). */
export const SHEET_ROW = 'min-h-12 w-full justify-start gap-3';

'use client';

import { createContext, useContext, useEffect, useLayoutEffect, useRef } from 'react';

interface Open { readonly close: () => void; /** The phone nav sheet itself. */ readonly nav: boolean }
const opened = new Set<Open>();

/** True inside the phone nav sheet's content: a sheet opened from there is nested (it stacks on the nav sheet, whose subtree it lives in) and does not close it. */
export const InsideNavSheet = createContext(false);

/** While `open`, this sheet is the only one: every other open sheet is asked to close when it opens, except the nav sheet a nested sheet lives in. `nav` marks the phone nav sheet's own registration. */
export function useExclusiveSheet(open: boolean, close: () => void, nav = false): void {
  const latest = useRef(close);
  const nested = useContext(InsideNavSheet);
  useLayoutEffect(() => { latest.current = close; });
  useEffect(() => {
    if (!open) return;
    const mine: Open = { close: () => latest.current(), nav };
    for (const other of [...opened]) if (!(nested && other.nav)) other.close();
    opened.add(mine);
    return () => { opened.delete(mine); };
  }, [open, nested, nav]);
}

'use client';

// The shell's panel place: a second agent or tool beside the app, opened from the account menu. The shell knows only this shape, so an app
// plugs in what it wants (the product manager is `pmPanel` from the Factory's `platform-ui/pm-panel`) and an app without one installs nothing more.
import type { ComponentType, ReactNode } from 'react';

export interface ShellPanelProviderProps {
  /** `ShellPanel.config`, as the panel wrote it. */
  readonly config: unknown;
  readonly open: boolean;
  readonly close: () => void;
  readonly appName?: string | undefined;
  readonly locale?: string | undefined;
  /** The panel took the whole screen, or gave it back; `collapse` is what Back runs. */
  readonly onFull?: ((full: boolean, collapse: () => void) => void) | undefined;
  readonly children: ReactNode;
}

export interface ShellPanelLayoutProps {
  readonly children: ReactNode;
  /** The phone tab bar. The layout hides it while the panel covers the page. */
  readonly navigation?: ReactNode;
  /** The label of the screen on show. */
  readonly screen?: string;
}

export interface ShellPanelPageProps {
  readonly config: unknown;
  readonly appName: string;
  readonly locale?: string | undefined;
}

/** Keep `Provider`, `Layout` and `page.Page` the same across renders: a new component remounts the app. */
export interface ShellPanel {
  /** Passed back to `Provider` and `page.Page`. */
  readonly config: unknown;
  /** Wraps the whole shell, so the panel's state outlives its closing. */
  readonly Provider: ComponentType<ShellPanelProviderProps>;
  /** Wraps the screen and draws the panel beside it. */
  readonly Layout: ComponentType<ShellPanelLayoutProps>;
  /** The account menu's row and the layer's title. Default: the shell's « Améliorer l'app ». */
  readonly label?: string;
  /** `false`: no account menu row for the panel, which still mounts (a host that already shows the panel, around a framed app). Default: the row. */
  readonly menu?: false;
  /** The panel's language, for the shell's own words when the app has no agent to say it. */
  readonly locale?: string | undefined;
  /** Changes when the panel's conversation changes; a launch link's focus waits on it. */
  readonly identity?: unknown;
  /** The address that shows only the panel, without the shell. */
  readonly page?: { readonly matches: () => boolean; readonly Page: ComponentType<ShellPanelPageProps> };
}

/** The screen when the app has no panel. */
export function NoPanelLayout({ children, navigation }: ShellPanelLayoutProps) {
  return <div className="relative flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">{children}</div>
    <div className="shrink-0 md:hidden">{navigation}</div>
  </div>;
}

// The composer's placement as flags. Today's `composer` strings are presets of this config; every place that used to compare `composer` to a string reads the resolved flags instead,
// and the strip's actions (the chevron and what the state offers) and the tray header's buttons read ONE action table. `composer` takes a preset string, this config object, or a
// function of the viewport and route that gives the object. The circle launcher is the first non-preset behaviour: invalid combinations throw, naming the fix.
import type { AgentComposer, ComposerPlace, ComposerSignals, ConversationSize, Level, ResolvedComposer } from './layer-context';
export type { Level } from './layer-context';
export type { ComposerLauncher, ResolvedComposer } from './layer-context';

/** A corner in logical terms (a right-to-left page mirrors it): `bottom-end` is the bottom right in a left-to-right page. */
export type Corner = 'bottom-end' | 'bottom-start' | 'top-end' | 'top-start';
/** A distance: px as a number, or a CSS length (`'var(--phone-band-h)'`). */
export type Length = number | string;
/** What a launcher steps around: a selector of the page's fixed elements, or a live rectangle (`null`: nothing there now). */
export type Avoid = string | (() => DOMRect | null);
/** What a `composer` function reads: the viewport and the route. */
export interface ComposerEnv { readonly phone: boolean; readonly width: number; readonly route?: string | undefined }

interface ComposerCommon {
  /** Names this launcher: the storage keys, `data-composer`, and Ctrl or Cmd + J (the first launcher answers). Absent: today's keys. */
  readonly id?: string;
  readonly at?: {
    readonly place?: 'bottom' | 'float' | Corner | 'right-edge';
    /** The gap to the corner's two edges, 16 and 16 by default. A phone's tab bar is added when `block` is not given. */
    readonly offset?: { readonly inline?: Length; readonly block?: Length };
    /** The order among launchers on one corner, lowest nearest the corner: `auto` (default) is by mount order. */
    readonly stack?: 'auto' | number;
    readonly remember?: 'local' | 'session' | false;
  };
  /** Publishes the launcher's footprint as `--composer-reserve-block` and `--composer-reserve-inline` (default `auto`), which the screens, the notice row and a host's own toasts read. */
  readonly reserve?: 'auto' | 'none';
  /** Rectangles the launcher and its panel step around (a drawer's tab, a band). */
  readonly avoid?: readonly Avoid[];
  /** The launcher's z-index (default 40; its panel is one above): below the app's sheets (50 and up) and above the page. */
  readonly layer?: number;
  /** Controlled when `level` is set: the app reads and sets it through `on.level`. */
  readonly level?: Level;
  readonly defaultLevel?: Level;
  readonly on?: {
    readonly level?: (level: Level) => void;
    readonly signals?: (signals: ComposerSignals) => void;
    /** Shorthand of `handoff.openFull`: hand the conversation to the app's full page. */
    readonly openFull?: (conversationId: string) => void;
  };
  /** The status text beside the folded launcher (`'réfléchit'`), or `null` for none. */
  readonly note?: (signals: ComposerSignals) => string | null;
  /** The pointing tool (`AgentSpec.feedback`): its toggle sits in the panel's title row; `while` is the level taken while annotating (default `folded`). */
  readonly feedback?: { readonly while?: Level };
  /** Adds Open in full: the app's full page for the conversation. */
  readonly handoff?: { readonly openFull: (conversationId: string, context: { readonly empty: boolean }) => void; readonly then?: 'close' | 'stay'; readonly allowEmpty?: boolean };
  /** The full page is on show: the launcher is hidden and the conversation is marked read, in every mounted instance. */
  readonly suspended?: boolean;
}

/** The config a preset stands for (the spec's key names: `at`, `side`). */
export type ComposerConfig = ComposerCommon & (
  | { readonly launcher: 'bar'; readonly sizes?: readonly ConversationSize[]; readonly dock?: boolean; readonly fold?: 'circle' | false; readonly float?: boolean | { readonly movable?: boolean } }
  | { readonly launcher: 'circle'; readonly sizes?: readonly ConversationSize[] }
  | { readonly launcher: 'tab'; readonly sizes?: readonly ConversationSize[]; readonly side?: { readonly mode?: 'push' | 'overlay' | 'auto'; readonly width?: number | string } }
  | { readonly launcher: 'header'; readonly float?: boolean });
/** What `composer` takes: a preset string, the config object, or a function of the viewport and route that gives the object. */
export type ComposerInput = AgentComposer | ComposerConfig | ((env: ComposerEnv) => ComposerConfig);

/** The presets, one per string. `bar` with the shell's `floatingComposer` and the standalone `FloatingComposer` are the two variants below. */
export const COMPOSER_PRESETS = {
  dock: { launcher: 'header', float: true },
  content: { launcher: 'bar', sizes: ['open'], dock: true },
  bar: { launcher: 'bar', sizes: ['open', 'grown', 'full'], dock: true },
  explore: { launcher: 'tab', side: { mode: 'auto' }, at: { place: 'right-edge' } },
} as const satisfies Record<AgentComposer, ComposerConfig>;

/** `composer="bar"` with `floatingComposer`: the bar may float and fold to its circle (remembered). */
export const BAR_FLOATING_PRESET = { ...COMPOSER_PRESETS.bar, fold: 'circle', float: { movable: true }, at: { remember: 'local' } } as const satisfies ComposerConfig;
/** The standalone `FloatingComposer`: a bar with no dock column; `start="icon"` is a default level, not a different preset. */
export const FLOATING_COMPOSER_PRESET = { launcher: 'bar', sizes: ['open', 'grown', 'full'], dock: false, fold: 'circle', float: { movable: true } } as const satisfies ComposerConfig;
/** The agent card: levels 0, 1 and 2 are `folded`, `open` and `full`. */
export const AGENT_CARD_PRESET = { launcher: 'bar', sizes: ['open', 'full'], dock: true } as const satisfies ComposerConfig;

/** Where the conversation is, as far as its strip is concerned (the layer's own values). */
export interface StripState {
  readonly expanded: boolean;
  readonly snap: 'closed' | 'peek' | 'half' | 'full';
  readonly trayOpen: boolean;
  readonly dockOpen: boolean;
  readonly size: ConversationSize;
  readonly place: ComposerPlace;
  readonly anchored: boolean;
  /** The layer offers the side dock (false for the standalone entry). */
  readonly docks: boolean;
  /** The agent has a pointing tool (`AgentSpec.feedback`): a circle's title row carries its toggle. */
  readonly feedback?: boolean;
}

/** The one action table: the strip and the tray header draw their ids and test ids from here. Labels, icons and what they do belong to the caller. */
export const STRIP_ACTIONS = {
  conversation: { id: 'chevron', testId: 'agent-bar-conversation' },
  reduce: { id: 'chevron', testId: 'agent-tray-reduce' },
  back: { id: 'chevron', testId: 'agent-full-back' },
  more: { id: 'more', testId: 'agent-tray-grow' },
  full: { id: 'full', testId: 'agent-tray-full' },
  split: { id: 'split', testId: 'agent-tray-dock' },
  float: { id: 'float', testId: 'composer-float' },
  dock: { id: 'dock', testId: 'composer-dock-bottom' },
  minimise: { id: 'minimise', testId: 'composer-minimise' },
  openFull: { id: 'open-full', testId: 'composer-open-full' },
} as const;
export type StripKey = keyof typeof STRIP_ACTIONS;
/** The circle panel's title-row actions: the annotate toggle (an agent with a pointing tool), Open in full (a `handoff`) and Close. Only what the config allows is drawn. */
export const CIRCLE_ACTIONS = {
  annotate: { id: 'annotate', testId: 'composer-annotate-title' },
  openFull: { id: 'open-full', testId: 'composer-open-full' },
  close: { id: 'close', testId: 'agent-layer-close' },
} as const;
export type CircleKey = keyof typeof CIRCLE_ACTIONS;
/** One action of the plan: `open` marks the phone chevron that collapses (its label), the rest is the table's. */
export interface StripPlanItem { readonly key: StripKey | CircleKey; readonly id: string; readonly testId: string; readonly open?: boolean }

const item = (key: StripKey, open?: boolean): StripPlanItem => ({ key, ...STRIP_ACTIONS[key], ...(open === undefined ? {} : { open }) });

const fail = (why: string): never => { throw new Error(`composer: ${why}`); };
const LEVELS: readonly string[] = ['folded', 'open', 'grown', 'full', 'docked'];
const CORNERS: readonly string[] = ['bottom-end', 'bottom-start', 'top-end', 'top-start'];
const checkLength = (name: string, value: unknown) => { if (value !== undefined && !(typeof value === 'number' && Number.isFinite(value)) && !(typeof value === 'string' && value.trim() !== '')) fail(`\`at.offset.${name}\` is a number of px or a CSS length such as 'var(--tabbar-h)'`); };

/** The levels a launcher can be at: the circle has two, a bar the sizes and the dock its config allows, a tab and the header trigger their own. */
export function levelsOf(config: ComposerConfig, standalone: boolean): readonly Level[] {
  switch (config.launcher) {
    case 'circle': case 'tab': return ['folded', 'open'];
    case 'header': return ['folded', 'open', 'docked'];
    case 'bar': { const sizes = config.sizes ?? ['open']; return ['folded', 'open', ...(sizes.includes('grown') ? ['grown' as const] : []), ...(sizes.includes('full') ? ['full' as const] : []), ...(config.dock !== false && !standalone ? ['docked' as const] : [])]; }
  }
}

/** The rules every launcher shares (`id`, `at`, `level`, `on`, `handoff`, `feedback`...): every invalid combination names the fix. */
function checkCommon(config: ComposerConfig, standalone: boolean): void {
  const { at, level, defaultLevel, on, handoff, feedback, sizes } = config as ComposerConfig & { readonly sizes?: readonly ConversationSize[] };
  const stack = at?.stack;
  const circle = config.launcher === 'circle';
  if (circle && sizes?.some(size => size !== 'open')) fail("a circle opens one panel: take 'grown' and 'full' out of `sizes`; to show the whole conversation on a page, give `handoff.openFull` (the page is your route)");
  if (at?.place !== undefined) {
    if (circle && !CORNERS.includes(at.place)) fail(`a circle sits in a corner: \`at.place\` is one of ${CORNERS.map(corner => `'${corner}'`).join(', ')}, not '${at.place}'`);
    if (!circle && !CORNERS.includes(at.place) && at.place !== 'bottom' && at.place !== 'float' && at.place !== 'right-edge') fail(`\`at.place\` is 'bottom', 'float', 'right-edge' or one of ${CORNERS.map(corner => `'${corner}'`).join(', ')}, not '${String(at.place)}'`);
  }
  const allowed = levelsOf(config, standalone);
  for (const [name, value] of [['level', level], ['defaultLevel', defaultLevel]] as const) {
    if (value === undefined) continue;
    if (allowed.includes(value)) continue;
    if (circle) fail(LEVELS.includes(value) ? `a circle has two levels, 'folded' (the circle) and 'open' (the panel): \`${name}: '${value}'\` is for the bar; to show the whole conversation, give \`handoff.openFull\`` : `\`${name}\` is 'folded' or 'open'`);
    fail(LEVELS.includes(value) ? `a ${config.launcher} launcher has no '${value}' level (it has ${allowed.map(one => `'${one}'`).join(', ')}): ${value === 'docked' ? 'set `dock: true` (the standalone composer has no dock)' : `add '${value}' to \`sizes\``}, or ask for one of those` : `\`${name}\` is one of ${allowed.map(one => `'${one}'`).join(', ')}`);
  }
  if (level !== undefined && !on?.level) fail('`level` is controlled: pass `on.level` to change it, or use `defaultLevel` for a start the person can change');
  if (handoff && on?.openFull) fail('`handoff.openFull` and `on.openFull` both hand the conversation to the full page: keep one');
  if (handoff?.then !== undefined && handoff.then !== 'close' && handoff.then !== 'stay') fail("`handoff.then` is 'close' (default) or 'stay'");
  if (feedback?.while !== undefined && !allowed.includes(feedback.while)) fail(`\`feedback.while\` is the level taken while annotating: one of ${allowed.map(one => `'${one}'`).join(', ')} ('folded' steps the panel aside, the default of a circle)`);
  if (stack !== undefined && stack !== 'auto' && !(Number.isInteger(stack) && stack >= 0)) fail("`at.stack` is 'auto' or a whole number from 0 (the one nearest the corner)");
  if (config.layer !== undefined && !Number.isFinite(config.layer)) fail('`layer` is a z-index number');
  if (config.reserve !== undefined && config.reserve !== 'auto' && config.reserve !== 'none') fail("`reserve` is 'auto' (default) or 'none'");
  if (config.avoid !== undefined && !(Array.isArray(config.avoid) && config.avoid.every(entry => typeof entry === 'string' || typeof entry === 'function'))) fail('`avoid` is a list of selectors and functions that give a rectangle (or null)');
  checkLength('inline', at?.offset?.inline); checkLength('block', at?.offset?.block);
}

const clean = (config: ComposerConfig, standalone: boolean, given: boolean): ResolvedComposer => {
  if (config.id !== undefined && (typeof config.id !== 'string' || config.id.trim() === '')) fail('`id` is a non-empty string');
  const sizes = 'sizes' in config && config.sizes ? config.sizes : config.launcher === 'tab' || config.launcher === 'header' ? [] : ['open'] as const;
  if ('sizes' in config && config.sizes && config.sizes.length === 0) fail('`sizes` is empty');
  if (config.launcher === 'circle' && ('dock' in config || 'fold' in config || 'float' in config)) fail('a circle launcher is always folded: no `dock`, `fold` or `float`');
  if (config.launcher === 'tab' && ('dock' in config || 'fold' in config || 'float' in config)) fail('a tab launcher takes no `dock`, `fold` or `float`');
  if (config.launcher === 'header' && 'sizes' in config) fail('a header launcher has no sizes: it is the docked trigger');
  if (config.launcher !== 'bar' && 'fold' in config) fail('`fold` is for a bar');
  if (given && standalone && config.launcher === 'header') fail('`FloatingComposer` has no header trigger: use launcher \'bar\' or \'circle\'');
  if (given && standalone && config.launcher === 'bar' && config.dock === true) fail('`FloatingComposer` has no side dock: leave `dock` out (or set it to false)');
  checkCommon(config, standalone);
  const float = config.launcher === 'bar' || config.launcher === 'header' ? config.float === true || (typeof config.float === 'object' && config.float !== null) : false;
  const fold = config.launcher === 'bar' ? config.fold === 'circle' : false;
  if (config.launcher === 'bar' && fold !== (config.float !== undefined && config.float !== false)) fail('a bar folds to its circle exactly when it floats: set `fold` and `float` together');
  const bar = config.launcher === 'bar' && sizes.includes('grown');
  return { launcher: config.launcher, sizes, dock: config.launcher === 'bar' ? !standalone && config.dock !== false : config.launcher === 'header', floatable: config.launcher === 'bar' && float && fold && bar,
    contentColumn: config.launcher === 'bar', bar, explore: config.launcher === 'tab', circle: config.launcher === 'circle', id: config.id };
};

/**
 * The flags of a `composer` string (or config) and, given the conversation's state, the ordered strip actions. `floatingComposer` only turns the `bar` preset into
 * its floating variant (as today: `content` ignores it). `standalone` is the `FloatingComposer` entry (no side dock, no header trigger); `legacy` names the old props the
 * caller was given next to an object (`floatingComposer`, `storage`, `start`, `onOpenFull`), which the object replaces. Invalid combinations throw.
 */
export function resolveComposer(input: { readonly composer?: AgentComposer | ComposerConfig | undefined; readonly floatingComposer?: boolean | undefined; readonly state?: StripState | undefined; readonly standalone?: boolean | undefined; readonly legacy?: readonly string[] | undefined }): { readonly flags: ResolvedComposer; readonly config: ComposerConfig; readonly actions: readonly StripPlanItem[] } {
  const { composer = 'dock', floatingComposer = false, state, standalone = false, legacy = [] } = input;
  let config: ComposerConfig;
  if (typeof composer === 'string') {
    if (!(composer in COMPOSER_PRESETS)) throw new Error(`composer: "${String(composer)}" is not a composer preset`);
    config = composer === 'bar' && floatingComposer ? BAR_FLOATING_PRESET : COMPOSER_PRESETS[composer];
  } else {
    if (typeof composer !== 'object' || composer === null) fail('`composer` is a preset string, a config object or a function that gives one');
    if (floatingComposer) throw new Error('composer: a composer config replaces `floatingComposer`: set `fold` and `float` on it');
    if (legacy.length > 0) fail(`a composer config replaces ${legacy.map(name => `\`${name}\``).join(', ')}: put it on the config (\`at.remember\`, \`defaultLevel\`, \`handoff.openFull\`) and remove the prop`);
    config = composer;
  }
  const flags = clean(config, standalone, typeof composer === 'object');
  return { flags, config, actions: state ? stripPlan(flags, state, config) : [] };
}

/**
 * The composer one screen shows (`NavItem.composer`): the app's own when the screen says nothing; `false` is the app's composer with `suspended` (hidden here, the conversation read); a config object replaces it for this screen.
 * `floating` is the shell's `floatingComposer`, which a config object replaces (it throws next to one), so it is dropped from whatever turns into an object.
 */
export function composerForScreen(base: AgentComposer | ComposerConfig | undefined, floating: boolean, screen: ComposerConfig | false | undefined): { readonly composer: AgentComposer | ComposerConfig | undefined; readonly floating: boolean } {
  if (screen === undefined) return { composer: base, floating };
  if (screen === false) return { composer: { ...resolveComposer({ composer: base, floatingComposer: floating }).config, suspended: true }, floating: false };
  return { composer: screen, floating: false };
}

/** The config object the layer was given (`undefined` for a string preset): `Internal.composerConfig` holds it untyped. */
export const configOf = (layer: { readonly composerConfig: { readonly current: unknown } }): ComposerConfig | undefined => layer.composerConfig.current as ComposerConfig | undefined;

/** The strip in a state, as today: the chevron first, then what the state offers. A circle's panel has only what its config allows: Open in full (a `handoff`) and Close. A `handoff` adds Open in full to a bar's strip while the conversation is open (the full page is the app's own, never a level). */
export function stripPlan(flags: ResolvedComposer, s: StripState, config?: ComposerConfig): readonly StripPlanItem[] {
  const plan = basePlan(flags, s, config);
  const handoff = config?.handoff !== undefined || config?.on?.openFull !== undefined;
  const open = s.expanded ? s.trayOpen && s.size !== 'full' : s.snap === 'half' || s.snap === 'full';
  return handoff && !flags.circle && open && plan.length > 0 ? [...plan, item('openFull')] : plan;
}

function basePlan(flags: ResolvedComposer, s: StripState, config?: ComposerConfig): readonly StripPlanItem[] {
  if (flags.circle) {
    if (s.snap === 'closed') return [];
    const handoff = config?.handoff !== undefined || config?.on?.openFull !== undefined;
    return [...(s.feedback ? [{ key: 'annotate' as const, ...CIRCLE_ACTIONS.annotate }] : []), ...(handoff ? [{ key: 'openFull' as const, ...CIRCLE_ACTIONS.openFull }] : []), { key: 'close' as const, ...CIRCLE_ACTIONS.close }];
  }
  if (!s.expanded) {
    const open = s.snap === 'half' || s.snap === 'full';
    return [item('conversation', open), ...(s.snap === 'half' ? [item('more')] : [])];
  }
  if (s.trayOpen && s.size === 'full') return [item('back')];
  if (s.dockOpen) return [];
  const floats = flags.floatable && !s.anchored;
  if (s.place === 'float') return [s.trayOpen ? item('reduce') : item('conversation'), item('dock'), item('minimise')];
  const places = floats ? [item('float'), item('minimise')] : [];
  if (s.trayOpen) return [item('reduce'), ...(s.size === 'open' ? [item('more')] : []), ...(s.docks ? [item('split')] : []), item('full'), ...places];
  return [item('conversation'), item('full'), ...places];
}

'use client';

// `composer` as a function of the viewport and the route: the object it gives, read again on a resize and on a route change. Kept apart from `composer-config.ts`, which has no React in it.
import { useEffect, useState } from 'react';
import { usePhone } from '../utils/use-media';
import type { AgentComposer } from './layer-context';
import type { ComposerConfig, ComposerInput } from './composer-config';

/** The string or object as given, or what the function gives for this viewport and route. */
export function useComposerInput(input: ComposerInput | undefined, route?: string): AgentComposer | ComposerConfig | undefined {
  const phone = usePhone();
  const [width, setWidth] = useState(() => typeof window === 'undefined' ? 0 : window.innerWidth);
  const dynamic = typeof input === 'function';
  useEffect(() => {
    if (!dynamic) return;
    const read = () => setWidth(window.innerWidth);
    window.addEventListener('resize', read);
    return () => window.removeEventListener('resize', read);
  }, [dynamic]);
  return typeof input === 'function' ? input({ phone, width, route }) : input;
}

'use client';

// Where launchers sit when a page has several, and what the page keeps free for them. Launchers on one corner stack along the block axis (lowest `at.stack` nearest the corner, `auto` by
// mount order, 12 px apart); `avoid` rectangles push a launcher or its panel sideways along the inline axis; and the footprint of the stack is published as two CSS variables
// (`--composer-reserve-block`, `--composer-reserve-inline`) that the screens, the notice row and a host's own toasts read, instead of probing the DOM. Host concern: Pi has no layout.
import { useCallback, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { RefObject } from 'react';
import type { Avoid, Corner, Length } from './composer-config';
import type { LauncherOwner } from './layer-context';
export type { LauncherOwner } from './layer-context';

/** The circle's size in px (3.25 rem) and the gap between launchers on one corner. */
export const CIRCLE_SIZE = 52;
export const STACK_GAP = 12;
/** The gap kept between a launcher or panel and a rectangle it steps around. */
export const AVOID_GAP = 8;
/** The distance to a corner's edges when the config gives none. */
export const DEFAULT_OFFSET = 16;

/** A `Length` as CSS: a number is px. */
export const css = (length: Length): string => typeof length === 'number' ? `${length}px` : length;

/** One launcher of the page: `corner` is `null` for one that sits in the page's flow (a bar under the content): it keeps its `id` in the registry and takes no place on a corner. `w` and `h` are its box in px (a circle by default). */
interface Launcher { readonly key: object; readonly id: string | undefined; readonly corner: Corner | null; readonly rank: number; readonly seq: number; readonly reserve: boolean; readonly inline: string; readonly block: string; readonly w?: number; readonly h?: number }
let launchers: readonly Launcher[] = [];
const listeners = new Set<() => void>();
let counter = 0;
const EMPTY: readonly Launcher[] = [];
const subscribe = (notify: () => void) => { listeners.add(notify); return () => { listeners.delete(notify); }; };
const snapshot = () => launchers;
const serverSnapshot = () => EMPTY;

/** One composer's place in the registry: the n-th composer to mount takes n, so `auto` stacks in the order the page mounted them. The layer owns it for its whole life, whichever surface (bar, icon, circle, tab) is drawn. */
export const newLauncherOwner = (): LauncherOwner => ({ key: {}, seq: ++counter });

const before = (a: { readonly rank: number; readonly seq: number }, b: { readonly rank: number; readonly seq: number }) => a.rank !== b.rank ? a.rank < b.rank : a.seq < b.seq;
/** How many launchers on `corner` sit nearer it than the one with this rank: its place in the stack (0 is the corner's own). */
export function slotOf(all: readonly { readonly corner: Corner | null; readonly rank: number; readonly seq: number; readonly key?: object }[], mine: { readonly key?: object; readonly corner: Corner | null; readonly rank: number; readonly seq: number }): number {
  return mine.corner === null ? 0 : all.filter(other => other.corner === mine.corner && other.key !== mine.key && before(other, mine)).length;
}
const sizeH = (launcher: { readonly h?: number }) => launcher.h ?? CIRCLE_SIZE;
/** The distance in px from the corner's edge to the near side of a launcher: the height of every launcher nearer the corner, and a gap after each (boxes of different heights stack without overlap). */
export function liftOf(all: readonly Launcher[], mine: { readonly key?: object; readonly corner: Corner | null; readonly rank: number; readonly seq: number }): number {
  return mine.corner === null ? 0 : all.filter(other => other.corner === mine.corner && other.key !== mine.key && before(other, mine)).reduce((sum, other) => sum + sizeH(other) + STACK_GAP, 0);
}
/** The distance from the corner's edge to the far side of the launcher in slot `index`, as px. */
export const stackLift = (index: number): number => index * (CIRCLE_SIZE + STACK_GAP);

/** The footprint of the launchers, as the CSS the two variables take: from the window's bottom edge up to the top of the highest stack, and from the inline end edge in. */
export function reserveOf(all: readonly Launcher[]): { readonly block: string | undefined; readonly inline: string | undefined } {
  const bottoms = all.filter(launcher => launcher.reserve && launcher.corner !== null && launcher.corner.startsWith('bottom'));
  const blocks = bottoms.map(launcher => `calc(${launcher.block} + ${liftOf(all, launcher) + sizeH(launcher)}px)`);
  const inlines = bottoms.filter(launcher => launcher.corner?.endsWith('end')).map(launcher => `calc(${launcher.inline} + ${launcher.w ?? CIRCLE_SIZE}px)`);
  const join = (list: readonly string[]) => list.length === 0 ? undefined : list.length === 1 ? list[0] : `max(${list.join(', ')})`;
  return { block: join(blocks), inline: join(inlines) };
}

function publish(): void {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  const { block, inline } = reserveOf(launchers);
  for (const [name, value] of [['--composer-reserve-block', block], ['--composer-reserve-inline', inline]] as const) {
    if (value === undefined) root.style.removeProperty(name); else root.style.setProperty(name, value);
  }
}
const changed = () => { publish(); for (const listener of [...listeners]) listener(); };

/** What the shell's screens keep free at their foot for the launchers: the bar's own reserve, or the launchers' footprint above the tab bar, whichever is more. `config`: the composer was given as a config object (any launcher): a string preset keeps what it always reserved. */
export const circleReserve = (bar: string, config: boolean): string => config ? `max(${bar}, max(0px, calc(var(--composer-reserve-block, 0px) - var(--app-shell-tabbar, 0px))))` : bar;

export interface LauncherSpec { readonly id: string | undefined; readonly corner: Corner | null; readonly stack: 'auto' | number; readonly reserve: boolean; readonly inline: Length; readonly block: Length; readonly w?: number; readonly h?: number }

/** Registers a launcher on its corner while `active` and returns its slot in the stack: 0 nearest the corner, and the px it lifts. Two launchers with one `id`, or one explicit `stack`, are a mistake the console names. `owner`: the layer's own, so the surface it draws can change (bar, icon, tab) without losing its place. */
export function useLauncherSlot(spec: LauncherSpec, active: boolean, owner?: LauncherOwner): { readonly slot: number; readonly lift: number; readonly first: boolean } {
  const [own] = useState<LauncherOwner>(() => owner ?? newLauncherOwner());
  const { key, seq } = owner ?? own;
  const { id, corner, stack, reserve, w, h } = spec;
  const inline = css(spec.inline), block = css(spec.block);
  const rank = typeof stack === 'number' ? stack : seq;
  useLayoutEffect(() => {
    if (!active) return;
    const mine: Launcher = { key, id, corner, rank, seq, reserve, inline, block, ...(w === undefined ? {} : { w }), ...(h === undefined ? {} : { h }) };
    for (const other of launchers) {
      if (other.key === key) continue;
      if (id !== undefined && other.id === id) console.error(`composer: two launchers have the id "${id}": give each its own \`id\` (it names the storage keys and Ctrl+J).`);
      if (typeof stack === 'number' && corner !== null && other.corner === corner && other.rank === stack) console.error(`composer: two launchers on ${corner} share \`at.stack: ${stack}\`: give each its own, or leave it out to stack by mount order.`);
    }
    launchers = [...launchers.filter(other => other.key !== key), mine];
    changed();
    return () => { launchers = launchers.filter(other => other.key !== key); changed(); };
  }, [active, key, id, corner, stack, rank, seq, reserve, inline, block, w, h]);
  return useLauncherPlace(owner ?? own, corner, rank);
}

/** The place a registered launcher has on its corner (read only: the registrant is `useLauncherSlot`). */
export function useLauncherPlace(owner: LauncherOwner, corner: Corner | null, rank: number = owner.seq): { readonly slot: number; readonly lift: number; readonly first: boolean } {
  const all = useSyncExternalStore(subscribe, snapshot, serverSnapshot);
  const { key, seq } = owner;
  const mine = all.find(other => other.key === key);
  const at = { key, corner, rank: mine?.rank ?? rank, seq };
  const first = all.every(other => other.key === key || before(at, other));
  return { slot: slotOf(all, at), lift: liftOf(all, at), first };
}

interface Box { readonly left: number; readonly right: number; readonly top: number; readonly bottom: number }

/** The inline shift, in px, that keeps a box (at its natural place on `corner`) clear of the rectangles: away from the side the corner is on, past each one it would cover. */
export function avoidShift(corner: Corner, rtl: boolean, natural: Box, rects: readonly Box[]): number {
  const right = corner.endsWith('end') !== rtl;
  let shift = 0;
  for (let pass = 0; pass <= rects.length; pass++) {
    const box = right ? { ...natural, left: natural.left - shift, right: natural.right - shift } : { ...natural, left: natural.left + shift, right: natural.right + shift };
    let moved = false;
    for (const rect of rects) {
      if (box.top >= rect.bottom + AVOID_GAP || box.bottom <= rect.top - AVOID_GAP) continue;
      if (box.left >= rect.right + AVOID_GAP || box.right <= rect.left - AVOID_GAP) continue;
      const next = right ? natural.right - rect.left + AVOID_GAP : rect.right - natural.left + AVOID_GAP;
      if (next > shift) { shift = next; moved = true; }
    }
    if (!moved) break;
  }
  return Math.max(0, Math.round(shift));
}

const boxOf = (rect: DOMRect): Box => ({ left: rect.left, right: rect.right, top: rect.top, bottom: rect.bottom });

/**
 * The px an element (a launcher or its panel, drawn with the shift as extra inline offset) moves along the inline axis to keep clear of the `avoid` rectangles. It measures on mount, on a
 * resize and when the page's own boxes change, not on a clock; with nothing to avoid it measures nothing.
 */
export function useAvoidShift(ref: RefObject<HTMLElement | null>, corner: Corner, avoid: readonly Avoid[] | undefined, active: boolean): number {
  const [shift, setShift] = useState(0);
  const shiftRef = useRef(0);
  const list = useRef(avoid);
  useLayoutEffect(() => { list.current = avoid; });
  const count = avoid?.length ?? 0;
  const key = (avoid ?? []).map(entry => typeof entry === 'string' ? entry : '[fn]').join('|');
  const measure = useCallback(() => {
    const element = ref.current;
    const entries = list.current ?? [];
    if (!element || entries.length === 0) { shiftRef.current = 0; setShift(0); return; }
    const rect = element.getBoundingClientRect();
    if (rect.width === 0) return;
    const rtl = getComputedStyle(document.documentElement).direction === 'rtl';
    const right = corner.endsWith('end') !== rtl;
    const current = shiftRef.current;
    const natural: Box = right ? { left: rect.left + current, right: rect.right + current, top: rect.top, bottom: rect.bottom } : { left: rect.left - current, right: rect.right - current, top: rect.top, bottom: rect.bottom };
    const boxes: Box[] = [];
    for (const entry of entries) {
      const found = typeof entry === 'string' ? [...document.querySelectorAll(entry)].filter(match => !element.contains(match) && !match.contains(element)).map(match => match.getBoundingClientRect()) : [entry()];
      for (const box of found) if (box && box.width > 0 && box.height > 0) boxes.push(boxOf(box));
    }
    const next = avoidShift(corner, rtl, natural, boxes);
    shiftRef.current = next;
    setShift(next);
  }, [ref, corner]);
  useEffect(() => {
    if (!active || count === 0) return;
    let frame = 0;
    const later = () => { cancelAnimationFrame(frame); frame = requestAnimationFrame(measure); };
    measure();
    window.addEventListener('resize', later);
    const mutations = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(later);
    mutations?.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['style', 'class', 'hidden', 'data-state'] });
    const sizes = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(later);
    sizes?.observe(document.body);
    return () => { cancelAnimationFrame(frame); window.removeEventListener('resize', later); mutations?.disconnect(); sizes?.disconnect(); };
  }, [active, count, key, measure]);
  // Nothing to avoid, or not on show: no shift (the last measure is kept in the ref and measured again when it is back).
  return active && count > 0 ? shift : 0;
}

'use client';

// `launcher: 'circle'`: a round button in a corner that opens ONE conversation window (the panel) in place, with no folded bar in between. The title row has only what the config allows:
// the annotate toggle (an agent with a pointing tool), Open in full (a `handoff`: the app's full page for the conversation) and Close. The circle carries the unread mark, the needs-you ring,
// a run's pulse and a count of the notes taken; several launchers stack on one corner and step around the page's `avoid` rectangles (`composer-stack`). On a phone the panel is the bottom sheet
// (`CompactSheet`). Host concern: Pi has no layout; the conversation is the layer's one chat, moved into the panel.
import { useContext, useEffect, useLayoutEffect, useRef } from 'react';
import type { CSSProperties, ReactElement } from 'react';
import { SparklesIcon, XIcon } from '../_shared/icons';
import { UnreadMark } from '../_shared/controller-strip';
import { Button } from '@/components/ui/button';
import { AnnotateControl, LauncherNote, OpenFullButton, escapeOwnedElsewhere, useNote } from './composer-actions';
import { cn } from '../utils/utils';
import { ChatSlot, HeaderExtras, HistoryButton, useCircleCollapsed, useTitle } from './agent-chats';
import { VoiceProblem } from './agent-bar-parts';
import { CIRCLE_ACTIONS, configOf } from './composer-config';
import { ComposerClassContext, NoticeSlot } from './float-composer';
import type { Corner } from './composer-config';
import { DEFAULT_OFFSET, css, useAvoidShift, useLauncherSlot } from './composer-stack';
import { composerLabels, shellWords, useInternal } from './layer-context';

const MARGIN = `max(${DEFAULT_OFFSET}px, env(safe-area-inset-bottom, 0px))`;

/** What the circle's geometry reads from the config: its corner and the two distances, the phone's tab bar added when the app gives no block offset. */
function useGeometry() {
  const layer = useInternal();
  const config = configOf(layer);
  const corner: Corner = (config?.at?.place as Corner | undefined) ?? 'bottom-end';
  const given = config?.at?.offset;
  const inline = given?.inline ?? DEFAULT_OFFSET;
  const block = given?.block ?? (layer.expanded ? MARGIN : `calc(${layer.tabbar}px + ${MARGIN})`);
  return { layer, config, corner, inline, block, bottom: corner.startsWith('bottom'), end: corner.endsWith('end'), z: config?.layer ?? 40 };
}

/** The title row's actions in the order the strip's plan gives them. `withClose`: the phone's header draws its own Close. */
export function CircleControls({ withClose = true }: { readonly withClose?: boolean }): ReactElement | null {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  return <span data-testid="composer-controller" className="flex shrink-0 items-center gap-0.5">
    <AnnotateControl />
    <OpenFullButton />
    {withClose && <Button variant="ghost" size="icon" data-testid={CIRCLE_ACTIONS.close.testId} data-action={CIRCLE_ACTIONS.close.id} aria-label={text.close} title={text.close} onClick={layer.close}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>}
  </span>;
}

/** The round launcher: a tap opens the panel. Unread mark, needs-you ring, the run's pulse, the notes taken and the app's status note. */
function Launcher({ hidden, slot, lift }: { readonly hidden: boolean; readonly slot: number; readonly lift: number }): ReactElement {
  const { layer, config, corner, inline, block, bottom, end, z } = useGeometry();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const labels = composerLabels(layer.locale, layer.agent);
  const { signals } = layer;
  const box = useRef<HTMLSpanElement>(null);
  const hostClass = useContext(ComposerClassContext);
  const shift = useAvoidShift(box, corner, config?.avoid, !hidden);
  const Icon = layer.agent?.icon ?? SparklesIcon;
  const note = useNote();
  const label = signals.unread ? `${text.restore} (${signals.unread.label}${signals.unread.count && signals.unread.count > 1 ? `, ${signals.unread.count}` : ''})` : text.restore;
  const working = signals.working === true && !signals.needsYou;
  const style: CSSProperties = { zIndex: z, [end ? 'insetInlineEnd' : 'insetInlineStart']: `calc(${css(inline)} + ${shift}px)`, [bottom ? 'insetBlockEnd' : 'insetBlockStart']: `calc(${css(block)} + ${lift}px)` };
  // Hidden (the panel is open, or the full page is on show) the box keeps its slot in the stack and out of the way: the others do not shift.
  return <span ref={box} hidden={hidden} style={style} data-composer={config?.id} data-testid="composer-circle-box" data-slot-index={slot}
    className={cn('fixed size-13 rounded-pm-round shadow-pm-popover', signals.needsYou && 'ring-2 ring-warning outline-3 outline-warning/25', hostClass)}>
    <Button type="button" size="icon" data-testid="composer-circle" data-needs-you={signals.needsYou || undefined} data-working={working || undefined} aria-busy={working || undefined} aria-label={label} title={text.restore} onClick={() => layer.open('agent')}>
      <Icon aria-hidden="true" />
      {signals.unread && <UnreadMark unread={signals.unread} dot="top-0 right-0" pill="-top-1 -right-2" />}
    </Button>
    {working && <span data-testid="composer-circle-working" aria-hidden="true" className="pointer-events-none absolute -inset-0.5 rounded-pm-round ring-2 ring-primary animate-pulse motion-reduce:animate-none" />}
    {(signals.notes ?? 0) > 0 && <span role="img" aria-label={labels.annotateNotes(signals.notes ?? 0)} data-testid="composer-circle-notes" data-count={signals.notes}
      className="pointer-events-none absolute -bottom-1 -left-1 flex h-5 min-w-5 items-center justify-center rounded-pm-round bg-foreground px-1 text-xs leading-none font-semibold tabular-nums text-background ring-2 ring-background">{signals.notes}</span>}
    <NoticeSlot below={!bottom} className={cn('w-[min(22rem,calc(100vw-2rem))]', end ? 'right-0 left-auto' : 'left-0 right-auto')} />
    {note && <LauncherNote note={note} testId="composer-circle-note" />}
  </span>;
}

/** The wide panel: the layer's one conversation in a window at the launcher's corner, title row, thread and field. */
function Panel({ lift }: { readonly lift: number }): ReactElement {
  const { config, corner, inline, block, bottom, end, z } = useGeometry();
  const { text, title } = useTitle();
  const box = useRef<HTMLDivElement>(null);
  const shift = useAvoidShift(box, corner, config?.avoid, true);
  const style: CSSProperties = { zIndex: z + 1, [end ? 'insetInlineEnd' : 'insetInlineStart']: `calc(${css(inline)} + ${shift}px)`, [bottom ? 'insetBlockEnd' : 'insetBlockStart']: `calc(${css(block)} + ${lift}px)`,
    maxBlockSize: `calc(100dvh - ${css(block)} - ${lift}px - ${DEFAULT_OFFSET}px)` };
  return <div ref={box} data-testid="composer-circle-panel" data-composer={config?.id} data-state="open" role="dialog" aria-label={title} style={style}
    className="app-shell fixed isolate flex h-[36rem] w-[min(24rem,calc(100vw-2rem))] flex-col text-card-foreground [&_[data-boring=pi-chat]>header]:hidden [&_[data-testid=composer-annotate]]:hidden">
    <div aria-hidden="true" data-boring="chrome" className="pointer-events-none absolute inset-0 z-behind rounded-(--radius-3xl) bg-card shadow-pm-popover ring-1 ring-border" />
    <div data-testid="agent-layer-header" className="flex h-13 shrink-0 items-center gap-1.5 px-2 md:px-3">
      <h2 data-testid="agent-layer-title" className="m-0 min-w-0 flex-1 truncate text-sm leading-5 font-semibold tracking-tight">{title}</h2>
      <HistoryButton />
      <HeaderExtras text={text} compact={false} />
      <CircleControls />
    </div>
    <VoiceProblem />
    <ChatSlot />
  </div>;
}

/** Ctrl or Cmd + J (the first launcher answers), Esc (a handled key, a menu or a note bubble keeps its own), and focus: into the field on open, back to the circle on close. */
function CircleController({ open, first }: { readonly open: boolean; readonly first: boolean }): null {
  const layer = useInternal();
  const now = useRef({ open, first, layer });
  useLayoutEffect(() => { now.current = { open, first, layer }; });
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.isComposing || event.keyCode === 229) return;
      const { open: isOpen, first: answers, layer: api } = now.current;
      if ((event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === 'j') {
        if (!answers || api.suspended) return;
        event.preventDefault();
        if (isOpen) api.close(); else api.open('agent');
        return;
      }
      if (event.key !== 'Escape' || !isOpen || !api.expanded) return;
      // Feedback, then a list, menu or file opened over the panel, take their own Escape first; the panel closes last.
      if (escapeOwnedElsewhere(event)) return;
      event.preventDefault();
      api.close();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  const was = useRef(open);
  const { host } = layer;
  useEffect(() => {
    if (was.current === open) return;
    was.current = open;
    let frame = 0, tries = 0;
    const land = () => {
      const held = document.activeElement;
      if (open) {
        // A phone's sheet keeps the keyboard down until the person taps the field.
        if (!now.current.layer.expanded) return;
        const field = host?.querySelector<HTMLElement>('[data-spec=agent] [data-testid=composer-input]');
        field?.focus({ preventScroll: true });
        if (field && document.activeElement === field) return;
      } else {
        if (held && held !== document.body && !held.closest('[data-testid=composer-circle-panel]')) return;
        const circle = document.querySelector<HTMLElement>('[data-testid=composer-circle]');
        circle?.focus({ preventScroll: true });
        if (circle && document.activeElement === circle) return;
      }
      if (++tries < 12) frame = requestAnimationFrame(land);
    };
    land();
    return () => cancelAnimationFrame(frame);
  }, [open, host]);
  return null;
}

/** What `AgentLayer` draws for `launcher: 'circle'`: the launcher, and on a wide screen the panel (the phone's panel is the layer's bottom sheet). */
export function CircleHost(): ReactElement | null {
  const layer = useInternal();
  const collapsed = useCircleCollapsed();
  const { config, corner, inline, block } = useGeometry();
  // One place in the stack for the launcher and its panel: they are the same launcher at two levels.
  const { slot, lift, first } = useLauncherSlot({ id: config?.id, corner, stack: config?.at?.stack ?? 'auto', reserve: config?.reserve !== 'none', inline, block }, layer.agent !== undefined && !layer.suspended, layer.launcherOwner);
  if (!layer.agent) return null;
  const open = layer.snap !== 'closed' && layer.showing === 'agent';
  const shown = open && !collapsed && !layer.suspended;
  return <>
    <CircleController open={shown} first={first} />
    {layer.expanded && shown && <Panel lift={lift} />}
    {!layer.suspended && <Launcher hidden={shown} slot={slot} lift={lift} />}
  </>;
}

'use client';

// The parts every launcher shares, so a config option does the same thing wherever it is given: Open in full (`handoff`), the status `note` on a folded launcher, the pointing tool's control
// in a title row or a field (the built-in toggle, or the app's own render slot `AgentSpec.feedbackSlot`), and the Esc rule between feedback, the pane and menus, and the panel.
// Host concern: Pi has no layout.
import { useEffect, useSyncExternalStore } from 'react';
import type { ReactElement, ReactNode } from 'react';
import { ExternalLinkIcon, MessageSquarePlusIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { Toggle } from '@/components/ui/toggle';
import { clearUnread } from '../agent-bar/use-agent-bar-chat';
import { useComposerFeedback } from '../feedback/feedback-session';
import { cn } from '../utils/utils';
import { CIRCLE_ACTIONS, configOf } from './composer-config';
import { composerLabels, shellWords, useInternal } from './layer-context';
import type { FeedbackSlotContext } from './layer-context';

const NEVER = () => () => {};
const NOOP = () => {};

/** The conversation has no message yet (nothing to continue on a full page). */
export function useEmpty(): boolean {
  const { agent } = useInternal();
  const controller = agent?.controller;
  const read = () => { const snapshot = controller?.getSnapshot(); return !snapshot || ((snapshot.view?.entries?.length ?? 0) === 0 && (snapshot.echo?.length ?? 0) === 0 && (snapshot.outbox?.length ?? 0) === 0); };
  return useSyncExternalStore(controller?.subscribe ?? NEVER, read, read);
}

/** Open in full (`handoff`): what it does, and whether it can now. `run` is undefined when the config gives no hand-off. The person goes where the whole conversation is: what was unread is read, and the panel closes unless the app says it stays. */
export function useOpenFull(): { readonly run: (() => void) | undefined; readonly disabled: boolean } {
  const layer = useInternal();
  const config = configOf(layer);
  const empty = useEmpty();
  const controller = layer.agent?.controller;
  const full = config?.handoff?.openFull ?? config?.on?.openFull;
  if (!full || !controller) return { run: undefined, disabled: false };
  const run = () => {
    const id = String(layer.agent?.chatProps?.conversations?.activeId ?? controller.getSnapshot().conversationId);
    (full as (id: string, context: { readonly empty: boolean }) => void)(id, { empty });
    clearUnread(controller);
    if ((config?.handoff?.then ?? 'close') === 'close') layer.close();
  };
  return { run, disabled: empty && config?.handoff?.allowEmpty !== true };
}

/** The Open in full button of a title row (a circle's panel, a tab's panel, the docked header). Absent without a `handoff`. */
export function OpenFullButton(): ReactElement | null {
  const layer = useInternal();
  const text = shellWords(layer.locale ?? layer.agent?.chatProps?.locale, layer.agent);
  const { run, disabled } = useOpenFull();
  if (!run) return null;
  return <Button variant="ghost" size="icon" data-testid={CIRCLE_ACTIONS.openFull.testId} data-action={CIRCLE_ACTIONS.openFull.id} aria-label={text.openFull} title={text.openFull} disabled={disabled} onClick={run}><ExternalLinkIcon data-icon="inline-start" aria-hidden="true" /></Button>;
}

/** What the app's feedback slot is given: the level and a way to set it, the session's phase and the notes taken, and where the slot is drawn (`field`: the composer's row; `title`: the panel's title row). */
export function useFeedbackSlotContext(where: 'field' | 'title'): FeedbackSlotContext {
  const layer = useInternal();
  const session = layer.agent?.feedback;
  const phase = useSyncExternalStore(session?.subscribe ?? NEVER, () => session?.getSnapshot().phase ?? 'idle', () => 'idle');
  const feedback = useComposerFeedback(session);
  return { level: layer.level, setLevel: layer.setLevel, phase, count: feedback?.count ?? 0, annotate: feedback?.annotate ?? NOOP, where };
}

function SlotContent({ slot, where }: { readonly slot: ReactNode | ((context: FeedbackSlotContext) => ReactNode); readonly where: 'field' | 'title' }): ReactElement {
  const context = useFeedbackSlotContext(where);
  return <span data-testid="composer-feedback-slot" data-where={where} className="contents">{typeof slot === 'function' ? slot(context) : slot}</span>;
}

/** Where the slot is drawn for a launcher: the circle's panel draws the pointing tool in its title row (its field's toggle is hidden); every other launcher draws it in the composer's row. */
export const feedbackWhere = (launcher: 'bar' | 'circle' | 'tab' | 'header'): 'field' | 'title' => launcher === 'circle' ? 'title' : 'field';

/** The pointing tool's control in a circle's title row: the app's render slot when it gives one (`AgentSpec.feedbackSlot`), else the annotate toggle. */
export function AnnotateControl(): ReactElement | null {
  const layer = useInternal();
  const labels = composerLabels(layer.locale, layer.agent);
  const feedback = useComposerFeedback(layer.agent?.feedback);
  const slot = layer.agent?.feedbackSlot;
  if (slot !== undefined && slot !== null && slot !== false) return <SlotContent slot={slot} where="title" />;
  if (!feedback) return null;
  return <Toggle className="min-h-11 min-w-11" data-testid={CIRCLE_ACTIONS.annotate.testId} data-action={CIRCLE_ACTIONS.annotate.id} pressed={feedback.active} aria-label={labels.annotate} title={labels.annotateHint}
    onPressedChange={() => feedback.annotate()}><MessageSquarePlusIcon data-icon="inline-start" aria-hidden="true" /></Toggle>;
}

/** The slot in the composer's row (a launcher with a resting field). The chat's own toggle is hidden when it is there; its notes chip stays (it clears the draft's notes). */
export function FieldFeedbackSlot({ slot }: { readonly slot: ReactNode | ((context: FeedbackSlotContext) => ReactNode) }): ReactElement {
  return <SlotContent slot={slot} where="field" />;
}

/** The app's status text beside a folded launcher (`note`), or null. */
export function useNote(): string | null {
  return useInternal().note;
}

/** The note as a pill. `beside`: to the inline start of a round or tall launcher; `above`: over a bar's field. */
export function LauncherNote({ note, placement = 'beside', className, testId = 'composer-launcher-note' }: { readonly note: string; readonly placement?: 'beside' | 'above'; readonly className?: string | undefined; readonly testId?: string }): ReactElement {
  return <span role="status" data-testid={testId} data-placement={placement}
    className={cn('pointer-events-none absolute rounded-pm-round bg-card px-3 py-1.5 text-xs whitespace-nowrap text-card-foreground shadow-pm-popover ring-1 ring-border', placement === 'beside' ? 'top-1/2 -translate-y-1/2 [inset-inline-end:calc(100%+0.5rem)]' : 'bottom-full mb-2 [inset-inline-end:0]', className)}>{note}</span>;
}

const bubbleOpen = new WeakSet<Event>();
/** Feedback's turn of the Escape, the first of the order: a handled key (annotating ended on it), or one that closed a note bubble. Every launcher's panel asks it before anything else. */
export const escapeInFeedback = (event: KeyboardEvent): boolean => event.defaultPrevented || bubbleOpen.has(event);
/**
 * Records, before anything else sees an Escape (window capture), whether a note bubble was open: the session closes the bubble on that same key, and by the time a panel's own handler runs it
 * would otherwise find the bubble gone and close the panel too. One guard per layer (`AgentLayerProvider`).
 */
export function useEscapeGuard(): void {
  const { agent } = useInternal();
  const session = agent?.feedback;
  useEffect(() => {
    if (!session) return;
    const record = (event: KeyboardEvent) => { if (event.key === 'Escape' && session.getSnapshot().bubble) bubbleOpen.add(event); };
    window.addEventListener('keydown', record, { capture: true });
    return () => window.removeEventListener('keydown', record, { capture: true });
  }, [session]);
}

/**
 * Whether an Escape is owned by something nearer the person than the panel. The order, once, for every launcher: feedback first (its own Escape ends annotating when no note bubble is open,
 * and closes the bubble when one is: either way the key is spent), then the pane, a list, a menu or a dialog opened over the panel, and the panel closes last.
 */
export function escapeOwnedElsewhere(event: KeyboardEvent): boolean {
  if (escapeInFeedback(event)) return true;
  if (document.querySelector('[data-testid=conversations], [data-testid=agent-preview], [role=menu], [role=listbox], [role=alertdialog], [data-boring-overlay]')) return true;
  return event.target instanceof Element && event.target.closest('[aria-haspopup][aria-expanded=true]') !== null;
}

'use client';

// Where the conversation is, as one `Level` for every launcher (`folded`, `open`, `grown`, `full`, `docked`), and the way to take it to another. The layer keeps its own state (the snap, the tray's size,
// the dock mode); this reads it as a level and maps a level back onto it (the equivalence table: open = tray = half = panel; a level the launcher lacks goes to the nearest it has). `level`,
// `defaultLevel`, `on.level` and `feedback.while` of the config work on every launcher through it; the circle's own controlled state (its snap) stays in `AgentLayerProvider`.
import { useCallback, useEffect, useLayoutEffect, useRef } from 'react';
import { useCommenting } from '../feedback/point-mode';
import type { ComposerConfig, Level } from './composer-config';
import { levelsOf } from './composer-config';
import type { AgentMode, AgentSpec, ComposerPlace, ConversationSize, ResolvedComposer, Snap, Which } from './layer-context';

export interface LevelState {
  readonly flags: ResolvedComposer;
  readonly standalone: boolean;
  readonly preset: ComposerConfig;
  readonly hasAgent: boolean;
  readonly expanded: boolean;
  readonly snap: Snap;
  readonly shown: Which;
  readonly trayOpen: boolean;
  readonly dockOpen: boolean;
  readonly dockFloating: boolean;
  readonly size: ConversationSize;
  readonly place: ComposerPlace;
}
export interface LevelActions {
  readonly open: (which?: Which, at?: 'peek' | 'half' | 'full' | 'dock') => void;
  readonly close: () => void;
  readonly setSize: (size: ConversationSize) => void;
  readonly setMode: (mode: AgentMode) => void;
  readonly enterFull: (from?: 'folded' | 'dock') => void;
}

/** The level the layer is at. */
export function levelOf(s: LevelState): Level {
  if (!s.hasAgent) return 'folded';
  const opened = s.snap !== 'closed' && s.snap !== 'peek' && s.shown === 'agent';
  if (s.flags.bar) {
    if (s.place === 'icon') return 'folded';
    if (!s.expanded) return s.snap === 'full' && s.shown === 'agent' ? 'full' : opened ? 'open' : 'folded';
    return s.trayOpen ? s.size : s.dockOpen ? 'docked' : 'folded';
  }
  if (!opened) return 'folded';
  if (s.flags.launcher === 'header' && s.expanded) return s.dockFloating ? 'open' : 'docked';
  return 'open';
}

const ORDER: readonly Level[] = ['folded', 'open', 'grown', 'full', 'docked'];
/** A level the launcher lacks goes to the nearest it has: grown to open, full to grown (or open), docked to open. */
export function clampLevel(level: Level, allowed: readonly Level[]): Level {
  if (allowed.includes(level)) return level;
  const fallbacks: Readonly<Record<Level, readonly Level[]>> = { folded: ['folded'], open: ['open', 'folded'], grown: ['open'], full: ['grown', 'open'], docked: ['full', 'open'] };
  return fallbacks[level].find(one => allowed.includes(one)) ?? ORDER.find(one => allowed.includes(one)) ?? 'folded';
}

/** What a level does to the layer. */
function apply(level: Level, s: LevelState, a: LevelActions): void {
  if (!s.hasAgent) return;
  if (level === 'folded') { a.close(); return; }
  if (!s.flags.bar) { a.open('agent', level === 'docked' && s.flags.launcher === 'header' ? 'dock' : 'half'); return; }
  if (!s.expanded) { a.open('agent', level === 'full' ? 'full' : 'half'); return; }
  if (level === 'docked') { a.open('agent', 'dock'); return; }
  if (s.dockOpen) a.setMode('tray');
  if (level === 'full' && !s.trayOpen) { a.enterFull('folded'); return; }
  a.open('agent');
  a.setSize(level);
}

/** The level, the way to set it, and the config's `level`, `defaultLevel` and `on.level` on every launcher but the circle (whose snap is the layer's own controlled state). */
export function useConfigLevel(state: LevelState, actions: LevelActions, config: ComposerConfig | undefined, standalone: boolean): { readonly level: Level; readonly setLevel: (level: Level) => void } {
  const level = levelOf(state);
  const now = useRef({ state, actions, standalone });
  useLayoutEffect(() => { now.current = { state, actions, standalone }; });
  const allowed = levelsOf(state.preset, standalone);
  const setLevel = useCallback((next: Level) => {
    const { state: s, actions: a, standalone: alone } = now.current;
    apply(clampLevel(next, levelsOf(s.preset, alone)), s, a);
  }, []);
  const circle = state.flags.circle;
  const known = useRef<{ level: Level; given: Level | undefined; started: boolean; timer: ReturnType<typeof setTimeout> | undefined }>({ level, given: config?.level, started: false, timer: undefined });
  const given = config?.level, start = config?.defaultLevel, report = config?.on?.level;
  const latest = useRef({ given, level, allowed });
  useLayoutEffect(() => { latest.current = { given, level, allowed }; });
  useEffect(() => () => clearTimeout(known.current.timer), []);
  useEffect(() => {
    if (!config || circle || !state.hasAgent) return;
    const was = known.current;
    // The first look: the app's level, or its default, is where the conversation starts.
    if (!was.started) {
      was.started = true; was.given = given; was.level = level;
      const first = given ?? start;
      if (first !== undefined && clampLevel(first, allowed) !== level) { was.level = clampLevel(first, allowed); setLevel(first); }
      return;
    }
    // The app set a new level: the layer goes there.
    if (given !== undefined && given !== was.given) { was.given = given; was.level = clampLevel(given, allowed); if (was.level !== level) setLevel(given); return; }
    // The person moved it: the app is told; a controlled level the app does not take comes back (checked once the app has drawn again).
    if (level !== was.level) {
      was.level = level;
      report?.(level);
      if (given !== undefined) {
        clearTimeout(was.timer);
        was.timer = setTimeout(() => {
          const now = latest.current;
          if (now.given !== undefined && clampLevel(now.given, now.allowed) !== now.level) { known.current.level = clampLevel(now.given, now.allowed); setLevel(now.given); }
        }, 0);
      }
    }
  });
  return { level, setLevel };
}

/** `feedback.while`: the level taken while annotating, and back to the one before when it ends. Only when the config names one (a circle's panel steps aside by default: `useCircleCollapsed`). */
export function useFeedbackWhile(config: ComposerConfig | undefined, feedback: AgentSpec['feedback'], level: Level, setLevel: (level: Level) => void): void {
  const annotating = useCommenting(feedback);
  const taken = config?.feedback?.while;
  const before = useRef<Level | undefined>(undefined);
  const latest = useRef({ level, setLevel });
  useLayoutEffect(() => { latest.current = { level, setLevel }; });
  useEffect(() => {
    if (taken === undefined || config?.launcher === 'circle') return;
    if (annotating && before.current === undefined) { before.current = latest.current.level; latest.current.setLevel(taken); }
    else if (!annotating && before.current !== undefined) { const back = before.current; before.current = undefined; latest.current.setLevel(back); }
  }, [annotating, taken, config?.launcher]);
}

'use client';

// Where a launcher that floats on a corner (the floating bar, its folded icon, the explore tab) is drawn when the composer is a config object: `at.offset`, `at.stack`, `avoid`, `layer`, and the
// footprint it publishes (`reserve`). The circle does the same for itself (`composer-circle`); a composer given as a string keeps the styles it always had (`style` is `undefined`).
import type { CSSProperties, RefObject } from 'react';
import { configOf } from './composer-config';
import type { Corner, Length } from './composer-config';
import { css, useAvoidShift, useLauncherSlot } from './composer-stack';
import { useInternal } from './layer-context';

export interface CornerPlace {
  /** The inline and block insets and the z-index, or `undefined` for a composer that is not a config object (the caller's own styles). */
  readonly style: CSSProperties | undefined;
  /** The px the launcher lifts above the others nearer its corner. */
  readonly lift: number;
  /** The first launcher of the page answers Ctrl or Cmd + J. */
  readonly first: boolean;
}

/**
 * Registers the launcher on `corner` while `active` (`null`: it sits in the page's flow or is dragged free, so it takes no corner) and gives its style. `defaults` are the distances of the launcher
 * when the config gives none; `size` is its box in px, for the stack and the reserve. One composer is one registrant at a time: its bar, its icon and its tab are never drawn together.
 */
export function useCornerPlace({ ref, corner, defaults, size, active }: { readonly ref: RefObject<HTMLElement | null>; readonly corner: Corner | null; readonly defaults: { readonly inline: Length; readonly block: Length }; readonly size: { readonly w: number; readonly h: number }; readonly active: boolean }): CornerPlace {
  const layer = useInternal();
  const config = configOf(layer);
  const inline = config?.at?.offset?.inline ?? defaults.inline;
  const block = config?.at?.offset?.block ?? defaults.block;
  const registered = config !== undefined && active;
  const { lift, first } = useLauncherSlot({ id: config?.id, corner, stack: config?.at?.stack ?? 'auto', reserve: config?.reserve !== 'none', inline, block, w: size.w, h: size.h }, registered, layer.launcherOwner);
  const shift = useAvoidShift(ref, corner ?? 'bottom-end', config?.avoid, registered && corner !== null);
  if (!config || corner === null) return { style: undefined, lift: 0, first };
  const bottom = corner.startsWith('bottom'), end = corner.endsWith('end');
  return { lift, first, style: { ...(config.layer === undefined ? {} : { zIndex: config.layer }), [end ? 'insetInlineEnd' : 'insetInlineStart']: `calc(${css(inline)} + ${shift}px)`, [bottom ? 'insetBlockEnd' : 'insetBlockStart']: `calc(${css(block)} + ${lift}px)` } };
}

/** The z-index a config gives a launcher's own box (`layer`), as a style; nothing when it gives none. A panel sits one above its launcher. */
export function layerStyle(layer: { readonly composerConfig: { readonly current: unknown } }, above = 0): CSSProperties | undefined {
  const z = configOf(layer)?.layer;
  return z === undefined ? undefined : { zIndex: z + above };
}

'use client';

// The resizable left pane (D-1898), owned by the kit and independent of the host's shadcn sidebar: the host's SidebarProvider takes no kit-only
// prop. The width is the `--sidebar-width` custom property on the provider's wrapper (the theme token the sidebar already reads), so the host's
// own sidebar needs no change; the rail becomes the drag handle (role separator, arrow keys, double-click reset). Fine pointers only: on touch
// the rail stays the host's toggle and the phone sheet keeps `--sidebar-width-mobile`.
// The width the person chose is kept in rem in localStorage under the kit's own key, which names the app and, when it is known, the person: another
// person on the same browser, or another app on the same origin, starts from the theme's width. Every storage access is guarded: a blocked or
// throwing store only means the width is not remembered.
// An app that renders SidebarProvider itself uses ResizableSidebarProvider and ResizableRail in its place: the same behaviour, no AppShell.
import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type CSSProperties } from 'react';
import { SidebarProvider, SidebarRail, useSidebar } from '@/components/ui/sidebar';
import { cn } from '../utils/utils';

export const SIDEBAR_WIDTH_KEY = 'boring-ui:sidebar-width';
/** The storage key of one sidebar setting for an app and a person: `boring-ui:sidebar-<setting>:<app>:<person>`; with no person, `:<app>`; with neither, the bare prefix. The person is never dropped: with no app the app part is empty. The width (D-1898) and the open state (D-1909) share this one scheme; the open state of the `screen` layout is its own setting, `open-screen` (D-1919). */
export function sidebarKey(setting: 'width' | 'open' | 'open-screen' | 'pin' | 'agent-mode' | 'agent-mode-screen' | 'agent-pane' | 'composer-place' | 'composer-pos' | 'composer-height' | 'explore-width', app?: string, person?: string, composer?: string): string {
  const part = (value: string | undefined) => `:${encodeURIComponent(value ?? '')}`;
  // A composer with an `id` (several agents on one page) keeps its own keys; without one the keys are what they always were.
  return `boring-ui:sidebar-${setting}${app || person ? part(app) : ''}${person ? part(person) : ''}${composer ? `#${encodeURIComponent(composer)}` : ''}`;
}
/** The stored width's key: `boring-ui:sidebar-width:<app>:<person>`. */
export function sidebarWidthKey(app?: string, person?: string): string {
  return sidebarKey('width', app, person);
}
/** The least width (D-1969): 14rem = 224px, so item names are not truncated. The one place; a stored narrower width is clamped to it on read. */
const MIN_REM = 14;
const MAX_REM = 28;
const STEP_REM = 1;

export type SidebarResizable = boolean | { readonly min?: number; readonly max?: number };

export interface SidebarResize {
  /** The storage key of this app and person: a drag started under another key is cancelled. */
  readonly storageKey: string;
  readonly minRem: number;
  readonly maxRem: number;
  /** The wrapper's style: the chosen `--sidebar-width`, or none (the theme's width). */
  readonly style: CSSProperties | undefined;
  readonly widthRem: number | null;
  readonly set: (rem: number, commit: boolean) => void;
  readonly reset: () => void;
}

function readStored(key: string, min: number, max: number): number | null {
  try {
    const stored = window.localStorage.getItem(key) ?? '';
    // The whole value must be a number: `20garbage` is not 20rem.
    return /^\d+(\.\d+)?$/.test(stored) ? Math.min(max, Math.max(min, Number(stored))) : null;
  } catch {
    return null;
  }
}

function writeStored(key: string, rem: number | null) {
  try {
    if (rem === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, String(rem));
  } catch {
    // storage unavailable: the width lasts for this visit only
  }
}

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;
const rootRem = () => Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
const roundRem = (rem: number) => Math.round(rem * 10) / 10;

/** The resize state of the shell. `undefined` while `resizable` is off or the pointer is not fine. Call it where the SidebarProvider is rendered. */
export function useSidebarResize(resizable: SidebarResizable | undefined, identity: { readonly app?: string | undefined; readonly person?: string | undefined } = {}): SidebarResize | undefined {
  const storageKey = sidebarWidthKey(identity.app, identity.person);
  const bounds = typeof resizable === 'object' ? resizable : {};
  const minRem = bounds.min ?? MIN_REM;
  const maxRem = Math.max(minRem, bounds.max ?? MAX_REM);
  const [fine, setFine] = useState(false);
  const [widthRem, setWidthRem] = useState<number | null>(null);
  const on = Boolean(resizable);
  useIsoLayoutEffect(() => {
    if (!on) return;
    const query = window.matchMedia('(pointer: fine)');
    const sync = () => setFine(query.matches);
    sync();
    query.addEventListener('change', sync);
    return () => query.removeEventListener('change', sync);
  }, [on]);
  const active = on && fine;
  useIsoLayoutEffect(() => { if (active) setWidthRem(readStored(storageKey, minRem, maxRem)); }, [active, storageKey, minRem, maxRem]);
  const set = useCallback((rem: number, commit: boolean) => {
    const next = Math.min(maxRem, Math.max(minRem, rem));
    setWidthRem(next);
    if (commit) writeStored(storageKey, next);
  }, [storageKey, minRem, maxRem]);
  const reset = useCallback(() => { setWidthRem(null); writeStored(storageKey, null); }, [storageKey]);
  const style = useMemo<CSSProperties | undefined>(() => (active && widthRem !== null ? ({ '--sidebar-width': `${widthRem}rem` } as CSSProperties) : undefined), [active, widthRem]);
  return useMemo(() => (active ? { storageKey, minRem, maxRem, style, widthRem, set, reset } : undefined), [active, storageKey, minRem, maxRem, style, widthRem, set, reset]);
}

// The rail's look is the host sidebar's own (same classes), so the handle sits exactly where the toggle did.
const RAIL = cn(
  'absolute inset-y-0 z-lifted hidden w-4 transition-all ease-linear group-data-[side=left]:-right-4 group-data-[side=right]:left-0 after:absolute after:inset-y-0 after:start-1/2 after:w-[2px] hover:after:bg-sidebar-border sm:flex ltr:-translate-x-1/2 rtl:-translate-x-1/2',
  'group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full hover:group-data-[collapsible=offcanvas]:bg-sidebar',
  '[[data-side=left][data-collapsible=offcanvas]_&]:-right-2 [[data-side=right][data-collapsible=offcanvas]_&]:-left-2',
  'cursor-col-resize touch-none',
);

const ResizeContext = createContext<SidebarResize | undefined>(undefined);

export type ResizableSidebarProviderProps = ComponentProps<typeof SidebarProvider> & {
  /** `true` or `{ min, max }` in rem (12 and 28). Off: this is the host's SidebarProvider. */
  readonly resizable?: SidebarResizable | undefined;
  /** The app's name and the signed-in person's id or email: the stored width is theirs. With no person it is the app's. */
  readonly app?: string | undefined;
  readonly person?: string | undefined;
};

/** The host's SidebarProvider with a resizable left pane, for an app that renders the provider itself. Put `ResizableRail` in the Sidebar where `SidebarRail` was. */
export function ResizableSidebarProvider({ resizable, app, person, style, ...props }: ResizableSidebarProviderProps) {
  const resize = useSidebarResize(resizable, { app, person });
  return <ResizeContext value={resize}><SidebarProvider style={resize?.style ? { ...style, ...resize.style } : style} {...props} /></ResizeContext>;
}

/** The rail of the sidebar: the host's toggle, or, under a resizable provider (fine pointer, expanded, wide), the drag handle. */
export function ResizableRail() {
  const resize = useContext(ResizeContext);
  const { isMobile, state } = useSidebar();
  if (!resize || isMobile || state !== 'expanded') return <SidebarRail />;
  return <ResizeHandle resize={resize} />;
}

function ResizeHandle({ resize }: { readonly resize: SidebarResize }) {
  const drag = useRef<{ x: number; rem: number; sign: number; moved: boolean } | null>(null);
  const [measured, setMeasured] = useState<number | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  const gap = () => ref.current?.closest('[data-slot=sidebar-wrapper]')?.querySelector<HTMLElement>('[data-slot=sidebar-gap]') ?? null;
  // The width in rem: the chosen one, else what the theme gives (the gap's own width).
  const current = () => resize.widthRem ?? (gap()?.getBoundingClientRect().width ?? 0) / rootRem();
  // The theme's width, until one is chosen: read from the gap in an observer callback (a subscription), not in an effect body.
  useEffect(() => {
    const element = ref.current?.closest('[data-slot=sidebar-wrapper]')?.querySelector<HTMLElement>('[data-slot=sidebar-gap]');
    if (!element || typeof ResizeObserver === 'undefined') return undefined;
    const observer = new ResizeObserver(() => setMeasured(element.getBoundingClientRect().width / rootRem()));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const direction = () => (ref.current?.closest('[data-side]')?.getAttribute('data-side') === 'right' ? -1 : 1);
  const to = (start: { x: number; rem: number; sign: number }, clientX: number) => start.rem + ((clientX - start.x) * start.sign) / rootRem();
  // The sidebar animates its width; following the pointer must not lag behind it. The inline transitions are put back as they were when the drag
  // ends however it ends: release, cancel, a lost pointer capture, or the handle leaving (Ctrl+B mid-drag collapses the sidebar and unmounts it).
  const held = useRef<Array<readonly [HTMLElement, string]>>([]);
  const settle = useCallback(() => {
    for (const [element, transition] of held.current) element.style.transition = transition;
    held.current = [];
  }, []);
  const follow = (on: boolean) => {
    if (!on) { settle(); return; }
    settle();
    const wrapper = ref.current?.closest('[data-slot=sidebar-wrapper]');
    for (const element of wrapper?.querySelectorAll<HTMLElement>('[data-slot=sidebar-gap], [data-slot=sidebar-container]') ?? []) {
      held.current.push([element, element.style.transition]);
      element.style.transition = 'none';
    }
  };
  // The drag belongs to the key it started under: if the person (or app) changes mid-drag, it is cancelled, so the width is never written under the
  // other key. The hook has already read that key's own width. The same cleanup puts the transitions back when the handle leaves.
  useEffect(() => () => { drag.current = null; settle(); }, [resize.storageKey, settle]);
  return <div
    ref={ref}
    data-sidebar="rail"
    data-slot="sidebar-rail"
    role="separator"
    aria-orientation="vertical"
    aria-label="Resize sidebar"
    aria-valuemin={resize.minRem}
    aria-valuemax={resize.maxRem}
    aria-valuenow={roundRem(resize.widthRem ?? measured ?? 0) || undefined}
    tabIndex={0}
    title="Resize sidebar (double-click to reset)"
    className={RAIL}
    onPointerDown={event => {
      if (event.button !== 0) return;
      event.currentTarget.setPointerCapture(event.pointerId);
      drag.current = { x: event.clientX, rem: current(), sign: direction(), moved: false };
      follow(true);
    }}
    onPointerMove={event => {
      const start = drag.current;
      if (!start) return;
      start.moved = true;
      resize.set(to(start, event.clientX), false);
    }}
    onPointerUp={event => {
      const start = drag.current;
      drag.current = null;
      follow(false);
      if (start?.moved) resize.set(to(start, event.clientX), true);
    }}
    onPointerCancel={() => { drag.current = null; follow(false); }}
    onLostPointerCapture={() => { drag.current = null; follow(false); }}
    onDoubleClick={resize.reset}
    onKeyDown={event => {
      const grow = direction() === 1 ? 'ArrowRight' : 'ArrowLeft';
      const shrink = grow === 'ArrowRight' ? 'ArrowLeft' : 'ArrowRight';
      let rem: number | null = null;
      if (event.key === grow) rem = current() + STEP_REM;
      else if (event.key === shrink) rem = current() - STEP_REM;
      else if (event.key === 'Home') rem = resize.minRem;
      else if (event.key === 'End') rem = resize.maxRem;
      if (rem === null) return;
      event.preventDefault();
      resize.set(rem, true);
    }}
  />;
}

'use client';

// Whether the wide-screen left pane is open (D-1909), owned by the kit around the host's SidebarProvider (controlled `open` / `onOpenChange`; the stock
// sidebar is untouched). The person's last choice (Ctrl+B, the trigger, the rail) is kept in localStorage under the same key family and identity as the
// width (`sidebarKey('open', app, person)`, and `'open-screen'` for the `screen` layout, so a fold in one layout is not read by the other (D-1919): "1" or "0", anything else ignored). With no stored choice the first visit decides once, at mount (and when the
// person changes): at 1280px and wider the pane opens when the screen on show has a `sidebar` content, else it is the icon rail; narrower, today's default.
// Navigating between screens never re-decides. Every storage access is guarded; a blocked store only means the choice is not remembered. Written on change
// only, under the key of the person who made it.
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { sidebarKey } from './sidebar-resize';

/** The width from which a first visit opens the pane for a screen that has a sidebar. */
export const SIDEBAR_FIRST_VISIT_MIN = 1280;

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

function readOpen(key: string): boolean | null {
  try {
    const stored = window.localStorage.getItem(key);
    return stored === '1' ? true : stored === '0' ? false : null;
  } catch {
    return null;
  }
}

function writeOpen(key: string, open: boolean) {
  try {
    window.localStorage.setItem(key, open ? '1' : '0');
  } catch {
    // storage unavailable: the choice lasts for this visit only
  }
}

function wide(): boolean {
  try {
    return window.matchMedia(`(min-width: ${SIDEBAR_FIRST_VISIT_MIN}px)`).matches;
  } catch {
    return false;
  }
}

/**
 * The controlled `open` and `onOpenChange` of the SidebarProvider. `fallback` is today's default (the pane is open on the `screen` layout); `hasSidebar` is whether
 * the screen on show has a `sidebar` content. Off (`enabled` false): `undefined`, and the provider keeps its own `defaultOpen`.
 */
export function useSidebarOpen(enabled: boolean, identity: { readonly app?: string | undefined; readonly person?: string | undefined }, screenLayout: boolean, fallback: boolean, hasSidebar: boolean) {
  const key = sidebarKey(screenLayout ? 'open-screen' : 'open', identity.app, identity.person);
  const [open, setOpen] = useState(fallback);
  const latest = useRef({ fallback, hasSidebar });
  // The screen on show and today's default as of the last commit: read when the person (key) changes, not a dependency of it.
  useIsoLayoutEffect(() => { latest.current = { fallback, hasSidebar }; }, [fallback, hasSidebar]);
  // Mount, or another person: that person's stored choice, else the first-visit default. Not on a change of screen.
  useIsoLayoutEffect(() => {
    if (!enabled) return;
    const choice = readOpen(key);
    const now = latest.current;
    setOpen(choice ?? (wide() ? now.fallback || now.hasSidebar : now.fallback));
  }, [enabled, key]);
  const onOpenChange = useCallback((next: boolean) => {
    setOpen(next);
    writeOpen(key, next);
  }, [key]);
  return enabled ? { open, onOpenChange } : undefined;
}

/**
 * The pin of the hover rail (D-2010): kept open whatever the pointer and focus do. Stored under `sidebarKey('pin', app, person)` ("1" or "0", anything else ignored),
 * read at mount and when the person changes, written on a change only. `enabled` is false off the hover rail: never pinned, nothing read or written.
 */
export function useSidebarPin(enabled: boolean, identity: { readonly app?: string | undefined; readonly person?: string | undefined }) {
  const key = sidebarKey('pin', identity.app, identity.person);
  const [pinned, setPinned] = useState(false);
  useIsoLayoutEffect(() => { setPinned(enabled && readOpen(key) === true); }, [enabled, key]);
  const set = useCallback((next: boolean) => {
    setPinned(next);
    writeOpen(key, next);
  }, [key]);
  return { pinned: enabled && pinned, set };
}

